INSERT INTO `especes` (`id`, `nom_francais`, `autres_noms_francais`, `nom_anglais`, `autres_noms_anglais`, `nom_scientifique`, `commentaires`, `description`, `repartition`, `etat_situation`, `habitat`, `alimentation`, `reproduction`, `comportement`, `menaces`, `statuts_des_populations`, `rang_S`, `statut_LEMV`, `competence_principale`, `groupe_id`) VALUES
(4, 'Salamandre sombre des montagnes, pop. des Appalaches', 'salamandre sombre des montagnes, pop. 2; salamandre sombre des montagnes, pop. des Grands Lacs et du Saint-Laurent', 'Allegheny Mountain Dusky Salamander - Appalachian population', 'Allegheny Mountain Dusky Salamander - Great Lakes - St. Lawrence Population', 'Desmognathus ochrophaeus pop. 2', 'Le nom français \"salamandre sombre des montagnes\" et le nom anglais \"Mountain Dusky Salamander\" ne sont pas assez précis pour désigner cette espèce, car il existe d\'autres salamandres sombres des montagnes en Amérique du Nord. Toutefois, le statut d\'espèce menacée a été attribué au nom français simplifié \"salamandre sombre des montagnes\" et non à son nom précis \"salamandre sombre des montagnes Allegheny\".', '<p>La salamandre sombre des montagnes est la plus rare des salamandres du Québec. Elle n’a pas de poumons ni de branchies : sa peau perméable à l’air et à l’eau lui permet de respirer. Pour échapper aux prédateurs, elle peut se départir d’un bout de sa queue. Cette dernière se régénérera avec le temps.</p>', '<p>La salamandre sombre des montagnes vit uniquement dans l’est de l’Amérique du Nord. Elle se trouve principalement le long de la chaîne de montagnes des Appalaches aux États‑Unis.</p><p>\r\n\r\nAu Canada, elle occupe quelques ruisseaux et résurgences (réapparition en surface d’un cours d’eau après un parcours souterrain) du versant nord de la colline de Covey Hill, au Québec. Elle fréquente aussi deux cours d’eau des gorges du Niagara, en Ontario.</p><p>\r\n\r\n Au Québec, l’espèce se trouve uniquement en terres privées dans les municipalités de Franklin et de Havelock.</p>', '<p>Découverte en 1988 au Québec, la salamandre sombre des montagnes est la plus rare parmi nos 10 espèces de salamandres. En 2020, le nombre de populations de salamandres sombres des montagnes était estimé à 25 pour l’ensemble du Québec. Comme près de 70 % d’entre elles sont très peu documentées, il est difficile d’en évaluer les chances de survie à moyen terme. Toutefois, près du quart des populations auraient de bonnes chances de persister dans les 20 prochaines années, si les conditions actuelles sont maintenues ou améliorées.</p>', '<p>La salamandre sombre des montagnes vit près des sources, des dépressions humides et des petits ruisseaux d’eau claire et froide situés en montagne. Elle affectionne les cours d’eau intermittents et les milieux dotés d’un sol mal drainé. L’hiver, elle se réfugie sous les pierres ou dans le sol.</p>', '<p>La salamandre sombre des montagnes se nourrit surtout de fourmis, de larves de mouches et de papillons, d’araignées et d’un peu de végétation.</p>', '<p>L’accouplement se déroule en milieu terrestre au printemps et à l’automne. La ponte se déroule au printemps ou à l’été. La femelle dépose ses œufs en une petite masse ressemblant à une grappe de raisins dans une dépression du sol, généralement protégée sous un abri, comme une roche. Le nombre d’œufs pondus varie de 8 à 24. Les larves sont aquatiques et se métamorphosent à la fin du premier été ou l’été suivant, après un hiver passé en milieu aquatique.</p><p>\r\nCette espèce peut s’accoupler avec la salamandre sombre du Nord pour produire des individus fertiles.</p>', NULL, '<p>Les menaces qui pèsent sur la salamandre sombre des montagnes au Québec sont :</p>\r\n<ul>\r\n  <li>le captage de l’eau souterraine qui dégrade la qualité des milieux naturels par la diminution de la disponibilité en eau de son habitat;</li>\r\n  <li>la sédimentation et la pollution qui altèrent la qualité de l’eau;</li>\r\n  <li>l’exploitation forestière qui entraine l’élimination du couvert forestier, ce qui influence négativement les conditions d’humidité et de température optimales pour l’espèce.</li>\r\n</ul>\r\n\r\n<p>Comme elle respire seulement par la peau, la salamandre sombre des montagnes est particulièrement sensible à toute modification ou détérioration de son habitat. De plus, elle ne tolère pas les milieux secs.</p>\r\n', 'Toute l\'année', 'S2S3', 'Menacée', 'Québec', 4),
(13, 'Rainette faux-grillon de l\'Ouest', 'rainette faux-grillon de l\'Ouest, pop. Des Grands-Lac / Saint-Laurent et Bouclier canadien; rainette faux-grillon; rainette faux-criquet', 'Western Chorus Frog', 'Western Chorus Frog - Great Lakes - St. Lawrence - Canadian Shield Population; Swamp Cricket Frog; Striped Chorus Frog; Pickering Frog', 'Pseudacris triseriata', 'Avant les années 1990, il était convenu que quatre sous-espèces de rainettes faux-grillon de l’Ouest existaient: P. triseriata triseriata, P. triseriata maculata, P. triseriata feriarum et P. triseriata kalmi. Les entités taxinomiques ont été par la suite élevées au rang d’espèce (P. triseriata, P. maculata, P. feriarum. P. kalmi) plutôt que de sous-espèce. Des analyses génétiques récentes indiquent que l’ADN mitochondrial de rainettes faux-grillon qui vivent dans le sud du Québec correspondrait à celui de la rainette faux-grillon boréale (Pseudacris maculata) et non de la rainette faux-grillon de l’Ouest (Pseudacris triseriata). De nouvelles analyses génétiques sont en cours pour confirmer les résultats.', '<p>La rainette faux-grillon de l’Ouest est une petite grenouille munie de ventouses au bout des doigts. Elle est la première à chanter au printemps.</p>', '<p>La rainette faux-grillon de l’Ouest vit uniquement en Amérique du Nord. Au Canada, elle se trouve seulement dans les basses terres du sud de l’Ontario et du sud du Québec. Au Québec, elle est présente en Outaouais et en Montérégie.</p>', '<p>Dans les années 1950, la rainette faux-grillon de l’Ouest était abondante, commune et largement répartie en Montérégie. Elle était observée de la vallée de l’Outaouais jusqu’aux contreforts des Appalaches et à l’ouest de la rivière Richelieu. Depuis, l’espèce a subi un déclin important. Les experts estiment que plus de 15 % des sites de reproduction de la Montérégie et 30 % de ceux de l’Outaouais ont été détruits entre 2004 et 2009.</p>\r\n\r\n<p>En l\'absence de mesures de protection renforcées, le déclin de l’espèce risque de se poursuivre. D’autre part, l’état de situation de la rainette faux-grillon de l’Ouest laisse croire que moins du quart des populations seraient capables de survivre à moyen terme si les conditions actuelles sont maintenues.</p>\r\n\r\n<p>Des analyses génétiques laissent supposer que les rainettes faux-grillon du Québec et certaines populations de l’Ontario appartiennent à une autre espèce, à savoir la rainette faux-grillon boréale (Pseudacris maculata), mais ces résultats ont récemment été contestés. Peu importe la conclusion à venir, la situation des populations de rainettes faux-grillon reste précaire au Québec.</p>', '<p>La rainette faux-grillon de l’Ouest fréquente les clairières, les prairies humides, les friches, les plantations d’arbustes humides et les milieux agricoles de faible intensité (ex. : cultures de foin ou pâturages).</p>\r\n\r\n<p>Ces habitats doivent comprendre des milieux humides qui s’assèchent en été, comme des marais, des marécages et des fossés de drainage.</p>\r\n\r\n<p>L’hiver, elle peut survivre jusqu’à -5 à -7 °C grâce aux réserves de glycogène contenues dans son foie. Elle hiberne à la surface du sol, cachée sous des feuilles, des troncs d’arbres morts, des racines ou des pierres.</p>\r\n', '<p>Sous forme de têtard, la rainette faux-grillon de l’Ouest est herbivore et se nourrit d’algues. Une fois adulte, elle mange surtout des insectes, comme des coléoptères, des mouches ou des fourmis ainsi que des araignées.</p>', '<p>La rainette faux-grillon de l’Ouest se reproduit tôt au printemps et pond ses œufs en petites grappes qui adhèrent à la végétation aquatique. L’incubation prend moins de 15 jours et les têtards se métamorphosent en adulte après un ou deux mois. Cette adaptation lui permet de se reproduire dans des milieux aquatiques temporaires qui s’assèchent généralement en juillet. Ces milieux ne sont pas accessibles aux poissons, qui sont des prédateurs pour les têtards.</p>', NULL, '<p>Les menaces qui pèsent sur la rainette faux-grillon de l’Ouest au Québec sont :</p>\r\n<ul>\r\n  <li>la destruction, la dégradation et la fragmentation de son habitat, notamment à cause de l’urbanisation et l’intensification de l’agriculture;</li>\r\n  <li>la modification de l’écoulement naturel de l’eau par les barrages de castor ou le drainage;</li>\r\n  <li>les espèces exotiques envahissantes, dont le nerprun cathartique, une plante néfaste pour les têtards (par la production d’émodine);</li>\r\n  <li>les fertilisants et les pesticides.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2', 'Menacée', 'Québec', 4),
(27, 'Grèbe esclavon', 'grèbe esclavon, pop. des îles de la Madeleine; grèbe cornu; grèbe oreillard; grèbe de l\'esclavonie', 'Horned Grebe', 'Slavonian Grebe; Pink-eyed Diver; Dusky Grebe; Little White Diver', 'Podiceps auritus', '', '<p>Le grèbe esclavon, autrefois connu sous le nom de grèbe cornu, est un oiseau aquatique de taille moyenne. Au Québec, cette espèce est désignée menacée.</p>', '<p>Le grèbe esclavon niche dans l’Ouest canadien, rarement à l’est du lac Supérieur. Il se concentre surtout en Colombie‑Britannique, au Yukon, aux Territoires du Nord‑Ouest, au sud du Nunavut, dans les Prairies et au nord‑ouest de l’Ontario. Il est rare au Québec, où sa répartition est restreinte et isolée des autres sites fréquentés au Canada.</p><p>\r\n\r\nSa nidification au Québec n’est rapportée qu’aux îles de la Madeleine, où une population reproductrice est confirmée depuis plus de 100 ans. Dans la province, le grèbe esclavon est plus commun lors des périodes de migration à l’automne lorsque les populations de l’Ouest fréquentent le Saint-Laurent.</p><p>\r\n\r\nLa majorité des grèbes esclavons hivernent en eau salée sur les côtes de l\'Atlantique jusqu’à la limite sud des États‑Unis. Une autre partie de la population hiverne sur les côtes du Pacifique. Un très petit nombre pourrait également passer l’hiver dans les terres intérieures jusqu’aux Grands Lacs.</p>', '<p>Bien que la population de l’Ouest compte entre 200 000 et 500 000 individus, les recensements ont révélé une diminution de 45 % des effectifs depuis les années 1960.</p>\r\n\r\n<p>Au Québec, la taille de la population de grèbe esclavon demeure très faible. La population a grandement chuté au cours des dernières décennies et elle est actuellement estimée à une quinzaine de couples. Depuis 1993, un maximum de 25 couples a été observé durant la même saison de nidification.</p>', '<p>Le grèbe esclavon niche principalement dans les zones tempérées, mais il fréquente également les zones boréales et subarctiques. Il niche généralement en eau douce. À l’occasion, il fréquente les eaux saumâtres des petits étangs semi-permanents ou permanents. Il peut aussi nicher dans des marais et des baies peu profondes aux abords des lacs. Il choisit des secteurs d’eaux libres riches en végétation émergente qui fournissent les matériaux nécessaires à la construction et au camouflage de son nid.</p>', '<p>Le grèbe esclavon est un oiseau plongeur. Il capture ses proies et s’en nourrit sous l’eau. L’été, son alimentation est principalement composée d’insectes aquatiques et de poissons. L’hiver, il mange des poissons, mais également des crustacés et des vers marins (polychètes).</p>', '<p>Aux îles de la Madeleine, le grèbe esclavon construit son nid principalement avec du scirpe, une plante de milieux humides, puis le surveille en quasi permanence et défend farouchement son territoire.</p>\r\n\r\n<p>La femelle pond de 3 à 6 œufs et les couve avec le mâle.</p>', NULL, '<p>Les principales menaces qui pèsent sur le grèbe esclavon sont :</p>\r\n<ul>\r\n  <li>la destruction des milieux humides;</li>\r\n  <li>la compétition avec le grèbe à bec bigarré;</li>\r\n  <li>les récoltes accidentelles lors de la chasse à la sauvagine (prises accessoires) et de la pêche commerciale;</li>\r\n  <li>les déversements pétroliers dans les aires d’hivernage;</li>\r\n  <li>le dérangement par les humains lors d’activités récréatives;</li>\r\n  <li>les conditions météorologiques défavorables;</li>\r\n  <li>la prédation.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1B', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(46, 'Petit blongios', 'petit butor; blongios; blongios minute; blongios d\'Amérique', 'Least Bittern', 'Bittlin; Gaulin; Minute Bittern; Eastern Least Bittern', 'Ixobrychus exilis', '', '<p>Le petit blongios, autrefois connu sous le nom de petit butor, est un petit échassier au même titre que le grand héron. Au Québec, cette espèce est désignée vulnérable.</p>', '<p>Au Canada, le petit blongios a été observé dans toutes les provinces. La population canadienne est estimée à environ 1 500 couples et elle est principalement concentrée dans le sud de l’Ontario.\r\n</p><p>\r\nAu Québec, le petit blongios est présent seulement dans le sud de la province. La grande majorité des mentions proviennent des régions situées le long des rivières des Outaouais et Richelieu, comme du fleuve Saint-Laurent en amont de Québec, ainsi que de la rive sud du fleuve jusqu’aux environs du lac Saint-Pierre.\r\n</p><p>\r\nLe petit blongios hiverne principalement le long des côtes et du golfe du Mexique, jusqu’au Panama.</p>', '<p>La population nicheuse du Québec totaliserait entre 200 et 300 couples. L’effectif de l’espèce est en diminution depuis plusieurs années au Canada et aux États-Unis, mais la tendance démographique de l’espèce au Québec demeure inconnue.</p>', '<p>Le petit blongios niche dans des marais et des marécages d’eau douce dominés par des plantes aquatiques émergentes, particulièrement les quenouilles, ainsi que par des arbustes et des zones d’eau libre. Il affectionne les milieux humides où le niveau de l’eau varie peu durant l’été (marais aménagés, marais lacustres).</p>', '<p>Le petit blongios se nourrit de petits poissons et d’invertébrés aquatiques. Il chasse ses proies à l’affût, en eau peu profonde près du bord des marais, ce qui explique son besoin de disposer de zones d’eaux libres.</p>', '<p>L’âge de reproduction de l’espèce n’est pas connu. Le petit blongios construit son nid dans une touffe de végétation à une hauteur qui varie entre 15 et 76 cm au-dessus du niveau de l’eau. Une couvée contient généralement quatre ou cinq œufs blancs bleutés ou verdâtres. Le succès de nidification est variable en raison de la vulnérabilité des nids à la montée des eaux et à la prédation.</p>', NULL, '<p>Les principales menaces qui pèsent sur le petit blongios sont :</p>\r\n<ul>\r\n  <li>la destruction des milieux humides qui causent la perte d’habitats de nidification;</li>\r\n  <li>l’agriculture par le remplissage et l’assèchement des marais;</li>\r\n  <li>le développement urbain;</li>\r\n  <li>les produits toxiques dans l’eau;</li>\r\n  <li>les espèces végétales envahissantes;</li>\r\n  <li>les clôtures et les fils électriques;</li>\r\n  <li>les collisions avec les véhicules.</li>\r\n</ul>\r\n', 'Reproducteur', 'S2S3', 'Vulnérable', 'Environnement et Changement climatique Canada', 3),
(101, 'Arlequin plongeur, pop. de l\'Est', 'canard arlequin; garrot arlequin; garrot harlequin; canard arlequin de l\'Est', 'Harlequin Duck - Eastern population', '', 'Histrionicus histrionicus pop. 1', NULL, '<p>L’arlequin plongeur, autrefois connu sous le nom de canard arlequin, est un petit canard de mer. Au Québec, cette espèce est désignée vulnérable.</p>', '<p>La population de l’Est de l’arlequin plongeur se reproduit en eau douce, le long des cours d’eau, depuis le nord du Nouveau‑Brunswick jusqu’au Nunavut. Elle passe l’hiver le long des côtes rocheuses et des îles de l’est de l’Amérique du Nord, depuis Terre‑Neuve‑et‑Labrador jusqu’au Maryland, et sur la côte sud‑ouest du Groenland.\r\n</p><p>\r\nUne part importante de la population d’arlequins plongeurs de l’est de l’Amérique du Nord niche au Québec. Une sous-population se reproduit dans certains secteurs du Nunavik et hiverne sur les côtes du Groenland. Une autre sous-population niche en Gaspésie et probablement aussi sur la Basse‑Côte‑Nord. Cette sous-population hiverne le long de la côte de l’Atlantique, à Terre‑Neuve, en Nouvelle‑Écosse et au Maine.\r\n</p><p>\r\nPlusieurs sites de mue en eau salée sont également utilisés dans la province : le long de la Gaspésie et de la Basse‑Côte-Nord, de même qu’à l’île d’Anticosti.</p>', '<p>Dans le sud de son aire de reproduction, une certaine augmentation du nombre d’arlequins plongeurs a été observée. Toutefois, la taille de la population de l’Est demeure restreinte. Des estimations montrent que moins de la moitié des femelles nichent certaines années, possiblement en raison d’une diminution de l’abondance des insectes.\r\n</p><p>\r\nComparativement à d’autres populations d’oiseaux aquatiques, le taux de reproduction des populations d’arlequins plongeurs est faible. Leur croissance démographique est donc difficile à rétablir après un déclin. Des facteurs comme l’âge avancé au moment de la première reproduction, la faible taille de ponte et la proportion élevée d’oiseaux non reproducteurs certaines années peuvent contribuer à cette faible productivité.\r\n</p><p>\r\nPar ailleurs, l’arlequin plongeur a pour habitude de se rassembler en grands groupes à la période de la mue dans les aires d’hivernage marines. Cette habitude le rend particulièrement vulnérable à certaines catastrophes comme les déversements de pétrole, qui pourraient nuire à de nombreux individus de l’espèce en même temps.</p>', '<p>En hiver, les arlequins plongeurs occupent les falaises rocheuses, les caps exposés et les corniches. Ils se regroupent pour se nourrir dans les eaux agitées des régions côtières peu profondes et rocheuses. Ils sont aussi régulièrement observés à proximité des îles, au large des côtes.</p>', '<p>En mer, l’arlequin plongeur trouve sa nourriture en plongeant dans les petits bassins près des rochers. Il se nourrit principalement de petits crabes, de petits crustacés (amphipodes), de gastropodes, d’œufs et de poisson.\r\n</p><p>\r\nPendant l’incubation des œufs, les arlequins plongeurs s’alimentent en scrutant le substrat des rivières pour trouver des larves d’insectes et d’autres invertébrés.</p>', '<p>Au printemps, l’arlequin plongeur quitte les eaux salées pour remonter les rivières et les ruisseaux à débit rapide afin de s’y reproduire. La reproduction commence généralement à la fin de mai ou au début de juin. Le nid, garni de duvet, peut être construit sur le sol, sous des arbustes, dans des cavités d’arbres, sous des corniches ou même sur des rochers.\r\n</p><p>\r\nLa femelle pond de trois à huit œufs et elle les couve pendant environ 28 jours. Pendant l’incubation, la femelle quitte rarement le nid; elle le fait pour s’alimenter, se laver ou se reposer. Comme le font de nombreux autres oiseaux aquatiques, le mâle quitte l’aire de nidification une fois l’incubation commencée (généralement entre la mi‑juin et le début de juillet). Les femelles les rejoignent normalement pour muer un ou deux mois plus tard.</p>', NULL, '<p>Les menaces qui pèsent sur l’arlequin plongeur, population de l’Est, sont :</p>\r\n<ul>\r\n  <li>l’exploitation forestière qui détruit ses sites de reproduction;</li>\r\n  <li>les barrages qui augmentent le niveau d’eau et, ce faisant, dégradent son habitat;</li>\r\n  <li>la construction de routes d’accès aux exploitations hydroélectriques et minières qui fragmentent son habitat;</li>\r\n  <li>les prises accidentelles dans les engins de pêche;</li>\r\n  <li>la pollution comme les déversements d’hydrocarbures.</li>\r\n</ul>\r\n', 'Reproducteur', 'S3S4B', 'Vulnérable', 'Environnement et Changement climatique Canada', 3),
(107, 'Garrot d\'Islande, pop. de l\'Est', 'garrot de Barrow; garrot islandais; canard de Barrow', 'Barrow\'s Goldeneye - Eastern population', 'Goldeneye; Brasseye; Cock pie-duck; Great-head', 'Bucephala islandica pop. 1', NULL, '<p>Le garrot d’Islande, aussi connu sous le nom de garrot de Barrow, est un canard plongeur de taille moyenne. Cette espèce est désignée vulnérable au Québec.</p>', '<p>La population de garrot d’Islande de l’Est du Canada se trouve en grande majorité au Québec. Son aire de nidification s’étend principalement au nord de l’estuaire et du golfe du Saint‑Laurent, dans la forêt boréale.\r\n</p><p>\r\nPeu de temps après le début de la période de couvaison, les mâles s’envolent vers leurs sites de mue. Ces sites comprennent les eaux côtières de la baie d’Hudson, de la baie d’Ungava et de la baie Frobisher (île de Baffin) ainsi que quelques baies du nord du Labrador.</p>', '<p>La population mondiale compte au moins 200 000 individus, et plus de 95 % de celle-ci niche et hiverne au Canada, à l’ouest des Rocheuses. Ailleurs dans le monde, une petite population résidente se maintient en Islande (environ 2 000 individus). La population de l’Est du Canada est estimée à environ 6 800 individus.</p>', '<p>En hiver, le garrot d’Islande, population de l’Est, réside le long de l’estuaire du Saint‑Laurent. L’espèce est surtout observée sur la rive nord de l’estuaire, qui est généralement plus dégagée que la rive sud, où la glace recouvre une bonne partie du rivage.</p>', '<p>En dehors de la saison de reproduction, les garrots s’alimentent de crustacés et de mollusques des eaux côtières. En période de reproduction, ils mangent des insectes aquatiques et des crustacés qui se trouvent en abondance dans les lacs alcalins.</p>', '<p>La femelle pond une fois par année, généralement de 6 à 12 œufs. Les œufs sont pondus dans des cavités d’arbres, souvent dans le bouleau blanc et le tremble. Les arbres choisis pour la nidification sont de grande dimension et sont à un stade avancé de décomposition. Ils sont généralement situés à une distance de 90 m à 250 m de l’eau. Ce sont les femelles qui s’occupent de l’élevage des jeunes.</p>', NULL, '<p>Les principales menaces qui pèsent sur le garrot d’Islande, population de l’Est, sont :</p>\r\n<ul>\r\n  <li>l’exploitation forestière, qui élimine les arbres utilisés par le garrot pour la nidification et qui facilite l’accès des humains aux plans d’eau utilisés lors de la période de reproduction;</li>\r\n  <li>l’ensemencement des lacs fréquentés par le garrot, celui-là diminuant l’abondance des invertébrés dont il se nourrit;</li>\r\n  <li>les activités nautiques sur les plans d’eau qui servent de sites de nidification.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3S4B', 'Vulnérable', 'Environnement et Changement climatique Canada', 3),
(118, 'Pygargue à tête blanche', 'aigle à tête blanche; aigle chauve; aigle américain à tête blanche; pygargue d\'Amérique', 'Bald Eagle', 'Northern Bald Eagle; American Bald Eagle', 'Haliaeetus leucocephalus', NULL, '<p>Le pygargue à tête blanche est un oiseau de proie actif le jour. Au sommet de la chaîne alimentaire, ce prédateur occupe une place très utile dans les écosystèmes. Autrefois en situation précaire, cette espèce vulnérable est en voie de se rétablir.</p>\r\n\r\n<p>Le pygargue à tête blanche est un animal à déclaration obligatoire. En tout temps, si vous trouvez un pygargue à tête blanche blessé ou mort, contactez SOS Braconnage — Urgence faune sauvage au 1 800 463‑2191.</p>', '<p>Le pygargue à tête blanche vit uniquement en Amérique du Nord. L’espèce occupe le nord-ouest de l’Alaska et le centre du Canada, jusqu’au sud des États‑Unis. Au Québec, le pygargue à tête blanche niche au sud du 55e parallèle, à l’exception des zones densément peuplées. En automne, plusieurs individus migrent et hivernent principalement sur les côtes des océans Atlantique et Pacifique. Cependant, de plus en plus de pygargues à tête blanche demeurent au Québec tout l’hiver.</p>', '<p>Le pygargue à tête blanche a subi un déclin important de 1930 jusqu’aux années 1970. L’utilisation massive de pesticides organochlorés (p. ex., DDT) et leur accumulation dans la chaîne alimentaire ont engendré des problèmes de reproduction comme la stérilité, l’amincissement de la coquille des œufs, la mort embryonnaire ou le comportement anormal des parents. L’espèce a aussi été victime de persécution.\r\n</p><p>\r\nDepuis la fin des années 1970, l’utilisation de ces pesticides en Amérique du Nord est interdite et les populations de pygargues à tête blanche se portent mieux. En effet, la population de pygargues à tête blanche au Québec a connu une augmentation importante depuis 2002, tant en ce qui a trait au nombre d’individus que de sites de nidification. De plus, peu de menaces importantes sont appréhendées à court terme. Une tendance similaire a été observée dans l’ensemble de l’Amérique du Nord au cours des 30 dernières années.\r\n</p><p>\r\nLe pygargue à tête blanche niche maintenant dans presque toutes les régions du Québec. Il est estimé que la population continuera de croître au cours des prochaines années. En raison de l’amélioration de l’état de la population de l’espèce à l’échelle de la province, son statut de désignation pourrait être revu.</p>', '<p>Pour installer son nid, le pygargue à tête blanche cherche les arbres dominants de plus de 20 m de haut (conifères surtout) en forêt mature et la proximité de grandes étendues d’eau poissonneuses. Pour chasser, il survole surtout les grands lacs, les rivières à fort débit ou les vastes réservoirs artificiels.\r\n</p><p>\r\nL’hiver, le pygargue à tête blanche demeure près des lacs, des rivières et des réservoirs libres de glace où la nourriture est disponible.</p>', '<p>Le pygargue à tête blanche est un rapace carnivore actif le jour (diurne). Son régime alimentaire varie selon la disponibilité des proies. Il se nourrit principalement de poissons vivants ou morts. Il peut aussi se nourrir de sauvagine (canards, oies, bernaches, etc.), d’oiseaux marins (goélands, cormorans, macareux, etc.) ou de mammifères (surtout en hiver, notamment de carcasses de cervidés ou de phoques).</p>', '<p>Le pygargue à tête blanche est monogame. Les couples sont généralement formés pour la vie et ils retournent au même site de nidification chaque année.\r\n</p><p>\r\nLa ponte a lieu d’avril à mai et l’incubation dure de 34 à 46 jours. Chaque couvée comporte en moyenne deux œufs. Les deux parents apportent de la nourriture aux jeunes, mais c’est habituellement la femelle qui les nourrit. Les jeunes demeurent au nid jusqu’à l’âge de 10 ou 11 semaines et dépendent de leurs parents durant les deux mois qui suivent leur premier envol. Ils reviennent alors au nid pour se nourrir et pour dormir.</p>\r\n\r\n', NULL, '<p>Les principales menaces qui pèsent sur le pygargue à tête blanche au Québec sont :</p>\r\n<ul>\r\n  <li>la capture accidentelle par le piégeage;</li>\r\n  <li>la perte d’habitat en bordure des grands plans d’eau;</li>\r\n  <li>les pesticides;</li>\r\n  <li>le dérangement par les activités humaines dans les habitats de reproduction;</li>\r\n  <li>l’abattage illégal;</li>\r\n  <li>les collisions avec des véhicules, des éoliennes ou des lignes électriques;</li>\r\n  <li>l’empoisonnement à la suite de la consommation de carcasses intoxiquées par la grenaille de plomb provenant des cartouches de chasse (sauvagine et gros gibiers).</li>\r\n</ul>\r\n', 'Toute l\'année', 'S5B', 'Vulnérable', 'Québec', 3),
(129, 'Aigle royal', 'aigle doré; aigle fauve; aigle chrysaète; aigle commun', 'Golden Eagle', 'Black Eagle; Dark Eagle;', 'Aquila chrysaetos', NULL, '<p>L’aigle royal est un oiseau de proie actif le jour. Au sommet de la chaîne alimentaire, ce prédateur occupe une place très utile dans les écosystèmes. Particulièrement sensible aux activités humaines, sa présence est un bon indicateur de la qualité de l’environnement.</p>\r\n<p>\r\nL’aigle royal est un <a href=\"https://www.quebec.ca/tourisme-loisirs-sport/activites-sportives-et-de-plein-air/chasse-sportive/regles-generales/animaux-declaration-obligatoire\">animal à déclaration obligatoire</a>. En tout temps, si vous trouvez un aigle royal blessé ou mort, contactez <a href = \"https://www.quebec.ca/agriculture-environnement-et-ressources-naturelles/faune/protection-faune/sos-braconnage-urgence-faune-sauvage\">SOS Braconnage — Urgence faune sauvage</a> au 1 800 463‑2191.</p>', '<p>L’aigle royal est largement répandu en Amérique du Nord. Il existe deux populations :</p>\r\n<ul>\r\n  <li>la population de l’Ouest qui s’étend du Mexique à l’Alaska et de la Colombie-Britannique à la Saskatchewan;</li>\r\n  <li>la population de l’Est qui est répartie du Québec à la Virginie et du Manitoba au Labrador.</li>\r\n</ul>\r\n\r\n<p>Au Québec, l’aigle royal niche dans cinq régions administratives :</p>\r\n<ul>\r\n  <li>le Nord-du-Québec;</li>\r\n  <li>la Côte-Nord, dont l’île d’Anticosti;</li>\r\n  <li>la Gaspésie;</li>\r\n  <li>le Bas-Saint-Laurent;</li>\r\n  <li>la Capitale-Nationale.</li>\r\n</ul>\r\n\r\n<p>La majorité des aigles royaux du Québec sont migrateurs. Ils hivernent dans l’est des États-Unis, dans certains États du Midwest ou dans le sud du Canada.</p>\r\n', '<p>Les données historiques sur la taille de la population de l’aigle royal sont pratiquement inexistantes. Toutefois, il est estimé que plusieurs facteurs d’origine humaine sont responsables d’une diminution de l’effectif et limitent l’expansion de l’espèce au Québec.</p>\r\n\r\n<p>La population d’aigles royaux semble montrer une tendance stable et même une légère hausse depuis 2006, malgré les menaces qui pèsent toujours sur l’espèce. Afin de favoriser le rétablissement de l’aigle royal au Québec, il est nécessaire de poursuivre les efforts de protection, de recherche et de sensibilisation.</p>', '<p>Pour chasser, l’aigle royal survole des habitats relativement ouverts comme la toundra, la taïga, les prairies herbacées et arbustives. Les aires ouvertes d’épinettes noires à lichens ou à mousses de la forêt boréale font également partie de ses zones prisées pour la chasse.\r\n</p><p>\r\nEn période de reproduction, l’aigle royal installe son nid sur les corniches de falaises. Plus rarement, il peut nicher dans les arbres des régions montagneuses avec des vallées.</p>', '<p>L’aigle royal est un rapace carnivore actif le jour (diurne). Son régime alimentaire varie selon la disponibilité des proies. Il peut se nourrir d’oiseaux, de petits mammifères, de poissons (à l’occasion) et de charognes (surtout l’hiver, lorsque les proies sont rares).</p>', '<p>L’aigle royal atteint la maturité sexuelle à cinq ans, mais il peut se reproduire plus tôt si la densité d’adultes dans le secteur est faible. Il réutilise et améliore généralement un nid construit au cours d’une année précédente. La base du nid est constituée de branches sur lesquelles repose un bol, formé de mousses, de lichens, de feuilles et d’herbes, qui accueille les œufs. Un couple peut avoir plusieurs nids sur son territoire, mais n’en utilise qu’un seul par année.</p>\r\n\r\n<p>La ponte a lieu d’avril à la mi-juin et l’incubation dure de 43 à 45 jours. Une couvée contient généralement un ou deux œufs. Les œufs éclosent à quelques jours d’intervalle. Les deux parents prodiguent des soins aux jeunes. Les jeunes quittent le nid généralement autour de 65 jours. La plupart des couples sont unis pour la vie et restent fidèles à leur site de nidification, année après année.</p>', NULL, '<p>Les principales menaces qui pèsent sur l’aigle royal au Québec sont :</p>\r\n<ul>\r\n  <li>le piégeage accidentel par les pièges à canidés;</li>\r\n  <li>la contamination aux produits toxiques et particulièrement au plomb;</li>\r\n  <li>le dérangement par les activités humaines;</li>\r\n  <li>la collision avec des véhicules, des éoliennes ou des lignes électriques;</li>\r\n  <li>l’abattage illégal.</li>\r\n</ul>\r\n', 'Reproducteur', 'S3', 'Vulnérable', 'Québec', 3),
(145, 'Râle jaune', 'marouette jaune', 'Yellow Rail', 'Little Yellow Rail; Yellow-brested Gallinul; Clicker; Water Sparrow', 'Coturnicops noveboracensis', NULL, '<p>Le râle jaune, petit oiseau qui rappelle la caille, se déplace facilement dans la végétation aquatique. C\'est une espèce menacée.</p>', '\r\n<p>Le râle jaune se reproduit presque exclusivement au Canada et dans le nord des États‑Unis. Son aire de répartition au Québec représente environ le quart de son aire de répartition mondiale. Il niche par endroits dans la portion sud du Québec, principalement le long du fleuve Saint‑Laurent, jusqu’en Gaspésie, et le long de la rivière Saguenay. Des mentions ont été signalées l’été en Abitibi‑Témiscamingue, mais très peu de nids y ont été découverts jusqu’à présent. L’île aux Grues, en aval de Québec, est un site de nidification important, en plus d’être un site d’alimentation et de rassemblement pour la mue. La presque totalité des mentions durant la période migratoire proviennent des basses-terres du Saint‑Laurent.\r\n</p>\r\n<p>Le râle jaune passe l’hiver aux États‑Unis, de l’est du Texas jusque dans les Carolines.</p>', '<p>\r\nAu Canada, la population de râle jaune compte environ 10 000 individus. Selon les estimations, la population a décliné de près de 30 % depuis les années 2000.\r\n</p><p>\r\nTrès peu de données sont disponibles pour établir la tendance démographique du râle jaune au Québec. Son comportement discret et furtif le rend difficile à détecter dans son environnement. Néanmoins, les spécialistes estiment que plus de 1 000 couples nichent le long de la côte sud de la baie James.</p>', '<p>En période de nidification, le râle jaune habite de préférence la partie supérieure des marais d’eau douce et d’eau saumâtre de grande étendue, où la végétation est dense et courte. Les marais à carex dense ou couverts d’autres plantes basses sont les milieux qu’il affectionne plus particulièrement.</p>', '<p>Le râle jaune se nourrit surtout de coléoptères et d’autres petits arthropodes. Il mange aussi des graines de graminées.</p>', '<p>La femelle pond entre sept et dix œufs et elle assume seule l’incubation. Elle ne produit qu’une couvée par année, mais peut en produire une autre si la première ne survit pas. Le mâle ne participe pas au soin des jeunes et n’est plus associé à la femelle une fois l’incubation amorcée.</p>', '<p>Le râle jaune est parmi les oiseaux les plus rares et les plus méconnus au Québec en raison de son comportement discret et furtif ainsi que du type d’habitat qu’il fréquente. Au lieu de s’envoler à l’approche d’un humain, le râle jaune reste sur place, caché dans la végétation. De plus, le mâle vocalise beaucoup plus la nuit que le jour. Quant à la femelle, elle ne chante pas.</p>', '<p>Les principales menaces qui pèsent sur le râle jaune sont :</p>\r\n<ul>\r\n  <li>l’endiguement et l’assèchement par drainage ou remblayage qui causent la dégradation et la perte de son habitat;</li>\r\n  <li>le développement urbain, commercial et agricole.</li>\r\n</ul>\r\n', 'Reproducteur', 'S2S3', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(233, 'Sterne caspienne', 'sterne tchégrava; sterne tschegrava; hydroprogné tschégrava; grand esterette', 'Caspian Tern', 'Gannet Striker; Great Tern; Imperial Tern; Redbill', 'Hydroprogne caspia', NULL, '<p>La sterne caspienne est la plus grande et la plus lourde des sternes du monde. Au Québec, cette espèce est menacée.</p>', '<p>La sterne caspienne est présente partout dans le monde. Elle niche à plusieurs endroits au Canada et aux États‑Unis.</p>\r\n\r\n<p>Au Québec, son aire de nidification connue se limite toutefois à un endroit, soit l’île à la Brume, dans le golfe du Saint‑Laurent, à l’est du village de La Romaine. L’espèce fréquente d’autres îles à l’occasion, dont l’île Étrangle‑Chat, qui fait partie du refuge d’oiseaux migrateurs de l’île à la Brume.</p>\r\n\r\n<p>Lors des migrations, les sternes caspiennes de l’île à la Brume semblent transiter par les provinces et la côte Atlantique pour atteindre leurs quartiers d’hivernage. Ces derniers sont situés vraisemblablement sur la côte Atlantique, entre la Caroline du Nord et la Colombie.</p>', '<p>Dans plusieurs régions du monde, la sterne caspienne semble en déclin. Bien que les populations soient généralement en hausse en Amérique du Nord, la situation est différente le long de la côte atlantique. La colonie de sternes caspiennes de l’île à la Brume a connu une baisse marquée au fil du 20e siècle, et son déclin pourrait bien avoir atteint un point critique. Cette colonie comptait environ 200 couples nicheurs vers la fin du 19e siècle, mais son effectif n’a jamais dépassé une centaine d’oiseaux entre 1923 et 1945. Le déclin semble s’être poursuivi après 1945. Il est possible qu’il ait été causé par la récolte illégale d’œufs et d’adultes ainsi que par le dérangement qui accompagne de telles activités. Aucune activité de nidification n’a été confirmée depuis 1995 à cet endroit, bien que l’espèce y ait été observée à quelques reprises.</p>\r\n\r\n<p>Les observations faites dans les années 2000 dans ces environs laissent croire que la sterne caspienne pourrait encore s’y reproduire à l’occasion. Les îles de la Madeleine et le sud-ouest de la province, soit le cours inférieur de la rivière des Outaouais et le fleuve Saint‑Laurent, en amont de Trois‑Rivières, sont les seules autres régions du Québec où la sterne caspienne est observée régulièrement.</p>\r\n\r\n<p>Certaines données laissent croire qu’elle niche dans le sud-ouest du Québec. Les observations rapportées et la présence d’îles à bon potentiel de nidification expliquent que des couples nicheurs puissent passer inaperçus à travers les colonies de goélands.</p>', '<p>Pour nicher, la sterne caspienne s’établit souvent sur de petites îles basses, comptant peu ou pas de végétation. Elles sont situées tant le long des côtes qu’à l’intérieur des terres à proximité de rivières, de grands lacs ou de réservoirs.</p>\r\n\r\n<p>La sterne caspienne peut se trouver, par exemple, sur des îles sablonneuses parsemées de débris de bois, sur des îlots graveleux et sur des îles rocheuses.</p>', '<p>Dans la région des Grands Lacs, la sterne caspienne s’alimente de gaspareaux, d’éperlans arc‑en‑ciel, de perchaudes et de crapets de roche.</p>', '<p>La sterne caspienne se reproduit généralement en colonie parmi d’autres sternes et goélands. Elle peut également nicher en petit groupe ou en couple solitaire.</p>', NULL, '<p>Les principales menaces qui pèsent sur la sterne caspienne sont :</p>\r\n<ul>\r\n  <li>les dérangements par l’activité humaine;</li>\r\n  <li>le braconnage.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(235, 'Sterne de Dougall', 'sterne rosée; sterne rose', 'Roseate Tern', 'McDougall\'s tern', 'Sterna dougallii', NULL, '<p>Au Québec, la sterne de Dougall est présente seulement aux îles de la Madeleine. Elle est une espèce menacée au Québec.</p>', '<p>Au Canada, la sterne de Dougall niche dans trois provinces : au Québec, au Nouveau‑Brunswick et en Nouvelle‑Écosse. Cette dernière héberge d’ailleurs plus de 90 % des couples reproducteurs du pays.</p>\r\n\r\n<p>Au Québec, l\'espèce se reproduit en un seul endroit, soit aux îles de la Madeleine, sur l’île aux Cochons, et sur un îlot artificiel situé près de Grande‑Entrée. Ces deux sites représentent actuellement la limite nord de l’aire de répartition mondiale de l’espèce.</p>', '<p>Depuis les années 1930, les populations nord-américaines de sterne de Dougall ont subi des baisses majeures. Un déclin important a été observé au cours de deux périodes, soit de 1935 à 1952 et de 1972 à 1978. La première mention confirmée de la nidification de cette sterne aux îles de la Madeleine date de 1983. Cependant, des observations non compilées laissent supposer que l’espèce y nichait annuellement depuis 1972, mais en petit nombre.</p>\r\n\r\n<p>Aujourd’hui, sa population aux îles de la Madeleine semble stable. Elle est évaluée à quelques couples seulement.</p>', '<p>La sterne de Dougall niche habituellement au travers de colonies de goélands de diverses espèces. Toutefois, elle ne représente toujours qu’un faible pourcentage des oiseaux présents. </p>', '<p>La sterne de Dougall se nourrit de petits poissons comme les lançons, les harengs et les merlus.</p>', '<p>Les adultes peuvent s’accoupler à l’âge de 3 ans. Le nid est construit à même le sol et il est parfois caché sous la végétation. La femelle y pond habituellement 1 ou 2 œufs. Les deux parents participent à l’élevage.</p>', NULL, '<p>Les principales menaces qui pèsent sur la sterne de Dougall sont :</p>\r\n<ul>\r\n  <li>la récolte des œufs;</li>\r\n  <li>l’abattage sur les aires d’hivernage en Guyane;</li>\r\n  <li>la prédation;</li>\r\n  <li>la compétition pour les habitats liés à l’expansion de certaines populations d’espèces de goélands;</li>\r\n  <li>la pollution des eaux.</li>\r\n</ul>', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(274, 'Engoulevent bois-pourri', 'engoulevent criard; bois-pourri; engoulevent bruyant; engoulevent vocifère', 'Eastern Whip-poor-will', 'Whip-poor-will; Moskoto Hawk; Whip-her-well', 'Antrostomus vociferus', '<p>On le reconnaît à son cri troublant constitué d’un son roulé et répété de façon incessante qui sonne un peu comme « bois-pourri », d’où son nom (à titre comparatif, le nom anglais de l\'oiseau est aussi basé sur le même son, transcrit comme « whip-poor-will »)</p>', '<p>L\'Engoulevent bois-pourri (Antrostomus vociferus) est un oiseau nocturne de taille moyenne (22 à 27 cm) reconnu pour son plumage cryptique qui imite à la perfection l\'écorce ou le bois mort.</p>', NULL, NULL, '<p>L\'Engoulevent bois-pourri (Antrostomus vociferus) fréquente les mosaïques forestières semi-ouvertes qui combinent des zones boisées pour se reposer et des milieux ouverts pour chasser.</p>', '<p>L\'engoulevent bois-pourri est un oiseau strictement insectivore qui se nourrit d\'une grande variété d\'insectes volants qu\'il chasse la nuit.</p>', '<p>Il dépose 2 œufs sur le sol, généralement sur des feuilles sèches. Ils sont blanc crème ou grisâtre, tachetés de lilas ou brun foncé ou très pâle.</p>', NULL, '<p>Le déclin important des populations d\'engoulevent bois-pourri au Canada et aux États-Unis s\'explique par une combinaison de facteurs environnementaux et humains:</p>\r\n\r\n<ul>\r\n  <li><strong>La diminution des insectes proies :</strong> L\'utilisation massive et généralisée de pesticides et d\'insecticides à large spectre détruit les populations d\'insectes nocturnes (comme les gros papillons de nuit). Sans cette source de nourriture exclusive, l\'oiseau ne peut plus s\'alimenter correctement ni nourrir ses couvées.</li>\r\n  <li><strong>La perte et la dégradation de l\'habitat :</strong> L\'engoulevent a absolument besoin de forêts semi-ouvertes pour chasser au clair de lune. Ces milieux disparaissent au profit de l\'agriculture intensive ou du développement urbain au sud, ou se referment naturellement en forêts denses et sombres au nord, rendant la chasse impossible.</li>\r\n  <li><strong>Les collisions avec les véhicules :</strong> Comme il chasse à basse altitude près des lisières et qu\'il lui arrive fréquemment de se poser directement sur les routes de terre ou d\'asphalte la nuit (pour profiter de la chaleur ou pour repérer les insectes dans les phares), il est extrêmement vulnérable aux accidents routiers.</li>\r\n  <li><strong>Les changements climatiques :</strong> L\'augmentation de la fréquence et de la violence des ouragans le long de ses voies de migration vers l\'Amérique centrale perturbe son cycle de vie et augmente son taux de mortalité.</li>\r\n  <li><strong>La prédation accrue au sol :</strong> Cet oiseau niche directement sur le sol, sans construire de nid (à même les feuilles mortes). L\'étalement urbain amène une hausse des prédateurs opportunistes près de ses zones de nidification, notamment les chats domestiques en liberté, les ratons laveurs et les coyotes.</li>\r\n</ul>\r\n', 'Reproducteur', 'S3', 'Vulnérable', 'Environnement et Changement climatique Canada', 3),
(278, 'Pic à tête rouge', 'mélanerpe à tête rouge; pic tricolor; pic noir à domino rouge; pic-à-bois', 'Red-headed Woodpecker', 'Woodcock; Wood Pick; Wood Pecker; Redhead', 'Melanerpes erythrocephalus', '', '<p>Le pic à tête rouge est un oiseau de taille moyenne et l’une des neuf espèces de pics-bois du Québec. Le pic à tête rouge est désigné menacé au Québec.</p>', '<p>Le pic à tête rouge est présent seulement en Amérique du Nord. Aux États‑Unis, son aire de répartition est concentrée dans les États du centre-ouest. Au Canada, l’espèce est présente en Saskatchewan, au Manitoba, en Ontario et au Québec. À l’occasion, elle est observée dans l’ouest du pays et dans les Maritimes.\r\n</p><p>\r\nLe pic à tête rouge passe l\'hiver aux États‑Unis, bien qu’il demeure parfois au Québec. Les observations de l’espèce en hiver concernent probablement des individus visitant des aires d’alimentation situées en milieux urbains et agricoles.</p>', '<p>Moins de 1 % de la population mondiale de pic à tête rouge se trouve au Canada. La population canadienne de pic à tête rouge est estimée entre 2 000 à 3 000 couples, soit entre 4 000 et 6 000 individus matures. La population est considérée en déclin. Entre 1970 et 2016, la population aurait diminué de plus de 58 % au Canada.\r\n</p><p>\r\nLa présence de l’espèce est rare et irrégulière au Québec. Auparavant, il lui arrivait de nicher occasionnellement dans les régions bordant la vallée du sud du Saint‑Laurent comme l’Outaouais, Montréal, la Montérégie et l’Estrie. En 2016, on estimait qu’entre 0 et 3 couples nichaient au Québec. Aujourd’hui, le pic à tête rouge est considéré comme un nicheur rare qui se reproduit sporadiquement au Québec.</p>', '<p>Le pic à tête rouge fréquente surtout les forêts dominées par les chênes et les hêtres. L’espèce fréquente aussi d’autres types de milieux comme les plaines inondables, les prairies, les parcs urbains, les brûlis et le bord des rivières et des routes.</p>\r\n\r\n<p>En période de reproduction, le pic à tête rouge choisit des aires ouvertes qui comptent une grande densité d’arbres morts et dispersés lui procurant un emplacement potentiel pour le nid ou un perchoir.</p>', '<p>Le pic à tête rouge est probablement l’espèce la plus omnivore parmi les pics d’Amérique du Nord. Il capture des insectes en vol (coléoptères, papillons, cigales, criquets, abeilles, etc.) et se nourrit de glands et de faines (fruits du hêtre) en hiver. À l’occasion, il mange des œufs et des oisillons d’autres espèces d’oiseaux ainsi que des noix et des fruits. Il est l’un des seuls pics au monde à cacher des réserves de nourriture.</p>', '<p>Le pic à tête rouge est monogame. La femelle pond entre 3 et 10 œufs, et les deux membres du couple participent à la couvaison et au nourrissage des jeunes. Le nid occupe une cavité creusée dans un arbre mort ou une souche, dans un pieu de clôture ou un poteau.</p>', NULL, '<p>Les principales menaces qui pèsent sur le pic à tête rouge sont :</p>\r\n<ul>\r\n  <li>l’intensification de l’agriculture, qui cause la perte et la dégradation de son habitat;</li>\r\n  <li>la diminution du nombre d’arbres morts encore debout (chicots) qu’il recherche pour y installer son nid ou cacher de la nourriture;</li>\r\n  <li>la compétition avec l’étourneau sansonnet pour les mêmes sites de nidification;</li>\r\n  <li>les collisions avec des structures ou des véhicules.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3);
INSERT INTO `especes` (`id`, `nom_francais`, `autres_noms_francais`, `nom_anglais`, `autres_noms_anglais`, `nom_scientifique`, `commentaires`, `description`, `repartition`, `etat_situation`, `habitat`, `alimentation`, `reproduction`, `comportement`, `menaces`, `statuts_des_populations`, `rang_S`, `statut_LEMV`, `competence_principale`, `groupe_id`) VALUES
(341, 'Grive de Bicknell', '', 'Bicknell\'s Thrush', '', 'Catharus bicknelli', NULL, '<p>La grive de Bicknell est un oiseau de la même famille que le merle d’Amérique. Cette espèce est désignée comme espèce vulnérable au Québec.</p>', '<p>Aux États‑Unis, la grive de Bicknell est observée dans les États du Vermont, du Maine, du New Hampshire et de New York (Adirondacks). Au Canada, elle est présente au Québec, au Nouveau-Brunswick et en Nouvelle‑Écosse.\r\n</p><p>\r\nAu Québec, la répartition de la grive de Bicknell est limitée à un petit nombre d’endroits. Au sud du Saint‑Laurent, elle se trouve principalement dans les Appalaches (Estrie, Bas-Saint-Laurent et Gaspésie). Sur la rive nord, l’espèce est principalement observée en bordure du Bouclier canadien (réserve faunique des Laurentides, Charlevoix et région des monts Vallin). À l’automne, l’espèce quitte le Québec pour ses aires d’hivernage, situées dans les Grandes Antilles.</p>', 'La population de grive de Bicknell au Canada est en déclin. Au Québec, il n’est pas possible actuellement d’estimer avec précision la tendance démographique de l’espèce. Toutefois, un suivi réalisé au mont Gosford de 2001 à 2007 indiquait une diminution de 60 % des individus détectés lors des inventaires.', '<p>La grive de Bicknell recherche un habitat bien particulier. Il se compose de peuplements denses de conifères qui sont soit situés dans des régions montagneuses, soit en régénération, mesurant au moins 2 m de hauteur et situés à plus de 600 m d’altitude, où le sapin est généralement la principale essence forestière.\r\n</p><p>\r\nLes forêts recherchées par cette espèce sont caractérisées par un climat humide, frais et venteux où le brouillard est souvent présent.\r\n</p><p>\r\nBien qu’elle occupe aujourd’hui ses habitats traditionnels, la grive de Bicknell est également présente à plus basse altitude, dans les forêts denses dominées par le sapin, objet d’exploitation forestière.</p>', '<p>L’été, la grive de Bicknell se nourrit de chenilles, de fourmis, de guêpes, de coléoptères, de criquets juvéniles, de mouches, de papillons de nuit et d’autres insectes.\r\n</p><p>\r\nVers la fin de l’été et en automne, elle modifie son régime alimentaire pour devenir davantage frugivore. Elle ajoute à son menu les baies de cornouiller, de belladone, d’épine-vinette, de benjoin, de raisin sauvage, de vigne vierge commune et de sumac grimpant.</p>', '<p>En période de reproduction, la femelle a une seule couvée. Elle pond de trois à quatre œufs bleu verdâtre légèrement marqués de petites taches brunes. Contrairement à la majorité des passereaux, les mâles ne défendent pas de territoire.\r\n</p><p>\r\nLes grives de Bicknell ont un comportement social inhabituel : plusieurs mâles peuvent partager la paternité d’une même couvée. De plus, ils peuvent visiter et nourrir les oisillons de plus d’un nid à la fois.\r\n</p><p>\r\nLe nid est placé, souvent pas très haut, dans un conifère ou, plus rarement, dans un feuillu.</p>', NULL, '<p>Les principales menaces qui pèsent sur la grive de Bicknell sont :</p>\r\n<ul>\r\n  <li>l’exploitation forestière qui provoque la perte et la fragmentation de ses habitats;</li>\r\n  <li>les corridors de transport (tours de communications, lignes électriques);</li>\r\n  <li>les parcs éoliens qui causent la mort par une collision directe avec les pales en mouvement;</li>\r\n  <li>la prédation;</li>\r\n  <li>le développement commercial;</li>\r\n  <li>les changements climatiques;</li>\r\n  <li>le déboisement lié à l’agriculture de subsistance, la production de charbon de bois et la transformation de la canne à sucre, qui modifient les sites d’hivernage.</li>\r\n</ul>\r\n', 'Reproducteur', 'S2', 'Vulnérable', 'Environnement et Changement climatique Canada', 3),
(365, 'Paruline à ailes dorées', 'sylvette à ailes dorées; figuier à ailes dorées; figuier à épaulettes jaunes; fauvette aux ailes dorées', 'Golden-winged Warbler', 'Golden-winged Fly-catcher', 'Vermivora chrysoptera', '', '<p>La paruline à ailes dorées est un petit oiseau insectivore. Elle est désignée comme une espèce menacée au Québec.</p>', '<p>La paruline à ailes dorées niche seulement dans la portion est de l’Amérique du Nord. Elle est très peu présente au Canada et n’est répertoriée que dans le sud du Québec, de l’Ontario et du Manitoba.</p>\r\n\r\n<p>Les données des années 1970 démontrent qu’au Québec l’espèce nichait à deux endroits : au lac Philippe en Outaouais et à Philipsburg en Montérégie. Il semble que deux populations se soient installées autour de ces sites, formant deux aires de nidification bien distinctes. À l’automne, la paruline à ailes dorées repart vers l’Amérique centrale ou l’Amérique du Sud pour y passer l’hiver.</p>', '<p>Les données récentes indiquent que les effectifs de la paruline à ailes dorées aux États-Unis ont diminué depuis quelques décennies. Cet oiseau est maintenant absent de plusieurs localités où il était commun dans le passé. Depuis le début des années 1990, la population de paruline à ailes dorées continue de diminuer au Québec.</p>', '<p>La paruline à ailes dorées utilise des sites où il y a peu d’arbres, mais où les plantes herbacées et les grands buissons abondent.</p>', '<p>La paruline à ailes dorées se nourrit surtout de papillons et de leurs larves. Elle s’alimente aussi, dans une moindre mesure, d’autres insectes ailés et d’araignées.</p>', '<p>Le couple engendre habituellement une nichée par année. La femelle pond en moyenne de 2 à 6 œufs par couvée.</p>', NULL, '<p>Les principales menaces qui pèsent sur la paruline à ailes dorées sont :</p>\r\n<ul>\r\n  <li>la destruction et la fragmentation de son habitat, notamment ses sites d’hivernage;</li>\r\n  <li>le parasitisme de ses nids par le vacher à tête brune;</li>\r\n  <li>la compétition avec la paruline à ailes bleues pour les mêmes ressources;</li>\r\n  <li>l’hybridation avec la paruline à ailes bleues, car les deux espèces peuvent se reproduire ensemble. Or, les hybrides produits, une fois matures, préfèrent s’accoupler avec les parulines à ailes bleues, ce qui désavantage la paruline à ailes dorées.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(388, 'Paruline azurée', 'sylvette azurée; figuier bleu; figuier gris-de-fer; fauvette gris-de-fer', 'Cerulean Warbler', '', 'Setophaga cerulea', NULL, '<p>La paruline azurée appartient à la famille des Parulidés. Ce petit oiseau est désigné comme une espèce menacée au Québec.</p>', '<p>La paruline azurée se reproduit seulement en Amérique du Nord. L\'Ontario et le Québec sont les deux seules provinces canadiennes à abriter l’espèce. Au Québec, elle niche dans les basses-terres du fleuve Saint‑Laurent et elle est principalement observée à Montréal, en Montérégie et en Outaouais.</p>\r\n\r\n<p>Elle hiverne en Amérique du Sud, principalement dans une aire restreinte du versant est des Andes, du Venezuela au Pérou, à des altitudes allant de 500 à 2 000 m. La migration semble durer environ deux mois au printemps et quatre à l’automne.</p>', '<p>Au Québec, la paruline azurée est considérée comme un oiseau nicheur migrateur rare dont les effectifs sont estimés à quelques dizaines de couples seulement. Depuis les années 1960, l’espèce aurait disparu de cinq des six secteurs où elle avait été observée.</p>', '<p>La paruline azurée est associée à des forêts de feuillus matures caractérisées par la présence d’arbres de grande taille et d’un sous-étage ouvert.</p>', '<p>La paruline azurée semble strictement insectivore durant la saison de nidification. Elle mange des diptères, des coléoptères ainsi que des larves de lépidoptères. Elle peut aussi s’alimenter de nectar en dehors de la période de reproduction.</p>\r\n\r\n<p>La paruline azurée se nourrit presque exclusivement dans la partie supérieure des arbres, ce qui rend son observation difficile.</p>', '<p>Le couple produit habituellement une nichée par année. La femelle pond en moyenne de 2 à 5 œufs par couvée. Elle partage les soins aux jeunes avec le mâle.</p>', NULL, '<p>Les principales menaces qui pèsent sur la paruline azurée sont :</p>\r\n<ul>\r\n  <li>la destruction et la fragmentation de son habitat, notamment en raison de l’exploitation forestière;</li>\r\n  <li>le développement résidentiel, commercial et agricole;</li>\r\n  <li>les changements climatiques.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(468, 'Lamproie du Nord', 'COSEPAC: lamproie du Nord, pop. des Grands-Lacs et du haut Saint-Laurent; lamproie de ruisseau du Nord', 'Northern Brook Lamprey', 'Michigan Brook Lamprey; Brook Lamprey; Blood Sucker', 'Ichthyomyzon fossor', '', '<p>La lamproie du Nord est un petit poisson d’eau douce de la famille des pétromyzontidés. Contrairement à d’autres lamproies, elle ne parasite pas les autres poissons pour se nourrir. Elle passe la majorité de sa vie sous forme de larve (ammocète), enfouie dans des terriers où elle se nourrit par filtration.</p>', '<p>La lamproie du Nord est présente seulement en Amérique du Nord. Au Canada, l’espèce se trouve dans le bassin hydrographique des Grands Lacs et du fleuve Saint‑Laurent, en Ontario et au Québec, de même que dans le bassin de la rivière Winnipeg, au Manitoba. Au Québec, sa répartition très restreinte se limite au fleuve Saint‑Laurent et à une dizaine de rivières situées dans le sud du Québec.</p>', '<p>Peu d’information est disponible sur la tendance des populations de la lamproie du Nord. L’espèce a été observée dans les rivières aux Outardes Est en 2002 et Saint‑François en 2003 ainsi qu’en 2017‑2018. Elle semble avoir apparemment disparu de la rivière Yamaska, malgré qu’aucun inventaire ciblé n’ait été fait récemment à cet endroit. Elle y a été observée en grand nombre entre 1946 et 1950 près de Saint‑Césaire. La pollution de l’eau liée aux mauvaises pratiques agricoles pourrait être la cause de la disparition probable de l’espèce dans cette rivière. Par ailleurs, des inventaires ciblés dans le bassin versant de la rivière Saint‑François ont été réalisés et ont permis de mettre à jour plusieurs occurrences de l’espèce au cours des 5 dernières années.</p>', '<p>La lamproie du Nord fréquente généralement les ruisseaux et les rivières à fond de gravier ou de sable et, au Québec, certaines sections du fleuve Saint‑Laurent. Elle semble éviter les eaux stagnantes et les lacs. Elle fréquente seulement l’eau douce, car elle ne tolère aucunement la salinité. Les adultes préfèrent les petits cours d’eau aux eaux vives et claires dont le substrat est constitué de gravier et de sable. Les larves des lamproies, appelées ammocètes, préfèrent la portion des cours d’eau à courant plus lent. Le substrat meuble y est propice à l’enfouissement, ce qui correspond à du sable mi-fin.</p>', '<p>La lamproie du Nord est non parasite. Cela signifie qu’elle ne se collera pas aux poissons pour les mordre et s’alimenter de leur sang. Les larves de la lamproie du Nord se nourrissent par filtration des organismes planctoniques, tels que le phytoplancton (diatomées, desmides et algues vertes, etc.), les protozoaires et autres matières organiques, transportés par le courant au fil des saisons. Les adultes ne se nourrissent pas, puisque leur système digestif s’atrophie jusqu’à devenir non fonctionnel pendant la métamorphose.</p>', '<p>La lamproie du Nord fraie au printemps, en eau peu profonde dont la température dépasse 20 °C. Les adultes sélectionnent les sections de rivières ou de ruisseaux caractérisées par des substrats de gros graviers, de galets et de sable. Les mâles entreprennent la construction de nids en déplaçant de petites pierres et du gravier avec leur bouche, ce qui crée une petite dépression. Ces nids discrets sont situés dans les espaces entre les grandes pierres. Les œufs d’environ 1 mm de diamètre forment des masses gélatineuses à l’intérieur des nids. Ils vont éclore de deux à quatre semaines après la ponte. Après l’éclosion, les larves sont déportées par le courant vers l’aval sur des sites où elles rechercheront un substrat mou pour creuser des tunnels en forme de U.</p>\r\n\r\n<p>Le stade larvaire de la lamproie du Nord persiste de trois à six ans. La durée de la vie larvaire dépend de l’emplacement et de l’accès à la nourriture. Par la suite, l’ammocète subit une métamorphose; la bouche se transforme en un entonnoir pourvu de dents et le développement des organes reproducteurs débute. Les adultes ne vivent que de quatre à six mois avant de se reproduire et de mourir.</p>', NULL, '<p>Les principales menaces qui pèsent sur la lamproie du Nord au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution agricole, urbaine et industrielle, qui engendre l’accumulation de sédiments dans le substrat de fraie et détériore la qualité de l’eau;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration, qui modifient l’écoulement et qui confinent la population dans un tronçon de cours d’eau;</li>\r\n  <li>les changements climatiques, qui causent des variations de régimes d’écoulement qui pourraient faire disparaitre des habitats peu profonds.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2', 'Menacée', 'Déléguée au Québec', 1),
(480, 'Chabot de profondeur', 'COSEPAC: chabot de profondeur, pop. des Grands Lacs et du haut Saint-Laurent', 'Deepwater Sculpin', 'Sculpin; Lake Sculoin; Deep-water Blob; Fourhorn SculpinNachtrieb Dace; Northern Minnow; Pearl Dace; Allegheny Pearl Dace;', 'Myoxocephalus thompsonii', '', '<p>Le chabot de profondeur est un petit poisson de fond peu connu au Québec, notamment parce qu’il ne vit que dans quelques lacs isolés. Il serait un proche parent du chaboisseau à quatre cornes qui vit dans l’Arctique, dans la baie James entre autres.</p>', '<p>À l’exception de quelques mentions dans certains États du nord des États-Unis, le chabot de profondeur se trouve presque exclusivement au Canada, dans les provinces de l’Ontario, du Manitoba, de la Saskatchewan, de l’Alberta, du Québec, et dans les Territoires du Nord-Ouest. Au Québec, on le retrouve dans au moins cinq lacs très profonds des régions de l’Outaouais et des Laurentides.</p>', '<p>Peu de données sont disponibles sur la taille des populations québécoises du chabot de profondeur. Il est difficile à échantillonner et rarement observé, ce qui limite les possibilités d’en apprendre davantage. La rareté de l’espèce, combinée aux menaces qui pèsent sur ses habitats, lui a valu le statut d’espèce menacée.</p>', '<p>Le chabot de profondeur vit principalement dans le fond des lacs post-glaciaires caractérisés par des eaux claires, froides et bien oxygénées. Comme la lumière ne se rend pratiquement pas à ces profondeurs, le substrat est exclusivement composé de sable, de vase et de roches, sans végétation.</p>', '<p>Le chabot de profondeur se nourrit principalement de crustacés, d’œufs et de larves d’insectes aquatiques.</p>\r\n\r\n', '<p>La période de fraie du chabot de profondeur semble varier selon le lac où il se trouve, probablement en raison des variations dans les conditions environnementales de chaque plan d’eau. Cependant, la période de reproduction se situerait entre la fin de l’été et le début de l’automne. Les mâles atteignent la maturité vers l’âge de 2 ans et les femelles vers 3 ans. Elles peuvent pondre jusqu’à 1 000 œufs par fraie.</p>', NULL, '<p>Les principales menaces qui pèsent sur le chabot de profondeur au Québec sont :</p>\r\n<ul>\r\n  <li>La pollution urbaine et forestière, qui engendre l’accumulation de sédiments dans le substrat de fraie, l’eutrophisation et l’acidification des lacs;</li>\r\n  <li>Les changements climatiques, qui causent des variations et l’augmentation de la température de l’eau.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Déléguée au Québec', 1),
(522, 'Alose savoureuse', 'alose canadienne; alose; alose d\'Amérique', 'American Shad', 'Shad; Common Shad; Atlantic Shad; White Shad', 'Alosa sapidissima', NULL, '<p>L’alose savoureuse est l’un des plus grands représentants de la famille des harengs (clupéidés). Au Québec, elle est le sujet d’une pêche commerciale marginale et sa pêche récréative suscite un engouement renouvelé d’année en année.</p>', '<p>L’aire de répartition naturelle de l’alose savoureuse s’étend sur la côte atlantique, du Labrador jusqu’à la Floride. Au 19e siècle, elle a aussi été introduite sur la côte ouest du continent de l’Amérique du Nord. Au Québec, l’espèce est présente dans le réseau du fleuve Saint‑Laurent et dans la baie des Chaleurs.</p>\r\n\r\n<p>Dans le fleuve Saint‑Laurent, l’alose savoureuse remonte jusqu’au barrage de Carillon, dans la rivière des Outaouais, à l’ouest, et jusqu’à Beauharnois, au sud. Elle se reproduirait aussi dans certains tributaires, dont les rivières Sainte-Anne, Batiscan et Richelieu.</p>', '<p>La population de l’alose savoureuse dépendrait d’une seule frayère confirmée. C’est pourquoi l’espèce a été désignée comme espèce vulnérable en 2003. Les conséquences d’une éventuelle diminution ou perte de productivité de ce site avaient mené à cette désignation. La découverte de nouvelles frayères remet en question cette convention. Cependant, comprendre la dynamique de l’espèce demeure important pour pérenniser son rétablissement.</p>', '<p>L’alose savoureuse fréquente les habitats marins et ceux d’eau douce au cours de son cycle de vie. En eau douce, les adultes reproducteurs remontent les fleuves et les rivières jusqu’aux obstacles infranchissables. Les jeunes passent le premier été en eau douce et dévalent le fleuve afin de rejoindre l’estuaire et le golfe du Saint‑Laurent à l’automne.</p>', '<p>En mer, l’espèce se nourrit surtout de crustacés planctoniques par filtration, parfois aussi de petits poissons. Lorsqu’ils migrent dans le fleuve Saint‑Laurent pour leur reproduction, les aloses adultes ne semblent pas s’alimenter. De leur côté, les larves consomment du zooplancton. Leur diète se diversifie ensuite pour incorporer des œufs d’invertébrés, de petits crustacés, des insectes et des larves d’autres espèces de poissons.</p>', '<p>L’alose savoureuse fraye au printemps. Le moment de son arrivée en eau douce dépend de la température de l’eau. Sa présence dans l’estuaire du Saint‑Laurent est détectée à partir de la mi‑mai. La femelle expulse ses œufs qui sont fécondés simultanément par les mâles. Les œufs sont libérés dans la colonne d’eau et vont se déposer sur le fond en suivant les courants. L’éclosion se produit généralement en 8 à 12 jours.</p>', NULL, '<p>Les principales menaces qui pèsent sur l’alose savoureuse sont :</p>\r\n<ul>\r\n  <li>la pêche, à cause de la mortalité lors de la remise à l’eau et de la surexploitation;</li>\r\n  <li>le braconnage, à cause du non-respect des prises quotidiennes;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration et qui modifient l’écoulement;</li>\r\n  <li>les changements climatiques, à cause des variations de température de l’eau et de la quantité de précipitations qui influencent les conditions de fraie au printemps.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Déléguée au Québec', 1),
(529, 'Cisco de printemps', 'cisco de lac, pop. de printemps; toulibi; hareng de lac', 'Spring Cisco', 'Shallowwater Cisco', 'Coregonus artedi pop. 1', NULL, '<p>Le cisco de printemps est une sous-espèce rare de cisco de lac, présente dans un seul lac au Québec (et possiblement unique en Amérique). Contrairement au cisco de lac qui fraie à l’automne, le cisco de printemps fraie au printemps, comme son nom l’indique. C’est un petit poisson qui fait partie de la famille des salmonidés.</p>', '<p>Le cisco de printemps se retrouve uniquement dans le lac des Écorces, dans la région des Laurentides. Les eaux y sont plus chaudes en profondeur l’été et le refroidissement y est lent à l’automne, ce qui retarde la maturité de ses organes sexuels. Ces conditions expliqueraient sa présence dans ce lac.</p>', '<p>Le cisco de printemps est considéré comme en situation précaire parce qu’il est présent seulement dans un lac. Ses captures ont considérablement diminué au cours des dernières décennies. Les facteurs qui retardent sa période de fraie au printemps pourraient éventuellement changer et entraîner la disparition de cette sous-espèce du cisco de lac. L’arrivée récente de l’éperlan arc-en-ciel dans le lac des Écorces, qui se nourrit des œufs du cisco de printemps, pourrait également constituer une menace pour sa survie.</p>', '<p>Le cisco de printemps fréquente principalement la zone d\'eau froide (12 °C ou moins) et profonde du lac des Écorces. En hiver, il se tient à environ 12 m de profondeur, puis entre 20 et 30 m au printemps. Ces zones sont généralement caractérisées par une couche épaisse de substrat mou, comme la vase.</p>', '<p>Le cisco de printemps se nourrit principalement de plancton, comme les copépodes et les cladocères, ainsi que de larves aquatiques d’insectes. Parfois, il peut également manger de petits poissons ou des œufs.</p>', '<p>Contrairement à ceux du cisco de lac, les organes sexuels du cisco de printemps continuent à se développer au cours de l’hiver et la fraie a lieu vers la mi-mai et au début juin. Les œufs éclosent généralement vers la fin juillet. À ce moment, les larves remontent près de la surface, probablement pour remplir leur vessie natatoire d’oxygène, mais elles restent à au moins un mètre de la surface car l’eau y est trop chaude. Ensuite, elles commencent à se nourrir. Le cisco de printemps atteint sa maturité vers l’âge de 3 ans.</p>', NULL, '<p>Les principales menaces qui pèsent sur le cisco de printemps au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution urbaine et agricole, qui engendre l\'eutrophisation et l’acidification des lacs;</li>\r\n  <li>les espèces indigènes introduites, comme l’éperlan arc-en-ciel, qui se nourrissent de ses œufs;</li>\r\n  <li>les changements climatiques, qui causent des variations et l’augmentation de température de l’eau;</li>\r\n  <li>le braconnage.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Déléguée au Québec', 1),
(551, 'Brochet vermiculé', 'brochet d\'herbe; brochet de vase; brochet de fossé', 'Grass Pickerel', 'Western Grass Pickerel; Mud Pickerel; Little Pickerel; Central Redfin Pickerel', 'Esox americanus vermiculatus', NULL, '<p>Le brochet vermiculé est une espèce de poisson prédateur de petite ou moyenne taille. Il est peu pêché, contrairement à son cousin le grand brochet, probablement en raison de sa taille plus réduite et de sa rareté dans les eaux québécoises.</p>', '<p>Le brochet vermiculé est présent en Amérique du Nord, surtout dans le nord des États-Unis, en Ontario et au Québec. Au Québec, on le trouve dans les tributaires du lac Saint-François. Il a déjà été capturé dans le lac Saint-Louis, mais ces observations datent des années 1990.</p>', '<p>Il y a peu d’information sur la taille des populations québécoises de brochet vermiculé. Cette espèce est particulièrement rare dans la province et elle est localisée dans les petits tributaires du lac Saint-François. Il est difficile de dégager des tendances pour cette espèce au Québec. Les inventaires des dernières années ont permis de documenter sa présence dans des petits cours d’eau agricoles, mais il reste à démontrer si elle y reste de façon permanente.</p>', '<p>Le brochet vermiculé fréquente principalement les secteurs calmes et bien garnis en végétation des petits cours d’eau, ainsi que les baies herbeuses des lacs fluviaux.</p>', '<p>Le brochet vermiculé se nourrit d’une grande variété de proies, telles que des petits poissons, des crustacés et des larves d’insectes. Comme les autres espèces de brochets, le brochet vermiculé est un carnivore opportuniste qui se nourrit de tout ce qu’il peut capturer. Il chasse de jour et à l’affût.</p>', '<p>La reproduction du brochet vermiculé a lieu au printemps, bien qu’elle aurait déjà été observée en automne. Il fraie dans les zones herbeuses inondées où il pond des œufs qui se fixent à la végétation.</p>', NULL, '<p>Les principales menaces qui pèsent sur le brochet vermiculé au Québec sont :</p>\r\n<ul>\r\n  <li>Le nettoyage des cours d’eau, qui retire les végétaux immergés de son habitat;</li>\r\n  <li>La modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration, qui modifient l’écoulement et qui confinent des populations dans un tronçon de cours d’eau;</li>\r\n  <li>La gestion des niveaux d’eau par barrages, qui entraine la diminution de la superficie des plaines inondables;</li>\r\n  <li>Les changements climatiques, qui causent des variations de température de l’eau et de la quantité de précipitations, ce qui influence les conditions de fraie au printemps;</li>\r\n  <li>La pollution agricole, qui provoque la disparition des herbiers aquatiques par l\'eutrophisation;</li>\r\n  <li>Le développement résidentiel et commercial, qui engendre la transformation des berges;</li>\r\n  <li>La navigation de plaisance et les vagues causées par les embarcations, qui entrainent la perte d’herbiers aquatiques;</li>\r\n  <li>La voie de navigation commerciale et les vagues causées par les embarcations, qui entrainent la perte d’herbiers aquatiques.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2', 'Vulnérable', 'Déléguée au Québec', 1),
(565, 'Méné d\'herbe', NULL, 'Bridle Shiner', 'Bridled Shiner, Brikle Shiner', 'Notropis bifrenatus', NULL, '<p>Le méné d’herbe est un petit poisson qui appartient à la famille des cyprinidés. Comme son nom l’indique, tous ses stades de vie sont intimement liés aux herbiers aquatiques. C’est un poisson particulièrement rapide qui arrive même à se reproduire lors de sa première année de vie.</p>', '<p>L’aire de répartition mondiale du méné d’herbe se limite à l’est de l’Amérique du Nord, dans les bassins hydrographiques de l’Atlantique, entre la partie ouest du lac Ontario et le Maine. Au Canada, l’espèce se trouve seulement dans l’est de l’Ontario et au sud-est de la province de Québec.\r\n</p><p>\r\nLes premières mentions de capture au Québec remontent aux années 1940, dans les régions de Montréal et du lac Saint‑Pierre. Depuis, le méné d’herbe a été observé dans les affluents de huit régions : Montréal, Laval, Montérégie, Estrie, Laurentides, Lanaudière, Mauricie et Centre-du-Québec.</p>', '<p>Au Québec, la diminution d’abondance du méné d’herbe semble être associée à celle des herbiers aquatiques, notamment dans les bassins hydrographiques des rivières aux Brochets, Châteauguay, Richelieu, Yamaska et Saint‑François, de même que dans le fleuve Saint‑Laurent dans le secteur du lac Saint‑Louis et du lac Saint‑Pierre.\r\n</p><p>\r\nUn grand nombre de spécimens a été recensé dans le tronçon du fleuve Saint‑Laurent, entre Montréal et Sorel, ainsi que dans le lac Saint‑Pierre et son archipel. Cette espèce semble tout de même abondante dans certaines portions de son aire de répartition au Québec. De nouvelles populations ont aussi été découvertes dans plusieurs sous-bassins versants de la rivière Saint‑François, en Estrie.</p>', '<p>Le méné d’herbe vit dans les zones calmes des rivières, des ruisseaux et des lacs. Cette espèce se trouve habituellement en présence d’une végétation aquatique submergée abondante. Il peut être présent en nombre considérable dans ce type d’habitat où il se reproduit, s’abrite des prédateurs et s’alimente.</p>', '<p>Le méné d’herbe se nourrit de petits crustacés zooplanctoniques et de larves d’insectes.</p>', '<p>Les peuplements de myriophylle indigènes semblent les plus propices à l’espèce lors de la fraie et l’alevinage.\r\n</p><p>\r\nLe méné d’herbe fraie au printemps et en début d’été (mai à juillet) aux États-Unis (peu d’information ailleurs), mais la fraie peut se prolonger jusqu’en août. À ce moment, les adultes se tiendront à quelques centimètres au-dessus de la canopée de végétation aquatique où les œufs seront libérés en petites quantités. Une fois pondus, les œufs coulent et adhèrent au substrat. L’éclosion a lieu en 2 ou 3 jours lorsque la température est aux environs de 24 °C. Les alevins sont pourvus de glandes leur permettant d’adhérer aux plantes et demeurent d’abord cachés dans la végétation.\r\n</p><p>\r\nLe cycle de vie du méné d’herbe est court. La longévité de ce poisson serait d’environ 2 ans. La maturité sexuelle serait atteinte dès la première année chez les mâles, alors que, chez la grande majorité des femelles, elle est atteinte à 1 an.\r\n</p><p>\r\nÀ l’approche de la période de reproduction, les mâles se distinguent par leur coloration jaune brillant et la présence de petites excroissances (tubercules) sur les nageoires pectorales, la tête et la nuque. Les nageoires des individus des deux sexes deviennent jaunes peu de temps avant la période de fraie.</p>', NULL, '<p>Les principales menaces qui pèsent sur le méné d’herbe au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution agricole, urbaine et industrielle, qui provoque la disparition des herbiers aquatiques par eutrophisation;</li>\r\n  <li>le développement résidentiel et commercial, qui engendre la transformation des berges, ce qui inclut les zones portuaires;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration, qui modifient l’écoulement et qui confinent des populations dans un tronçon de cours d’eau;</li>\r\n  <li>la navigation de plaisance et les vagues causées par les embarcations, qui entrainent la perte d’herbiers aquatiques;</li>\r\n  <li>la voie de navigation commerciale et les vagues causées par les embarcations, qui entrainent la perte d’herbiers aquatiques.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Déléguée au Québec', 1),
(587, 'Chevalier de rivière', 'suceur ballot; moxostome ballot', 'River Redhorse', 'River Mullet', 'Moxostoma carinatum', NULL, '<p>Le chevalier cuivré est une espèce menacée dont la pêche est interdite. Il est la seule espèce vertébrée dont l’aire de répartition est exclusive à la province de Québec.</p>', '<p>Le chevalier de rivière est présent dans tout le centre et l’est du réseau hydrographique du Mississippi ainsi que dans le golfe du Mexique, plus précisément dans les États de la Floride et de la Louisiane. C’est un poisson rare au Canada. Des populations ne sont aujourd’hui présentes que dans quelques réseaux fluviaux de l’est de l’Ontario et du sud-ouest du Québec. L’espèce atteint le nord-est de son aire de répartition au Québec et ses populations sont géographiquement séparées des populations américaines.\r\n</p><p>\r\nDans cette dernière province, l’espèce semble répartie en deux grands secteurs. Le premier se trouve dans la rivière des Outaouais, entre Rapide-des-Joachims et le barrage de Carillon. L’autre se situe dans le fleuve Saint-Laurent près du lac Saint-Pierre et dans la rivière Richelieu (en aval de Chambly). Quelques captures récentes de chevaliers de rivière ont également été effectuées dans les rivières Yamaska, Noire et Saint-François.</p>', '<p>Il est difficile de statuer avec précision sur l’abondance des populations du chevalier de rivière. Cette espèce est rarement capturée dans les suivis provinciaux, mais ceux-ci ne sont majoritairement pas conçus à cette fin. La détérioration des herbiers aquatiques submergés nuit beaucoup au rétablissement de l’espèce. Ce type d’habitat est essentiel, surtout pour les jeunes stades de vie.</p>', '<p>Le chevalier cuivré adulte fréquente principalement les herbiers des zones peu profondes autour des îles et des archipels du fleuve Saint-Laurent et des rivières Richelieu, des Prairies et des Mille Îles.</p>\r\n\r\n<p>Les jeunes chevaliers cuivrés de moins de deux ans fréquentent les zones littorales peu profondes, pourvues de végétation et d’un substrat relativement fin.</p>\r\n\r\n<p>Les habitats fréquentés par les juvéniles de plus de 2 ans restent actuellement peu connus. Bien que les chevaliers cuivrés de cette gamme de taille soient plus souvent recensés depuis 2015, leur capture demeure un défi. Ils vivraient principalement dans les grands herbiers de la rivière Richelieu et du fleuve Saint-Laurent.</p>\r\n', '<p>À l’âge adulte, le chevalier de rivière se nourrit de petits mollusques, de gastéropodes, de crustacés et de larves d’insectes.</p>', '<p>La fraie du chevalier de rivière a lieu au printemps, soit de la fin de mai à la fin de juin selon les secteurs. Elle se déroule en eau vive et peu profonde, sur des substrats graveleux. Les larves sont entraînées vers l’aval par le courant après l’éclosion.\r\n</p><p>\r\nL’espèce peut vivre environ 20 ans. L’âge maximal observé serait de 28 ans. Sa maturité sexuelle est atteinte entre 7 et 10 ans.\r\n</p><p>\r\nAvant et pendant la période de reproduction, des excroissances (tubercules nuptiaux) sont présentes sur les nageoires anale et caudale des mâles. Chez les femelles, ces excroissances sont visibles durant la période de reproduction dans la partie inférieure de leurs nageoires.</p>', NULL, '<p>Les principales menaces qui pèsent sur le chevalier de rivière au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution agricole, urbaine et industrielle, qui provoque la disparition des herbiers aquatiques par eutrophisation;</li>\r\n  <li>le développement résidentiel et commercial, qui engendre la transformation des berges;</li>\r\n  <li>les pêches commerciale, récréative ou de subsistance et le braconnage, à cause des prises accidentelles;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration et qui modifient l’écoulement;</li>\r\n  <li>la présence d’espèces exotiques envahissantes, comme les moules zébrées et quagga, qui accumulent des polluants;</li>\r\n  <li>la navigation de plaisance et les vagues causées par les embarcations, qui entraînent la perte d’herbiers aquatiques;</li>\r\n  <li>la voie de navigation commerciale et les vagues causées par les embarcations, qui entraînent la perte d’herbiers aquatiques.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2S3', 'Vulnérable', 'Déléguée au Québec', 1),
(588, 'Chevalier cuivré', 'suceur cuivré; moxostome cuivré; carpe cuivrée', 'Copper Redhorse', '', 'Moxostoma hubbsi', '', '<p>Le chevalier cuivré est une espèce menacée dont la pêche est interdite. Il est la seule espèce vertébrée dont l’aire de répartition est exclusive à la province de Québec.</p>', '<p>Le chevalier cuivré se trouve uniquement au Québec. Il vit dans un tronçon du fleuve Saint-Laurent entre l’île Perrot et le lac Saint-Pierre, ainsi que dans la rivière Richelieu jusqu’à Chambly. Il fréquente aussi les rivières des Mille Îles, des Prairies, L’Acadie et Saint-François jusqu’aux premiers obstacles infranchissables. Des individus ont déjà été observés dans les rivières Yamaska et Noire. Cependant, aucune capture n’y a été faite depuis plusieurs décennies, malgré des efforts d’échantillonnage considérables.</p>', '<p>L’abondance actuelle du chevalier cuivré est faible. Les travaux d’inventaire dans son aire de répartition montrent que davantage d’individus adultes et plus jeunes (subadultes) sont présents, ce qui est un signal encourageant. Statuer avec plus de précisions sur la tendance de la population est difficile. La détérioration des herbiers aquatiques submergés nuit beaucoup au rétablissement de l’espèce. Ce type d’habitat est essentiel à toutes les étapes de son cycle de vie.</p>', '<p>Le chevalier cuivré adulte fréquente principalement les herbiers des zones peu profondes autour des îles et des archipels du fleuve Saint-Laurent et des rivières Richelieu, des Prairies et des Mille Îles.</p>\r\n\r\n<p>Les jeunes chevaliers cuivrés de moins de deux ans fréquentent les zones littorales peu profondes, pourvues de végétation et d’un substrat relativement fin.</p>\r\n\r\n<p>Les habitats fréquentés par les juvéniles de plus de 2 ans restent actuellement peu connus. Bien que les chevaliers cuivrés de cette gamme de taille soient plus souvent recensés depuis 2015, leur capture demeure un défi. Ils vivraient principalement dans les grands herbiers de la rivière Richelieu et du fleuve Saint-Laurent.</p>\r\n', '<p>À l’âge adulte, le chevalier cuivré se nourrit presque exclusivement de mollusques et de gastéropodes. Il parvient à les broyer grâce à son appareil pharyngien spécialisé, situé dans sa gorge, muni de dents robustes en forme de molaires. Les jeunes mangent de petits crustacés (cladocères, copépodes et ostracodes), des larves d’insectes et d’autres organismes de petite taille.</p>', '<p>Le chevalier cuivré effectue une migration de reproduction qui débute vers la fin du printemps. À ce moment, les reproducteurs quittent leurs habitats d’alimentation pour rejoindre les frayères. La fraie a lieu en eau vive, habituellement entre la mi-juin et le mois de juillet, lorsque la température de l’eau atteint près de 21 °C. Les frayères sont en eau vive, à des profondeurs variant de 0,75 à 2 m. Elles sont sur des sites qui possèdent un fond varié, composé de roche et de gravier (fin à grossier) et parfois de grosses roches enlisées dans l’argile.</p>\r\n\r\n<p>Quelques jours après la ponte, les larves éclosent et dévalent avec le courant vers les herbiers, où ils vont s’alimenter et croître.</p>\r\n\r\n<p>La maturité sexuelle est atteinte assez tard, soit vers 8 à 10 ans.</p>', NULL, '<p>Les principales menaces qui pèsent sur le chevalier cuivré au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution agricole, urbaine et industrielle, qui provoque la disparition des herbiers aquatiques par eutrophisation;</li>\r\n  <li>le développement résidentiel et commercial, qui engendre la transformation des berges;</li>\r\n  <li>la pêche, à cause des prises accidentelles;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration et qui modifient l’écoulement;</li>\r\n  <li>la présence d’espèces exotiques envahissantes, comme les moules zébrées et quagga, qui accumulent des polluants;</li>\r\n  <li>la navigation de plaisance et les vagues causées par les embarcations, qui entrainent la perte d’herbiers aquatiques;</li>\r\n  <li>la voie de navigation commerciale et les vagues causées par les embarcations, qui entrainent la perte d’herbiers aquatiques.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Déléguée au Québec', 1),
(592, 'Chat-fou des rapides', 'barbotte des rapides', 'Stonecat', 'Stone Catfish; Stonecat Madtom; White Cat; Doogler', 'Noturus flavus', 'Le nom commun français diffère de celui utilisé dans la publication \"American Fisheries Society (2013) Common and Scientific Names of Fishes from the United States, Canada, and Mexico, 7th edition\", mais sera révisé lors de la prochaine publication.', '<p>Le chat-fou des rapides est un petit poisson de fond. Il appartient à la même famille que la barbue de rivière et les barbottes.</p>', '<p>Le chat-fou des rapides est présent dans la partie centrale de l’Amérique du Nord. On le trouve principalement dans le grand bassin du Saint-Laurent, remontant dans les lacs Ontario et Érié, et jusqu’au bassin du Missouri à l’ouest. Au Québec, l’espèce a été signalée dans le Saint-Laurent jusqu’aux rivières du Sud et Bras Saint-Nicolas, dans plusieurs des tributaires du fleuve, dont les rivières Châteauguay, Nicolet et Yamaska, ainsi que dans quelques tributaires de la rivière des Outaouais. Cette espèce a été peu étudiée, ce qui fait que sa répartition pourrait être plus grande que celle qui est connue actuellement.</p>', '<p>Le chat-fou des rapides est un poisson nocturne qui se nourrit de différentes proies, dont des larves d’insectes, des mollusques, des petits poissons, ainsi que des végétaux.</p>', '<p>Le chat-fou des rapides fréquente principalement des rivières aux eaux vives, où le substrat est composé de sable, de gravier et de grosses roches qui émergent généralement à la surface. L’espèce a aussi été capturée dans des lacs (Grands Lacs), ainsi que dans le Saint-Laurent jusqu’à une profondeur de 14 m. Dans les rivières, il partage souvent les mêmes habitats que l’achigan à petite bouche, qui est l’un de ses prédateurs.</p>', '<p>Au Québec, la reproduction du chat-fou des rapides a lieu en été. Le mâle creuse une petite fosse sous les roches, qui servira de nid, où la femelle dépose une masse d’œufs jaunâtres. Le mâle surveille les œufs fécondés et les jeunes jusqu’à quelques jours après l’éclosion. </p>', '<p>Au Québec, la reproduction du chat-fou des rapides a lieu en été. Le mâle creuse une petite fosse sous les roches, qui servira de nid, où la femelle dépose une masse d’œufs jaunâtres. Le mâle surveille les œufs fécondés et les jeunes jusqu’à quelques jours après l’éclosion.</p>', NULL, '<p>Les principales menaces qui pèsent sur le chat-fou des rapides au Québec sont :</p>\r\n<ul>\r\n  <li>La pollution agricole, urbaine et industrielle, qui engendre l’accumulation de sédiments dans le substrat de fraie et détériore la qualité de l’eau;</li>\r\n  <li>Le développement résidentiel et commercial, qui engendre la transformation des berges;</li>\r\n  <li>La modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration, qui modifient l’écoulement et qui confinent des populations dans un tronçon de cours d’eau;</li>\r\n  <li>Le prélèvement des eaux souterraines et de surface, qui peut diminuer la quantité d’habitats peu profonds des cours d’eau;</li>\r\n  <li>Les changements climatiques, qui provoquent des variations dans les régimes d’écoulement, ce qui peut faire disparaitre des habitats peu profonds;</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Déléguée au Québec', 1),
(638, 'Dard de sable', 'COSEPAC: dard de sable, pop. du Québec; dard de sable du nord', 'Eastern Sand Darter', 'Sand Darter; Northern Sand Darter; Sand Darter', 'Ammocrypta pellucida', '', '<p>Espèce menacée au Québec, le dard de sable est un petit poisson qui appartient à la famille des percidés. Il s’enfouit généralement dans le sable, ne laissant que ses yeux découverts.</p>', '<p>Le dard de sable vit uniquement dans l’est de l’Amérique du Nord. Sa répartition est discontinue et se compose de deux aires disjointes : une aire principale concentrée dans le nord-est des États-Unis et dans l’extrême sud de l’Ontario (aire du Sud) et une autre, beaucoup plus petite et isolée de la précédente, située au sud du Québec (aire du Nord). </p>\r\n\r\n<p>Au Québec, la répartition du dard de sable est discontinue. L’espèce vit dans le fleuve Saint-Laurent et dans certains de ses tributaires situés entre le lac des Deux Montagnes et Leclercville, en aval du lac Saint-Pierre, marquant la limite nord de son aire de distribution connue. </p>', '<p>tendances pour cette espèce au Québec. Les inventaires réalisés ces dernières années ont permis de confirmer la présence de l’espèce dans tous les sites historiques et notamment dans le lac des Deux Montagnes où la disparition de l’espèce était présumée. Selon l’analyse des données disponibles en 2010, la rivière aux Saumons est celle qui abriterait la population la plus abondante et étant considérée comme en bon état. Les rivières Richelieu, L’Assomption, Ouareau et aux Saumons semblent toutes abriter des populations relativement stables. En contrepartie, les populations des rivières Châteauguay, Yamaska et Saint-François sont probablement en déclin et semblent en mauvais état.</p>', '<p>Le dard de sable est un poisson sédentaire qui s’enfouit généralement dans le sable. Il ne laisse que ses yeux découverts et demeure à l’affût. Ce comportement lui permettrait de se cacher des prédateurs, de diminuer les dépenses énergétiques associées à la nage dans un courant ou, encore, de maintenir sa position sur un substrat homogène. Il se trouve en cours d’eau, en rivières ou en lacs. Ces lieux lui offrent des fonds sablonneux, exposés à des courants suffisamment faibles pour maintenir le sable en place et suffisamment élevés pour prévenir l’envasement. Il préfère les eaux claires où la végétation aquatique est absente ou clairsemée.</p>', '<p>Le dard de sable se nourrit d’invertébrés vivant au fond de l’eau. Il mange en grande partie des larves aquatiques d’insectes, dont celles de moucherons et de mouches noires, mais aussi de crustacés microscopiques et de mollusques selon les saisons.</p>', 'p>Dans l’ensemble de l’aire de répartition, la fraie a lieu entre les mois d’avril et août, soit de la fin du printemps jusqu’à l’été. Au Québec, la fraie pourrait débuter vers la fin du mois de juin. Les œufs sont pondus et enfouis dans un substrat bien oxygéné, composé principalement de sable. Les adultes dards de sable ne prodiguent aucun soin parental.</p>\r\n<p>\r\nLa maturité sexuelle est atteinte à 1 an chez le mâle et vers 1 ou 2 ans chez la femelle.</p>', NULL, '<p>Les principales menaces qui pèsent sur le dard de sable au Québec sont :</p>\r\n<ul>\r\n  <li>le développement résidentiel et commercial, qui engendre la transformation des berges;</li>\r\n  <li>la pollution agricole, urbaine et industrielle, qui engendre l’accumulation de sédiments dans le substrat de fraie et détériore la qualité de l’eau;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration et qui modifient l’écoulement;</li>\r\n  <li>la présence d’espèces exotiques envahissantes, dont le gobie à taches noires;</li>\r\n  <li>les changements climatiques, qui provoquent des variations des régimes d’écoulement pouvant faire disparaitre des habitats peu profonds.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2', 'Menacée', 'Déléguée au Québec', 1);
INSERT INTO `especes` (`id`, `nom_francais`, `autres_noms_francais`, `nom_anglais`, `autres_noms_anglais`, `nom_scientifique`, `commentaires`, `description`, `repartition`, `etat_situation`, `habitat`, `alimentation`, `reproduction`, `comportement`, `menaces`, `statuts_des_populations`, `rang_S`, `statut_LEMV`, `competence_principale`, `groupe_id`) VALUES
(646, 'Fouille-roche gris', 'dard gris; petit gris des chenaux; dard gris', NULL, 'Copeland\'s Darter', 'Percina copelandi', NULL, '<p>Le fouille-roche gris est un petit poisson de fond. Il appartient à la famille des percidés qui comprend des espèces comme la perchaude et le doré jaune.</p>', '<p>Le fouille-roche gris est présent uniquement en Amérique du Nord. Sa répartition est discontinue, fortement localisée et s’étend sur un vaste territoire, à l’ouest de la chaîne des Appalaches.\r\n</p><p>\r\nAu Québec, l’espèce est à la limite nord de son aire de répartition mondiale. Les populations de fouille-roche gris se trouvent dans le fleuve Saint‑Laurent et plusieurs de ses grands tributaires, comme les rivières des Outaouais, Richelieu, L’Assomption, Saint‑François, Bécancour, Nicolet et du Sud, près de Montmagny.\r\n</p><p>\r\nDepuis 1995, des inventaires ont permis de découvrir des populations qui étaient inconnues et d’en invalider. La présence de l’espèce dans ces nouveaux plans d’eau est probablement due à l’intensification de l’échantillonnage plutôt qu’à l’élargissement de son aire de répartition ou, encore, à l’accroissement de son abondance au Québec.</p>', '<p>Le fouille-roche gris est rare et sa répartition au Québec est isolée des autres populations d’Amérique du Nord. Des échantillonnages ponctuels pour valider les mentions historiques laissent croire que certaines populations seraient disparues, notamment dans les rivières aux Bluets, Niger, Maskinongé et Chicot.\r\n</p><p>\r\nMalgré l’augmentation des mentions dans plusieurs bassins versants du Québec depuis 2010, le fouille‑roche gris demeure rarement observé. La tendance des populations est difficile à déterminer, car le nombre d’observations recueillies chaque année est faible. Pour contrer le déclin des populations, il importe de poursuivre l’amélioration de la qualité de l’eau et des habitats fréquentés par l’espèce.</p>', '<p>Dans son aire de répartition connue, le fouille-roche gris est observé dans différents types d’habitats allant du fleuve Saint‑Laurent jusqu’à de petits ruisseaux. Dans les rivières et petits cours d’eau, il est souvent associé à un substrat mixte généralement composé de sable, de gravier, de roche et de blocs, où la végétation est dispersée.</p>', '\r\n<p>Le fouille-roche gris se nourrit de proies qu’il retrouve sur le fond des cours d’eau. Son alimentation se compose surtout d’insectes. Il mange plus particulièrement des larves d’éphémères et de moucherons, mais aussi de grandes quantités d’algues et de débris végétaux.</p>', '<p>Au Québec, la reproduction aurait lieu de mai à juillet, sur un substrat composé de roches et de gravier avec une faible proportion de sable et de blocs. Les mâles établissent alors des territoires d’environ un mètre de diamètre autour d’une grosse roche. De leur côté, les femelles se déplacent d’un territoire à l’autre et s’accouplent successivement avec plusieurs mâles.\r\n</p><p>\r\nLe nombre total d’œufs déposés par une femelle de 1 à 2 ans serait de l’ordre de 350 à 700 œufs, mais ceux-ci seraient déposés en petites quantités (4 à 10 œufs) dans le substrat.\r\n</p><p>\r\nLes adultes quittent les frayères peu de temps après la reproduction et abandonnent les œufs enfouis dans le gravier.</p>', NULL, '<p>Les principales menaces qui pèsent sur le fouille-roche gris au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution agricole, urbaine et industrielle, qui engendre l’accumulation de sédiments dans le substrat de fraie et détériore la qualité de l’eau;</li>\r\n  <li>le développement résidentiel et commercial, qui engendre la transformation des berges;</li>\r\n  <li>la modification des systèmes naturels par les barrages, qui représentent des obstacles à la migration, qui modifient l’écoulement et qui confinent des populations dans un tronçon de cours d’eau;</li>\r\n  <li>les espèces exotiques envahissantes comme le gobie à taches noires;</li>\r\n  <li>les changements climatiques, qui provoquent des variations des régimes d’écoulement pouvant faire disparaitre des habitats peu profonds.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Déléguée au Québec', 1),
(728, 'Petite chauve-souris brune', 'vespertilion brun; chauve-souris brune', 'Little Brown Myotis', '', 'Myotis lucifugus', '', '<p>La petite chauve-souris brune est l’une des huit espèces de chauves-souris du Québec. Ce petit mammifère volant est surtout actif la nuit.</p>', '<p>La petite chauve-souris brune vit dans la majeure partie de l’Amérique du Nord, dont l’ensemble des provinces et des territoires du Canada, à l’exception du Nunavut. Au Québec, cette espèce est bien répartie dans le sud de la province. Cependant, il est difficile de savoir jusqu’à quelle latitude elle peut survivre.</p>', '<p>Les populations de petites chauves-souris brunes ont subi de graves déclins au Québec depuis l’arrivée du syndrome du museau blanc au Québec en 2010. Leurs populations ont diminué de plus de 78 à 100 % depuis l’apparition de cette infection fongique.</p>', '<p>La petite chauve-souris brune compte parmi l’une des cinq espèces résidentes de chauves-souris du Québec. Son hibernation s’étend de la fin septembre/mi-octobre jusqu’à la fin avril/début juin. Elle peut hiberner dans les mines désaffectées et les cavités naturelles creusées dans la roche, comme les grottes et les cavernes.</p>\r\n\r\n<p>Durant l’été, la petite chauve-souris brune se repose :</p>\r\n<ul>\r\n    <li>Sous les écorces soulevées des arbres;</li>\r\n    <li>Dans des trous et des fissures des troncs d’arbres;</li>\r\n    <li>Dans des crevasses rocheuses;</li>\r\n    <li>Dans des abris sous les roches;</li>\r\n    <li>Dans les bâtiments.</li>\r\n</ul>\r\n\r\n<p>Les sites de colonies de maternités sont utilisés par les femelles reproductives pour mettre bas et allaiter les nouveau-nés. Ces sites peuvent se trouver dans des bâtiments et des trous d’arbres creux ou morts à gros tronc. Ils peuvent compter des centaines de femelles accompagnées de leurs petits.</p>\r\n', '<p>La petite chauve-souris brune se nourrit d’insectes et s’active de nuit. Pour se repérer dans l’obscurité, elle émet des ondes sonores qui rebondissent sur les éléments qui l’entourent, puis capte l’écho qui revient à ses oreilles : c’est ce qu’on appelle l’écholocalisation. Elle arrive ainsi à se représenter son environnement sans le voir, ce qui lui permet de localiser et de capturer ses proies en vol. Cette espèce consomme une importante quantité d’insectes jugés nuisibles à l’agriculture et la foresterie. Par exemple, en une heure seulement, elle peut capturer jusqu’à 600 insectes.</p>\r\n\r\n<p>Elle s’alimente dans les endroits qui favorisent une production élevée d’insectes, tels que :</p>\r\n<ul>\r\n  <li>sous le couvert forestier;</li>\r\n  <li>dans les trouées;</li>\r\n  <li>dans les milieux humides;</li>\r\n  <li>à l’orée des boisés;</li>\r\n  <li>à proximité ou en bordure des plans d’eau.</li>\r\n</ul>\r\n', '<p>La petite chauve-souris brune est polygame. L’accouplement a lieu pendant les périodes de regroupement à la fin de l’été, à l’automne ou en hiver. L’implantation et la fertilisation de l’ovule sont retardées jusqu’au printemps, ce qu’on appelle « fécondation différée ».</p>\r\n\r\n<p>Les naissances ont généralement lieu de la mi-juin au début de juillet. Cette espèce peut avoir un jeune par année. Les nouveau-nés sont sevrés après 3 à 4 semaines, période à laquelle ils commencent à voler.</p>', NULL, '<p>Actuellement, le syndrome du museau blanc est la plus importante cause de mort chez cette espèce. En plus de cette infection, les principales menaces qui pèsent sur la petite chauve-souris brune sont :</p>\r\n<ul>\r\n  <li>le dérangement humain dans les grottes et les mines (qui lui servent d’aires d’hivernage);</li>\r\n  <li>le vandalisme et la persécution;</li>\r\n  <li>l’exclusion et l’extermination;</li>\r\n  <li>le développement résidentiel et commercial;</li>\r\n  <li>l’activité minière;</li>\r\n  <li>les éoliennes;</li>\r\n  <li>les contaminants agricoles.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Québec', 2),
(730, 'Chauve-souris nordique', 'vespertilion nordique', 'Northern Myotis', '', 'Myotis septentrionalis', '', '<p>La chauve-souris nordique est l’une des huit espèces de chauves-souris du Québec. Ce petit mammifère volant est surtout actif la nuit.</p>', '<p>La chauve-souris nordique fréquente principalement le sud du Canada et l’est des États-Unis. Elle est plus commune dans le centre et l’est du Canada et dans le nord des États‑Unis. Elle fréquente toutes les provinces et tous les territoires du Canada, à l’exception du Nunavut. Au Québec, l’espèce est bien répartie dans le sud de la province. Toutefois, il est difficile de savoir jusqu’à quelle latitude elle peut survivre. Des observations ont néanmoins été confirmées jusqu’au nord du 52e parallèle.</p>', '<p>Les populations de chauves-souris nordiques ont subi de graves déclins depuis l’arrivée du syndrome du museau blanc au Québec en 2010. Leurs populations ont diminué de 98 % depuis l’apparition de cette infection fongique.</p>', '<p>La chauve-souris nordique compte parmi l’une des troupes de cinq espèces résidentes de chauves-souris du Québec. Son hibernation s’étend de la fin septembre/mi-octobre jusqu’à la fin avril/début juin. Elle peut hiberner dans les mines désaffectées et les cavités naturelles creusées dans la roche, comme les grottes et les cavernes.</p>\r\n\r\n<p>Durant l’été, la chauve-souris nordique se repose :</p>\r\n<ul>\r\n    <li>Sous les écorces soulevées des arbres;</li>\r\n    <li>Dans des trous et des fissures de troncs d’arbres;</li>\r\n    <li>Dans des crevasses rocheuses;</li>\r\n    <li>Dans des abris sous les roches;</li>\r\n    <li>Dans les bâtiments, bien que cela soit moins fréquent que chez la petite chauve-souris brune.</li>\r\n</ul>\r\n\r\n<p>Les sites de colonies de maternités sont utilisés par les femelles reproductives pour mettre bas et allaiter les nouveau-nés. Ces sites peuvent être dans des bâtiments et des cavités d’arbres creux ou morts à gros tronc.</p>\r\n', '<p>La chauve-souris nordique se nourrit d’insectes et s’active de nuit. Pour se repérer dans l’obscurité, elle émet des ondes sonores qui rebondissent sur les éléments qui l’entourent, puis capte l’écho qui revient à ses oreilles : c’est ce qu’on appelle l’écholocalisation. Elle arrive ainsi à se représenter son environnement sans le voir, ce qui lui permet de localiser et de capturer ses proies en vol.</p>\r\n\r\n<p>Elle s’alimente dans les endroits qui favorisent une production élevée d’insectes, tels que :</p>\r\n<ul><li>\r\nsous le couvert forestier;</li><li>\r\ndans les trouées;</li><li>\r\nà l’orée des boisés;</li><li>\r\nà proximité ou en bordure des plans d’eau.</li><ul>', '<p>La chauve-souris nordique est polygame. L’accouplement a lieu pendant les périodes de regroupement à la fin de l’été, à l’automne ou en hiver. L’implantation et la fertilisation de l’ovule sont retardées jusqu’au printemps, ce qu’on appelle « fécondation différée ».</p>\r\n\r\n<p>Les naissances ont généralement lieu de la mi‑juin au début de juillet. Cette espèce peut donner naissance à un jeune par année. Les nouveau-nés sont sevrés après trois à quatre semaines, période à laquelle ils commencent à voler.</p>', NULL, '<p>Actuellement, le syndrome du museau blanc est la plus importante cause de mort chez cette espèce. En plus de cette infection, les principales menaces qui pèsent sur la chauve-souris nordique sont :</p>\r\n<ul>\r\n  <li>le dérangement humain dans les grottes et les mines (qui sont des aires d’hivernage pour elle);</li>\r\n  <li>le vandalisme et la persécution;</li>\r\n  <li>l’exclusion et l’extermination;</li>\r\n  <li>le développement résidentiel et commercial;</li>\r\n  <li>l’activité minière;</li>\r\n  <li>les éoliennes;</li>\r\n  <li>les contaminants agricoles.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Québec', 2),
(732, 'Pipistrelle de l\'Est', '', 'Tricolored Bat', 'Eastern Pipistrelle', 'Perimyotis subflavus', NULL, '<p>La pipistrelle de l’Est est l’une des huit espèces de chauves-souris du Québec. Ce petit mammifère volant est classé comme une espèce susceptible d’être désignée menacée ou vulnérable.</p>', '<p>La pipistrelle de l’Est vit sur la côte de l’océan Atlantique, de la Nouvelle‑Écosse jusqu’au Mexique ainsi qu’à l’ouest, jusqu’au centre des États‑Unis. Au Canada, elle fréquente le Nouveau‑Brunswick, le Québec et l’Ontario. Au Québec, elle a été détectée dans toutes les régions à l’exception du Saguenay–Lac‑Saint‑Jean, de la Côte‑Nord, du Nord‑du‑Québec et de Laval.</p>', '<p>Les populations de pipistrelles de l’Est ont subi de graves déclins depuis l’arrivée du syndrome du museau blanc au Québec en 2010. Leurs populations ont diminué de 75 % depuis l’apparition de cette infection fongique.</p>', '<p>La pipistrelle de l’Est compte parmi l’une des cinq espèces résidentes de chauves-souris du Québec. Son hibernation s’étend de la fin septembre/mi-octobre jusqu’à la fin avril/début juin. Elle peut hiberner dans les mines désaffectées et les cavités naturelles creusées dans la roche, comme les grottes et les cavernes.</p>\r\n\r\n<p>Durant l’été, la pipistrelle de l’Est se repose :</p>\r\n<ul>\r\n    <li>Dans des cavités;</li>\r\n    <li>Dans le feuillage;</li>\r\n    <li>Dans le lichen.</li>\r\n</ul>\r\n\r\n<p>En général, la pipistrelle de l’Est évite les habitats forestiers fragmentés. Les sites de colonies de maternités sont utilisés par les femelles reproductives pour mettre bas et allaiter les nouveau-nés. Ces sites comportent surtout des trous d’arbres creux ou morts à gros troncs.</p>\r\n', '<p>La pipistrelle de l’Est se nourrit d’insectes et s’active de nuit. Pour se repérer dans l’obscurité, elle émet des ondes sonores qui rebondissent sur les éléments qui l’entourent, puis capte l’écho qui revient à ses oreilles : c’est ce qu’on appelle l’écholocalisation. Elle arrive ainsi à se représenter son environnement sans le voir, ce qui lui permet de localiser et de capturer ses proies en vol.</p>\r\n\r\n<p>Elle s’alimente dans les endroits qui favorisent une production élevée d’insectes, tels que :</p>\r\n<ul>\r\n  <li>sous le couvert forestier;</li>\r\n  <li>dans les trouées;</li>\r\n  <li>à l’orée des boisés;</li>\r\n  <li>à proximité ou en bordure des plans d’eau.</li>\r\n</ul>\r\n', '<p>La pipistrelle de l’Est est polygame. L’accouplement a lieu pendant les périodes de regroupement à la fin de l’été, à l’automne ou en hiver. L’implantation et la fertilisation de l’ovule sont retardées jusqu’au printemps, ce qu’on appelle « fécondation différée ».</p>\r\n\r\n<p>Les naissances ont généralement lieu de la mi‑juin au début de juillet. Cette espèce peut avoir 2 jeunes par année. Les nouveau‑nés sont sevrés après trois à quatre semaines, période à laquelle ils commencent à voler.</p>', NULL, '<p>Actuellement, le syndrome du museau blanc est la plus importante cause de mort chez cette espèce. En plus de cette infection, les principales menaces qui pèsent sur la pipistrelle de l’Est sont :</p>\r\n<ul>\r\n  <li>le dérangement humain dans les grottes et les mines (aires d’hivernage);</li>\r\n  <li>le vandalisme et la persécution;</li>\r\n  <li>l’exclusion et l’extermination;</li>\r\n  <li>le développement résidentiel et commercial;</li>\r\n  <li>l’activité minière;</li>\r\n  <li>les éoliennes;</li>\r\n  <li>les contaminants agricoles.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Québec', 2),
(734, 'Chauve-souris rousse de l\'Est', 'chauve-souris rousse, chauve-souris rouge', 'Eastern Red Bat', NULL, 'Lasiurus borealis', NULL, '<p>La chauve-souris rousse est l’une des huit espèces de chauves-souris du Québec. Ce petit mammifère volant est classé comme une espèce susceptible d’être désignée menacée ou vulnérable.</p>', '<p>La chauve-souris rousse vit du centre-est de l’Amérique du Nord jusqu’au nord-est du Mexique. Au Canada, elle est répertoriée du sud-est de la Colombie‑Britannique jusqu’à la Nouvelle‑Écosse et dans le sud de Terre‑Neuve‑et‑Labrador. Il n’y a aucune mention de cette espèce au Yukon, dans les Territoires‑du‑Nord‑Ouest ni au Nunavut. Au Québec, elle est bien répartie dans le sud de la province. Toutefois, il est difficile de savoir jusqu’à quelle latitude elle peut survivre. Des observations ont néanmoins été confirmées jusqu’au sud du 52e parallèle.</p>', '<p>Peu de données font état de la dynamique des populations de chauves-souris rousses au Québec, en particulier avant la fin des années 2000. Aujourd’hui, le Réseau d’inventaires acoustiques Chirops et le Réseau de suivi de la biodiversité, par l’entremise de stations fixes d’enregistrement, collectent des données. Elles démontrent que le taux de détection de cette espèce est en augmentation, mais demeure plutôt bas.</p>', '<p>La chauve-souris rousse est l’une des trois espèces de chauves‑souris migratrices qui fréquentent le Québec. Elle quitte nos latitudes de septembre à novembre, puis migre sur de longues distances vers le sud pour échapper aux conditions hivernales du Québec. Certaines hibernent dans le sud‑est des États‑Unis ou dans le nord‑est du Mexique, mais la majorité se retrouve sur la côte de l’océan Atlantique et du golfe du Mexique. Au printemps, elles entreprennent leur migration vers le nord en avril pour revenir au Québec en mai.\r\n</p><p>\r\nDurant l’été, la chauve-souris rousse se repose dans le feuillage d’arbres de grande taille, dans divers types de milieux forestiers (feuillus, résineux ou mixtes). Suspendue aux branches la tête en bas, elle peut être confondue avec une feuille morte ou un cône de pin.</p>', '<p>La chauve-souris rousse se nourrit d’insectes et s’active de nuit. Pour se repérer dans l’obscurité, elle émet des ondes sonores qui rebondissent sur les éléments qui l’entourent, puis capte l’écho qui revient à ses oreilles : c’est ce qu’on appelle l’écholocalisation. Elle arrive ainsi à se représenter son environnement sans le voir, ce qui lui permet de localiser et de capturer ses proies en vol.</p>\r\n\r\n<p>Elle s’alimente surtout dans les endroits ouverts qui favorisent une production élevée d’insectes, tels que :</p>\r\n<ul>\r\n  <li>les zones de coupes forestières;</li>\r\n  <li>les bordures de forêts;</li>\r\n  <li>les jeunes plantations d’arbres;</li>\r\n  <li>à proximité ou en bordure des plans d’eau;</li>\r\n  <li>près des lampadaires de rues ou de bâtiments.</li>\r\n</ul>\r\n', '<p>L’accouplement a lieu pendant les périodes de regroupement à la fin de l’été. L’implantation et la fertilisation de l’ovule sont retardées jusqu’au printemps, ce qu’on appelle « fécondation différée ».\r\n</p><p>\r\nLes naissances ont souvent lieu vers la mi-juin. Cette espèce donne naissance à une seule portée par année pouvant compter d’un à cinq petits. Une des particularités de la chauve-souris rousse est qu’elle possède quatre tétines, contrairement à la plupart des autres espèces de chauves-souris qui, elles, en ont deux. Les jeunes commencent à voler lorsqu’ils sont âgés de cinq à six semaines.</p>', NULL, '<p>Compte tenu du faible effectif des populations, plusieurs menaces directes ou indirectes sont particulièrement préoccupantes pour la chauve-souris rousse. Les principales menaces qui pèsent sur elles sont :</p>\r\n<ul>\r\n  <li>les parcs éoliens qui causent la mort par collision directe avec les structures fixes, les pales en mouvement ou par barotraumatisme;</li>\r\n  <li>le développement résidentiel et commercial;</li>\r\n  <li>l’agriculture et la foresterie;</li>\r\n  <li>les feux de forêt;</li>\r\n  <li>les corridors de transport (lignes électriques, routes, voies ferrées, oléoducs, etc.);</li>\r\n  <li>les contaminants agricoles et industriels;</li>\r\n  <li>la pollution lumineuse;</li>\r\n  <li>les changements climatiques.</li>\r\n</ul>\r\n\r\n<p>Il est à noter que la chauve-souris rousse, étant une espèce migratrice, n’est pas aussi vulnérable aux effets dévastateurs du syndrome du museau blanc que les espèces qui hibernent sous nos latitudes, telles que la petite chauve-souris brune, la chauve-souris nordique, la pipistrelle de l’Est et la chauve-souris pygmée de l’Est.</p>\r\n', 'Reproducteur', 'S1S2', 'Vulnérable', 'Québec', 2),
(770, 'Béluga, pop. de l\'estuaire du Saint-Laurent', 'marsouin blanc; bélouga', 'Beluga Whale - St. Lawrence Estuary population', NULL, 'Delphinapterus leucas pop. 3', NULL, '<p>Le béluga appartient au groupe des baleines à dents. Au Québec, la population de l’estuaire du Saint‑Laurent est menacée.</p>', '<p>Les bélugas sont présents dans la région de l’Arctique. Ils occupent les eaux de l’Alaska, du Canada, du Groenland, de la Norvège et de la Russie. Selon le Comité sur la situation des espèces en péril au Canada (COSEPAC), quatre populations de béluga vivent au Québec, soit celles de l’est de la baie d’Hudson, de la baie d’Ungava, de la baie James et de l’estuaire du Saint‑Laurent.</p>\r\n\r\n<p>Cette dernière est isolée de celles de l’Arctique. Elle occupe la zone la plus au sud de l’aire de répartition circumpolaire de l’espèce. La répartition actuelle de la population de béluga de l’estuaire du Saint‑Laurent est beaucoup plus restreinte qu’autrefois et aurait peu changé au cours des 20 dernières années.</p>\r\n\r\n<p>Durant l’été, ces bélugas se déplacent dans une zone qui s’étend sur environ 200 km dans l’estuaire du Saint-Laurent : depuis les battures aux Loups Marins en face de Saint‑Jean‑Port‑Joli jusqu’à l’île du Bic, dans le fleuve Saint‑Laurent, à l’ouest de Rimouski, et à Forestville, sur la Côte‑Nord. Cette zone comprend le Saguenay, de son embouchure jusqu’à Saint‑Fulgence.</p>\r\n\r\n<p>En d’autres temps de l’année, la répartition des bélugas est mal connue. Il semble que leur aire de répartition l’hiver puisse varier d’une année à l’autre selon les conditions de glace. Toutefois, certains survols aériens ont permis de noter que la population semble s’étendre en aval dans le golfe jusqu’à Sept‑Îles (Côte‑Nord), où plusieurs individus ont été observés. De petits groupes ont aussi été aperçus dans l’estuaire jusqu’à Rivière‑du‑Loup.</p>', '<p>La population de l’estuaire du Saint‑Laurent comptait entre 7 800 et 10 100 individus au début du 20e siècle. Plus récemment, cette population, probablement stable ou en légère baisse, était estimée à 1 850 individus en 2022.</p>\r\n\r\n<p>La chasse abusive a principalement contribué au déclin initial de cette population de béluga. Protégée contre la chasse en 1979, les relevés aériens effectués entre 1973 et 1990 laissaient croire que le déclin avait cessé, mais ils ne fournissent pas de preuves évidentes d’une augmentation importante des effectifs.</p>\r\n\r\n<p>L’incapacité apparente de la population à se rétablir après l’arrêt de la chasse a été attribuée à une charge élevée en divers contaminants persistants et toxiques dans son environnement.</p>\r\n\r\n<p>Les évaluations précédentes de l’abondance des bélugas et de leur tendance démographique de la population n’incluaient pas les estimations faites à partir des relevés visuels. Des facteurs de correction ont été actualisés pour les animaux manqués parce qu’ils étaient en plongée (biais de disponibilité) ou présents à la surface, mais non détectés par les observateurs (biais de perception). Ces facteurs permettent désormais d’utiliser à la fois les relevés visuels et photographiques.</p>\r\n\r\n<p>Depuis 1990, l’abondance de la population de béluga de l’estuaire du Saint‑Laurent a été estimée à l’aide de relevés aériens systématiques. Ces derniers couvraient l’ensemble de son aire de répartition estivale. L’évaluation actuelle est fondée sur 11 relevés photographiques effectués durant huit étés entre 1990 et 2019 et sur 52 relevés visuels effectués au cours de 14 étés entre 2001 et 2022.</p>\r\n\r\n<p>Entre 2010 et 2022, une baisse du taux de survie des nouveau‑nés a été rapportée ainsi qu’une augmentation de la mortalité des femelles liée à la gestation. Ces mortalités demeurent inexpliquées. Toutefois, des causes liées à l’activité humaine comme le dérangement et le bruit pourraient être des facteurs qui ont contribué à ces mortalités.</p>', '<p>Les conditions hydrologiques du Saint‑Laurent et du Saguenay procurent au béluga un habitat « arctique », c’est-à-dire une eau froide et riche en ressources alimentaires, qui est utilisée toute l’année.</p>', '<p>Le béluga est un prédateur marin. Son alimentation comprend surtout du capelan et du hareng atlantique. Il se nourrit également de toute une variété de poissons (éperlan arc‑en‑ciel, anguille d’Amérique, lançon d’Amérique, flétan atlantique, flétan du Groenland, morue franche, etc.), de crustacés, de mollusques (céphalopodes) et de certaines espèces d’invertébrés vivant au fond de l’eau comme des vers marins (polychètes).</p>', '<p>Les femelles atteindraient leur maturité sexuelle entre 6 et 14 ans, et les mâles entre 16 et 22 ans.</p>\r\n\r\n<p>L’accouplement a lieu principalement au cours des mois d’avril et de juin. La femelle donne naissance à un seul veau, après une gestation estimée à environ 14 à 15 mois.</p>\r\n\r\n<p>La période de mise bas s’étend de la fin juin au début d’août. Les jeunes seront allaités pendant environ 20 à 32 mois. Ainsi, en moyenne, une femelle donnerait naissance à un veau tous les trois ans.</p>\r\n\r\n<p>Le béluga peut vivre jusqu’à 30 à 60 ans, voire au‑delà de 80 ans.</p>', '<p>Parmi les baleines à dents, le béluga est une des espèces qui vocalisent le plus. Il émet des chants variés; ces derniers sont constitués de plusieurs types de sons comme des sifflements, des cliquetis, des cris perçants et des claquements de dents. Ce comportement particulier lui a valu le surnom de « canari des mers ».</p>', '<p>\r\n        Les principales menaces qui pèsent sur le béluga de l’estuaire du\r\n        Saint‑Laurent sont&#8239;:\r\n      </p>\r\n      <ul>\r\n        <li>la contamination des eaux;</li>\r\n        <li>le dérangement par les activités humaines;</li>\r\n        <li>la diminution de l’abondance des proies;</li>\r\n        <li>la dégradation de l’habitat, en particulier par le bruit;</li>\r\n        <li>les collisions avec des embarcations nautiques;</li>\r\n        <li>les engins de pêche qui causent des empêtrements;</li>\r\n        <li>les algues toxiques;</li>\r\n        <li>la pollution et les déversements accidentels d’hydrocarbures;</li>\r\n        <li>les maladies.</li>\r\n      </ul>', 'Toute l\'année', 'S1', 'Menacée', 'Pêches et Océans Canada', 2),
(778, 'Rorqual commun', 'rorqual commun, pop. de l\'Atlantique', 'Fin Whale', NULL, 'Balaenoptera physalus', NULL, '<p>Le rorqual commun est une baleine à fanons. Elle est la deuxième en importance au monde pour sa taille, après le rorqual bleu. Cette espèce est désignée vulnérable au Québec.</p>', '<p>Le rorqual commun est réparti partout dans le monde, dans les mers tempérées et polaires, tant dans l’océan Arctique qu’Antarctique. Au Canada, cette espèce est présente dans les eaux de l’Atlantique où elle s’alimente en été.\r\n</p><p>\r\nAu Québec, un petit groupe estive dans le golfe du Saint-Laurent, où près de 300 de ces individus ont été photo-identifiés par les scientifiques. Une cinquantaine d’individus passent l’été dans l’estuaire du Saint-Laurent, non loin de Tadoussac; quelques dizaines de ces individus ont été photo-identifiés.\r\n</p><p>\r\nCe rorqual émigre vers des eaux plus chaudes pour hiverner, principalement le long des côtes américaines et parfois même jusque dans le golfe du Mexique.</p>', '<p>En raison de sa grande taille, le rorqual commun a été une cible de choix pour l’industrie de la baleine au 19e siècle. La plupart des effectifs des populations de l’hémisphère Nord ont été réduits à la suite de récoltes. L’exploitation dans les eaux canadiennes et américaines a cessé en 1972. Depuis, les populations auraient augmenté et seraient en voie de se rétablir dans les eaux canadiennes. Cette baleine a presque toujours été rare dans les eaux canadiennes. La plus récente estimation de la population du golfe du Saint-Laurent, soit 380 individus, date de 1995 et 1996. L’inventaire n’incluait cependant pas l’estuaire du Saint-Laurent.</p>', '<p>Le rorqual commun vit dans des mers tempérées et polaires.</p>', '<p>En été, le rorqual commun s’alimente surtout de zooplancton et de poissons pélagiques (capelans, harengs) dans les régions côtières.</p>', '<p>Les femelles atteignent la maturité sexuelle entre 6 et 10 ans, et les mâles entre 8 et 12 ans. L’accouplement a lieu au cours des mois de décembre et janvier.</p>', NULL, '<p>Les principales menaces qui pèsent sur le rorqual commun sont :</p>\r\n<ul>\r\n  <li>la disponibilité de la ressource alimentaire;</li>\r\n  <li>la prédation des jeunes;</li>\r\n  <li>la maladie;</li>\r\n  <li>la pollution chimique;</li>\r\n  <li>l’exploration pétrolière;</li>\r\n  <li>la pêche commerciale, qui cause une concurrence pour la même ressource alimentaire.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Pêches et Océans Canada', 2),
(792, 'Ours blanc', 'ours polaire', 'Polar Bear', '', 'Ursus maritimus', NULL, '<p>L’ours blanc est l’une des deux seules espèces d’ours du Québec. C’est une espèce vulnérable.</p>\r\n\r\n<p>L’ours blanc est un <a href=\"https://www.quebec.ca/tourisme-loisirs-sport/activites-sportives-et-de-plein-air/chasse-sportive/regles-generales/animaux-declaration-obligatoire\">animal à déclaration obligatoire<a>. En tout temps, si vous trouvez un ours blanc blessé ou mort, contactez <a href=\"https://www.quebec.ca/agriculture-environnement-et-ressources-naturelles/faune/protection-faune/sos-braconnage-urgence-faune-sauvage\">SOS Braconnage — Urgence faune sauvage</a> au 1 800 463‑2191.</p>', '<p>La population mondiale d’ours blanc est distribuée autour du pôle Nord, dans le nord de l’Amérique du Nord et dans l’extrême nord de l’Europe et de l’Asie. Ces ours sont divisés en 19 sous‑populations. Les échanges entre les sous-populations semblent limités. Au Canada, il est présent d’ouest en est, du Yukon au Labrador, et du nord au sud, de l’île d’Ellesmere à la baie James.\r\n<p></p>\r\nTrois des sous-populations du Canada vivent au Québec. Il s’agit de celle du sud de la baie d’Hudson, celle du bassin Foxe et celle du détroit de Davis. Elles se trouvent dans le Nord‑du‑Québec et les eaux adjacentes. Ces ours blancs font partie des sous-populations vivant le plus au sud de toute la planète.</p>', '<p>La population mondiale d’ours blanc est estimée à 26 000 individus. Au Canada, l’espèce est estimée à près de 15 500 individus. Les trois sous‑populations d’ours blancs du Québec ont chacune leurs estimations et leurs tendances. Celle du sud de la baie d’Hudson semble en diminution et comptait 780 ours en 2016. Celle du bassin Foxe semble en augmentation et comptait 2 585 ours en 2010. Celle du détroit de Davis semble en augmentation et comptait 2 158 ours en 2007.</p>', '<p>L’habitat de l’ours blanc varie selon les saisons, le sexe et le statut reproducteur de l’animal. Trois habitats principaux peuvent être retenus pour l’ours blanc : les aires d’alimentation au printemps, les sites de mise bas et les retraites durant l’été.\r\n<p></p>\r\nL’ours blanc se sert du milieu marin pour chasser des animaux qui y vivent, surtout lorsqu’il y a un certain degré de couverture de glace. Les ours se sont adaptés à tous les types de glaces de mer et sont d’excellents nageurs capables de franchir de longues distances en eaux libres. Il fréquente la majorité des zones côtières arctiques et subarctiques du Canada et se déplace à l’occasion sur de grandes distances vers l’intérieur des terres.\r\n<p></p>\r\nDans les zones où la glace de mer n’est que saisonnière, comme au Québec, il doit généralement avoir accès à la terre ferme pendant les périodes sans glace. De plus, il y aménage sa tanière durant l’hiver.</p>', '<p>L’ours blanc est surtout carnivore et se nourrit principalement de phoques annelés, de phoques du Groenland et de phoques barbus. Il mange aussi des oiseaux, leurs œufs et des carcasses de mammifères marins. Dans une moindre mesure, il peut également se nourrir de morse, d’omble chevalier, de castor, de caribou et de phoque commun.\r\n<p></p>\r\nAprès de longues périodes en mer, l’ours blanc a tendance à s’alimenter de mousses et de lichens une fois de retour sur la terre ferme. Cette habitude alimentaire pourrait l’aider à mieux retenir et à absorber les huiles contenues dans les phoques.\r\n<p></p>\r\nL’ours blanc est bien adapté aux périodes d’abondance ou de pénurie alimentaire. Lorsque la nourriture est abondante au printemps, l’ours blanc peut augmenter substantiellement sa masse corporelle. À l’opposé, lorsque la nourriture est rare ou introuvable, l’espèce peut survivre grâce aux réserves de graisse emmagasinées.</p>', '<p>L’espèce se reproduit de mars à juin. L’âge de la femelle au moment de la première reproduction varie de 4 à 7 ans. Les mâles atteignent probablement eux aussi la maturité sexuelle vers l’âge de 6 ans, mais les jeunes mâles affichent habituellement un faible succès de reproduction, en raison de la compétition venant des mâles plus gros et plus âgés. Il semble que la plupart des mâles ne commencent à se reproduire que vers l’âge de 8 à 10 ans.\r\n<p></p>\r\nLa tanière de l’ours blanc est formée de neige compactée en amoncellements ou est creusée dans le sol ou la neige. La femelle s’y rend à la fin de l’automne et donnera naissance à un ou deux oursons de novembre à janvier. Les femelles retournent souvent dans la même région pour mettre bas au cours de leur vie.\r\n<p></p>\r\nÀ la naissance, les oursons pèsent environ 0,6 kg. Ils sont allaités à l’intérieur de la tanière jusqu’à la fin de février et le milieu d’avril alors qu’ils auront atteint 10 à 12 kg. L’intervalle moyen entre les portées est d’environ 3,6 ans.</p>', NULL, '<p>Les principales menaces pesant sur l\'ours blanc incluent les changements climatiques, la destruction de l\'habitat, le transport maritime, la pollution, les maladies et la chasse non durable.</p>\r\n<p>Le réchauffement climatique représente une menace majeure à long terme en réduisant la glace de mer, ce qui entraîne une perte directe d\'habitat et une baisse indirecte des proies.</p>\r\n<p>La fonte précoce et le gel tardif augmentent la dépendance des ours envers les zones côtières, tandis que les variations climatiques menacent leurs tanières, bien que certaines zones de glace pluriannuelle puissent ponctuellement offrir un meilleur habitat.</p>\r\n', 'Non reproducteur', 'S3', 'Vulnérable', 'Québec', 2),
(801, 'Carcajou', 'carcajou, pop. de l\'Est; diable des bois;glouton', 'Wolverine', 'Glutton; Skunk Bear', 'Gulo gulo', NULL, '<p>Le carcajou est un puissant mustélidé dont il est actuellement impossible de déterminer s’il existe une population établie au Québec, malgré quelques mentions d’observations récentes. C’est une espèce menacée.\r\n</p><p>\r\nLe carcajou est un <a href=\"https://www.quebec.ca/tourisme-loisirs-sport/activites-sportives-et-de-plein-air/chasse-sportive/regles-generales/animaux-declaration-obligatoire\">animal à déclaration obligatoire</a>. En tout temps, si vous trouvez un carcajou blessé ou mort, contactez <a href=\"https://www.quebec.ca/agriculture-environnement-et-ressources-naturelles/faune/protection-faune/sos-braconnage-urgence-faune-sauvage\">SOS Braconnage — Urgence faune sauvage</a> au 1 800 463-2191.</p>', '<p>Le carcajou vit en Scandinavie et dans les régions nordiques de l’Eurasie et de l’Amérique du Nord. Malgré certaines mentions d’observations au Québec, il est actuellement impossible d’assurer qu’il existe une population résidente.</p>\r\n\r\n<p>Depuis la fin des années 1980, la grande majorité des observations rapportées n’ont pu être confirmées en raison de l’absence de preuves (p. ex., photo de l’animal, pistes, fèces, etc.). Il est donc difficile d’établir avec certitude sa répartition actuelle qui semble davantage se limiter au nord du Québec. Certaines mentions d’observation laissent toutefois supposer que le carcajou pourrait aussi être présent plus au sud. Cependant, ce mustélidé est reconnu comme étant capable de parcourir de très grandes distances. Il n’est donc pas exclu que certains individus puissent provenir de l’Ontario ou du Nunavut, voyageant parfois sur les glaces.</p>', '<p>Le carcajou a été éliminé sur plus de la moitié de son aire de répartition historique en Amérique du Nord de 1840 à 1925. À l’exception des Rocheuses, sa répartition ne descend plus en dessous du 50e parallèle.</p>\r\n\r\n<p>Au Canada, le carcajou se trouvait historiquement du Yukon jusqu’à Terre‑Neuve‑et‑Labrador, englobant l’archipel Arctique, ainsi que dans le nord des provinces de l’Ouest, de l’Ontario et du Québec. Avant l’arrivée des Européens, le carcajou était présent sur l’ensemble du territoire québécois. Les indices les plus anciens de sa présence au Québec sont des ossements vieux de quelques milliers d’années découverts dans la grotte de Saint‑Elzéar en Gaspésie.</p>\r\n\r\n<p>La présence de deux individus a été confirmée à Salluit, dans le Nord‑du‑Québec, à l’hiver 2018. Il s’agissait des premières mentions avérées depuis 1978 au Québec. Cependant, cela ne constitue pas une preuve de population résidente.</p>', '<p>Le carcajou fréquente les milieux vierges et sauvages et se tient à l’écart des régions peuplées par les humains. Il tolère un climat froid et occupe une grande diversité d’habitats, sauf les milieux très secs.</p>', '<p>Sa mâchoire, extrêmement solide et puissante, lui permet de consommer la chair et les os des carcasses gelées en hiver. Le carcajou est opportuniste et il consomme une grande variété d’aliments, selon leur disponibilité. En hiver, il devient principalement nécrophage et dévore les proies tuées par d’autres carnivores, les animaux morts naturellement ou pris dans les pièges des trappeurs.</p>', '<p>La période d’accouplement se déroule de mai à juillet et peut s’étendre jusqu’au début de l’automne. L’implantation de l’embryon est différée et son développement s’effectue donc quelques mois après l’accouplement.</p>\r\n\r\n<p>Les jeunes naissent de janvier à avril dans une caverne, une fissure de rocher, un trou sous des troncs d’arbres, un tunnel de neige ou à la surface du sol sous la neige. Le nombre de petits par portée se limite généralement à deux ou trois. La reproduction peut s’espacer d’une à plusieurs années.</p>', '<p>Le carcajou possède une grande endurance qui lui permet de circuler en terrain accidenté et dans la neige épaisse. Il se déplace aussi en altitude, suivant les saisons, la distribution et l’abondance des proies.</p>\r\n\r\n<p>Le carcajou est capable de traîner des carcasses sur de longues distances. Il a l’habitude de cacher sa nourriture sous la neige ou à divers endroits après l’avoir marquée d’un liquide malodorant.</p>', '<p>Les facteurs qui semblent avoir contribué au déclin du carcajou au Québec sont :</p>\r\n<ul>\r\n  <li>le piégeage et la chasse effectués au 19e siècle;</li>\r\n  <li>le déclin des populations de caribous au cours de la première moitié du 20e siècle;</li>\r\n  <li>le développement et l’étalement des activités humaines qui empiètent sur son habitat;</li>\r\n  <li>la diminution du nombre de de loups gris qui contribue normalement à lui procurer des carcasses d’animaux;</li>\r\n  <li>les opérations de contrôle des prédateurs.</li>\r\n</ul>', 'Inconnu/non déterminé', 'SH', 'Menacée', 'Québec', 2),
(822, 'Caribou des bois, écotype montagnard, pop. de la Gaspésie', 'caribou montagnard - pop. Gaspésie; caribou, pop. De la Gaspésie-Atlantique', 'Woodland Caribou - Mountain ecotype - Gaspésie population', '', 'Rangifer tarandus caribou pop. 2', 'La population de la Gaspésie appartiend à l\'écotype montagnard.', '<p>Le caribou des bois, écotype montagnard, population de la Gaspésie (caribou de la Gaspésie) est une espèce menacée. Il s’agit de la dernière population de caribous des bois au sud du fleuve Saint-Laurent.</p>\r\n\r\n<p>Le caribou des bois est <a href=\"https://www.quebec.ca/tourisme-loisirs-sport/activites-sportives-et-de-plein-air/chasse-sportive/regles-generales/animaux-declaration-obligatoire\">un animal à déclaration obligatoire</a>. En tout temps, si vous trouvez un caribou blessé ou mort, contactez <a href=\"https://www.quebec.ca/agriculture-environnement-et-ressources-naturelles/faune/protection-faune/sos-braconnage-urgence-faune-sauvage\">SOS Braconnage – Urgence faune sauvage</a> au 1 800 463‑2191.</p> ', '<p>Le caribou de la Gaspésie fréquente les hauts sommets des massifs McGerrigle, dont les monts Jacques‑Cartier, et des massifs des Chic‑Chocs (comprenant les monts Albert et Logan). En hiver, le caribou de la Gaspésie utilise également la forêt de conifères matures avoisinant le parc national de la Gaspésie.</p>\r\n\r\n<p>Cette population constitue le dernier vestige du caribou au sud du fleuve Saint-Laurent. À l’époque, le caribou occupait le Nouveau‑Brunswick, la Nouvelle‑Écosse, l’Île‑du‑Prince‑Édouard et la Nouvelle‑Angleterre.</p>\r\n\r\n\r\n', '<p>Au début des années 1950, la population de caribous de la Gaspésie comptait de 700 à 1 500 individus. Au cours des années 1980, elle était d’environ 250 individus. En octobre 2021, la population était estimée à seulement 38 caribous.</p>\r\n\r\n<p>Outre la chasse qui s’est poursuivie jusqu\'en 1948, ce sont les perturbations de son habitat par les activités humaines (p. ex. exploitation forestière et minière) qui seraient la cause de ce déclin. Aujourd’hui, la précarité du caribou de la Gaspésie serait principalement attribuable au faible effectif de la population, au faible taux de survie des faons et des femelles causé par la prédation du coyote et de l’ours noir ainsi qu’à un habitat de moindre qualité.</p>\r\n', '<p>Le caribou de la Gaspésie occupe principalement les milieux subalpin et alpin dont l’altitude est supérieure à 700 m. Il utilise, dans les altitudes inférieures, les sapinières matures (environ 70 ans). Sur les sommets, il fréquente les secteurs de toundra alpine et subalpine. Le groupe de caribous du secteur du mont Logan utilise davantage les peuplements de sapinières matures.</p>\r\n\r\n<p>L’habitat du caribou de la Gaspésie est <a href=\"https://www.quebec.ca/agriculture-environnement-et-ressources-naturelles/faune/gestion-faune-habitats-fauniques/habitats-fauniques/proteges-legalement\">protégé légalement</a>.</p>', '<p>Le régime alimentaire du caribou de la Gaspésie varie selon les saisons. En été, le caribou se nourrit de mousses, de lichens et d’herbacées. En hiver, les lichens qui poussent sur le sol (terricoles) et sur les arbres (arboricoles) dominent son alimentation. Les lichens arboricoles, qu’on trouve dans les forêts matures de haute altitude, sont essentiels à la survie du caribou lorsque les lichens terricoles sont couverts de neige. Les lichens sont une source d’énergie hautement digestible et riche en sucres, mais faible en protéines et en potassium.</p>', '<p>La période de rut et d’accouplement du caribou de la Gaspésie a lieu à l’automne, de septembre à novembre.</p>\r\n\r\n<p>La maturité sexuelle est atteinte entre 18 et 30 mois. Toutefois, seuls les mâles présentant un fort gabarit et des bois développés accèdent habituellement aux femelles.</p>\r\n\r\n<p>Les mâles sont polygynes, c’est-à-dire qu’un même mâle peut s’accoupler avec plusieurs femelles au cours d’une même saison de reproduction. Afin de signaler son statut de reproducteur, le mâle brame, secoue les arbustes avec ses bois et affronte ses rivaux dans des rituels (entrecroisement des bois) généralement sans blessure. Pendant le rut, le mâle se nourrit peu. Il garde son énergie pour les affrontements entre mâles et l’accouplement avec les femelles.</p>\r\n\r\n<p>La gestation dure de 225 à 235 jours. Entre la fin de mai et la mi-juin, les femelles se dispersent dans divers types d’habitat pour donner naissance à leurs faons. Les femelles de la population de la Gaspésie, suivies par télémétrie de 2013 à 2016, ont mis bas généralement entre le 20 mai et le 1er juin.</p>\r\n\r\n<p>La plupart des femelles s’accouplent pour la première fois à l’âge de 2,5 ans et donnent naissance à un seul faon par année. La présence de jumeaux est très rare, voire anecdotique chez le caribou. Les femelles du caribou de la Gaspésie préfèrent les secteurs en altitude, généralement rocailleux, accidentés et dépourvus d\'arbres.</p>\r\n\r\n<p>Quelques heures après sa naissance, le faon se dresse sur ses pattes et suit sa mère dans ses déplacements. Dès l’âge de trois jours, il parcourt des distances minimales semblables à celles des adultes, et il commence à brouter après deux semaines de vie. À un an, il accompagne parfois encore la femelle dans les aires de mise bas.</p>\r\n\r\n<p>Le caribou a une longévité typique pour un cervidé, soit entre 8 et 15 ans.</p>\r\n\r\n<p>Les caribous femelles sont moins productifs que les cerfs de Virginie ou les orignaux femelles. Les femelles ne produisent qu’un seul faon par année, alors qu’un cerf de Virginie femelle ou un orignal femelle ont de un à trois faons par année. Les caribous femelles se reproduisent également à un âge plus tardif que les femelles des autres espèces de cervidés. Ces particularités réduisent le potentiel de croissance annuelle et la capacité de renouvellement d’une population de caribous comparativement aux autres espèces de cervidés vivant au Québec.</p>', NULL, '<p>Les principales menaces qui pèsent sur le caribou montagnard de la Gaspésie sont :</p>\r\n<ul>\r\n  <li>la destruction, la dégradation et la fragmentation de son habitat, notamment par les coupes forestières et le développement de parcs éoliens;</li>\r\n  <li>le dérangement par les activités récréatives telles que l’utilisation de véhicules motorisés hors route, la pratique de sports de glisse, la randonnée, le camping et la villégiature;</li>\r\n  <li>l’augmentation du nombre de prédateurs. La présence de loups, d’ours noirs ou de coyotes découle principalement des perturbations dans l’habitat;</li>\r\n  <li>la construction de routes et de chemins multiusages qui facilitent à ces prédateurs l’accès au caribou;</li>\r\n  <li>les activités industrielles de prospection ou d’exploitation minière dans l’aire de répartition en périphérie du parc national de la Gaspésie, qui peuvent stresser les caribous ou les amener à abandonner leur habitat.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Québec', 2),
(830, 'Tortue luth', '', 'Leatherback Sea Turtle', 'Atlantic Leatherback Turtle; Leatherback', 'Dermochelys coriacea', NULL, '<p>La tortue luth est la seule espèce de tortue marine du Québec. Il s’agit de la plus grosse tortue au monde. Cette tortue de mer fréquente les océans et effectue les plus longues distances migratoires connues pour un reptile.</p>', '<p>La tortue luth fréquente les eaux chaudes des océans Pacifique, Atlantique et Indien. En dehors de la saison de reproduction, elle effectue de grandes migrations saisonnières durant lesquelles elle peut être apeçue dans les eaux plus froides.</p>\r\n\r\n<p>La population canadienne de l’Atlantique Nord peut être observée de juin à octobre, au large de la côte Atlantique, à l’est de l’île de Terre‑Neuve et parfois jusqu’au Labrador. Au Québec, l’espèce a été vue aux environs des îles de la Madeleine, de la Basse‑Côte‑Nord et de l’île d’Anticosti.</p>', '<p>Peu de renseignements sont disponibles pour définir la tendance des populations de tortues luths au Québec. Toutefois, il semblerait que les principales populations nicheuses de l’ouest de l’Atlantique soient relativement stables ou en légère augmentation.</p>', '<p>La tortue luth fréquente les côtes du golfe du Saint-Laurent où elle trouve des méduses.</p>', '<p>La tortue luth se nourrit de méduses, qui constituent l’essentiel de son régime alimentaire. Elle mange également d’autres invertébrés aquatiques, de petits poissons et des crustacés.</p>', '<p>La tortue luth passe la majeure partie de sa vie en mer, mais elle pond ses œufs sur les plages de l’Amérique du Sud et de l’Amérique centrale. La nidification a lieu à des intervalles de 2 à 4 ans. Une femelle pond environ 80 œufs, mais de nombreux œufs n’éclosent pas. La durée de l’incubation est d’environ 60 jours.</p>', NULL, '<p>Les principales menaces qui pèsent sur la tortue luth sont :</p>\r\n<ul>\r\n  <li>la pêche, plus précisément le matériel qui peut entraîner l’empêtrement et causer la noyade;</li>\r\n  <li>les bateaux qui peuvent provoquer des collisions;</li>\r\n  <li>la pollution marine, qui peut amener l’ingestion de débris de plastique qu’elle confond avec des méduses;</li>\r\n  <li>le bruit, dont les sons de basses fréquences susceptibles de modifier le comportement des tortues marines;</li>\r\n  <li>l’éclairage artificiel des sites de ponte qui désoriente les nouveau-nés;</li>\r\n  <li>le braconnage.</li>\r\n</ul>\r\n', 'Non reproducteur', 'SNA', 'Menacée', 'Pêches et Océans Canada', 5);
INSERT INTO `especes` (`id`, `nom_francais`, `autres_noms_francais`, `nom_anglais`, `autres_noms_anglais`, `nom_scientifique`, `commentaires`, `description`, `repartition`, `etat_situation`, `habitat`, `alimentation`, `reproduction`, `comportement`, `menaces`, `statuts_des_populations`, `rang_S`, `statut_LEMV`, `competence_principale`, `groupe_id`) VALUES
(833, 'Tortue des bois', NULL, 'Wood Turtle', 'Wood Tortoise', 'Glyptemys insculpta', NULL, '<p>Il s’agit de la plus terrestre des tortues d’eau douce du Québec. Bien qu’elle vive dans les rivières sinueuses, elle passe aussi beaucoup de temps sur la terre ferme. Ses déplacements entre ces milieux la poussent à traverser des routes, ce qui la rend vulnérable aux collisions avec les véhicules.</p>', '<p>La tortue des bois vit exclusivement dans le nord‑est de l’Amérique du Nord. Au Canada, cette espèce se trouve au sud de l’Ontario jusqu’à la Nouvelle‑Écosse. Au Québec, elle est présente dans plusieurs régions situées au sud du 49e parallèle, de part et d’autre du fleuve Saint‑Laurent.</p>', '<p>En 2018, le nombre de populations de tortues des bois était estimé à 119 pour l’ensemble du Québec. Cependant, plusieurs d’entre elles sont très peu documentées. En l’absence de mesures de protection renforcées, le déclin des populations de cette espèce risque de continuer pour au moins le quart des populations connues. Toutefois, il est difficile d’en estimer les chances de survie à moyen terme.</p>', '<p>Bien que la tortue des bois soit la plus terrestre des tortues d’eau douce du Québec, elle demeure néanmoins une tortue semi-aquatique. Elle s’éloigne rarement à plus de 200 m d’un cours d’eau et utilise le milieu aquatique tout au long de l’année. Elle fréquente généralement les cours d’eau de taille moyenne dont le fond est constitué de sable ou de gravier. Elle préfère les cours d’eau limpides et méandreux à débit lent ou modéré. La tortue des bois pond généralement sur les berges de sable ou de gravier sableux, ou encore sur des sites artificiels, comme les bords de routes et de chemins de fer, ainsi que dans les gravières. En milieu terrestre, on la retrouve souvent dans les aulnaies.\r\n</p><p>\r\nLa tortue des bois hiberne sous la glace. Elle passe l’hiver directement dans le lit du cours d’eau, dans des terriers de rats musqués, dans des souches immergées ou encore sous une berge en saillie. L’hibernation a généralement lieu à partir d’octobre ou de novembre jusqu’en avril.</p><p>Certains habitats de la tortue des bois bénéficient d’une protection légale au Québec. Ceux-ci sont désignés par un plan qui indique ses limites. Toute activité qui pourrait modifier un élément nécessaire aux besoins de l’espèce est interdite dans les habitats ayant été désignés.</p>', '<p>La tortue des bois est omnivore. Elle se nourrit de plantes, de fruits, de charognes, d’insectes et d’autres invertébrés, comme les vers de terre et les limaces.</p>', '<p>L’accouplement a généralement lieu au printemps ou à l’automne. Au Québec, la ponte se déroule essentiellement entre la fin de mai et la fin de juin. Bien que la ponte puisse avoir lieu en milieu naturel, elle survient souvent dans un milieu modifié par l’humain, dans des substrats habituellement graveleux ou sablonneux où la végétation est absente ou clairsemée. Le nombre d’œufs pondus varie de 3 à 20. Les nouveau-nés, dont le sexe est déterminé par des facteurs génétiques et non par la température d’incubation des œufs comme d’autres espèces de tortues, émergent du nid de la fin d’août au début d’octobre.</p>', NULL, '<p>Les principales menaces qui pèsent sur la tortue des bois au Québec sont :</p>\r\n<ul>\r\n  <li>les routes ou les chemins forestiers, qui peuvent entraîner des collisions avec un véhicule auprès des tortues adultes;</li>\r\n  <li>les activités agricoles (notamment la fauche des champs), les opérations forestières ou l’exploitation des gravières et sablières, qui peuvent causer la mort des femelles venues pondre leurs œufs;</li>\r\n  <li>la perte, la modification ou la fragmentation des habitats liés au développement industriel, residential et agricole;</li>\r\n  <li>les prédateurs, dont le raton laveur, la mouffette et le renard, principalement pour les populations près des zones habitées;</li>\r\n  <li>la collecte, la garde en captivité et le commerce illégal.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Québec', 5),
(834, 'Tortue mouchetée', 'tortue mouchetée, pop. des Grands-Lacs et du Saint-Laurent; tortue de blanding', 'Blanding\'s Turtle', '', 'Emydoidea blandingii', '', '<p>Cette tortue d’eau douce fréquente les habitats aquatiques et peut parcourir plusieurs centaines de mètres en milieu terrestre pour passer d’un milieu humide à un autre. Reconnue pour sa longévité, elle peut vivre jusqu’à 90 ans. Sa présence est fortement associée aux barrages de castors.</p>', '<p>La tortue mouchetée vit uniquement en Amérique du Nord, dans une région centrée sur les Grands Lacs. Au Canada, elle est présente seulement dans le sud de l’Ontario et à quelques endroits au Québec. Selon l’état actuel des connaissances, sa répartition au Québec se limite à une seule population, soit celle de la vallée de l’Outaouais et du parc de la Gatineau. Quelques observations isolées ont été rapportées, notamment en Abitibi‑Témiscamingue, en Montérégie, dans Lanaudière et dans la Capitale‑Nationale.</p>', '<p>En 2020, les populations de tortues mouchetées étaient estimées à 21 pour l’ensemble du Québec. Cependant, certaines d’entre elles sont très peu documentées. Aussi, on ignore si les observations isolées recensées entre 2014 et 2018 dans les régions de la Montérégie, de l’Outaouais, de Lanaudière et de l’Abitibi‑Témiscamingue constituent de véritables populations. Il est possible que d’autres populations de tortues mouchetées soient présentes au Québec dans des secteurs où peu d’efforts d’échantillonnage ont été déployés.</p>\r\n\r\n<p>En absence de mesures de protection renforcées, le déclin de cette espèce risque de continuer pour environ le quart des populations connues. Toutefois, il est difficile d’en estimer les chances de survie à moyen terme.</p>', '<p>La tortue mouchetée est une espèce surtout aquatique. Elle fréquente les marécages, les étangs, les lacs peu profonds et les terrains inondés. Cette espèce se trouve souvent dans des marais où la végétation aquatique et la matière organique abondent. La présence de tortues mouchetées est souvent associée aux milieux humides formés par une succession de barrages de castors. Les habitats calmes recouverts de lentilles d’eau sont ses habitats de prédilection.\r\n</p><p>\r\nLes tortues mouchetées hibernent sous la glace, généralement dans des étangs ou des cours d’eau à débit lent. Elles s’enfouissent dans le substrat et y demeurent de novembre à avril. Possiblement à cause d’une bonne tolérance au froid et à un taux d’oxygène faible, elles peuvent utiliser une variété d’habitats pour l’hibernation.</p>', '<p>La tortue mouchetée est principalement carnivore. Son régime alimentaire est varié. Elle mange beaucoup d’arthropodes, comme des insectes, des araignées et des écrevisses, des vers et des sangsues, des mollusques, des poissons, des grenouilles et des charognes.</p>', '<p>L’accouplement a généralement lieu entre mars et juillet, mais peut avoir lieu jusqu’à tard à l’automne. Au Québec, la période de ponte se déroule entre la fin de mai et le début de juillet.\r\n</p><p>\r\nBien que la ponte puisse avoir lieu en milieu naturel, elle survient souvent dans un milieu modifié par l’humain, dans des substrats habituellement graveleux ou sablonneux où la végétation est absente ou clairsemée.</p><p>\r\n\r\nLe nombre d’œufs pondus peut varier de 3 à 22. Les nouveau-nés, dont le sexe est influencé par la température d’incubation des œufs, émergent du nid de la fin d’août au début d’octobre selon la chaleur du sol durant l’incubation.</p>', NULL, '<p>Les principales menaces qui pèsent sur la tortue mouchetée au Québec sont :</p>\r\n<ul>\r\n  <li>le démantèlement non autorisé des barrages de castor provoquant la perte d’habitat propice à l’espèce ainsi que la mort des individus durant l’hiver due à l’assèchement des étangs et des marais;</li>\r\n  <li>la fragmentation et la perte d’habitats, notamment par la construction de routes;</li>\r\n  <li>les routes, les chemins forestiers et les automobiles, qui peuvent causer la mort des femelles lors de leur déplacement vers leurs sites de ponte;</li>\r\n  <li>l’assèchement des étangs et des marais à des fins industrielles, agricoles ou résidentielles;</li>\r\n  <li>la capture pour la garde en captivité ou le commerce illégal.</li>\r\n</ul>\r\n\r\n<p>Aussi, la prédation exercée sur les œufs et les jeunes de moins de 9 ans est sévère par endroit. Elle peut être particulièrement grave chez cette espèce qui atteint la maturité sexuelle entre 13 et 16 ans et qui peut vivre jusqu’à 90 ans.</p>\r\n', 'Toute l\'année', 'S2S3', 'Menacée', 'Québec', 5),
(835, 'Tortue géographique', 'tortue géographique du Nord', 'Northern Map Turtle', 'Common Map Turtle; Map Turtle', 'Graptemys geographica', 'Le nom français \"tortue géographique\" et le nom anglais \"Map Turtle\" sont associés au genre Graptemys et ne sont pas assez précis pour désigner l\'espèce. Toutefois, le statut d\'espèce vulnérable a été attribué au nom français simplifié \"tortue géographique\" et non à son nom précis \"tortue géographique du Nord\".', '<p>Cette tortue d’eau douce fréquente le fleuve Saint-Laurent et ses grands tributaires. L’été, elle s’expose au soleil sur les roches et troncs d’arbres émergeants dans les baies peu profondes où l’eau est chaude et la végétation abondante. Cette espèce consomme de grandes quantités de moules.</p>', '<p>La tortue géographique vit uniquement en Amérique du Nord. Au Canada, elle est présente seulement dans le sud-est de l’Ontario et le sud du Québec. Elle vit dans les régions les plus densément peuplées de ces provinces.\r\n</p><p>\r\nAu Québec, elle est observée surtout le long de la rivière des Outaouais, dans le fleuve Saint‑Laurent et ses tributaires autour et en amont de l’archipel des îles de Montréal, puis au lac Champlain. Il existe également des mentions isolées sur la rivière Richelieu, ainsi que dans le fleuve, à la hauteur de Cap‑Santé et de Québec.</p>', '<p>En 2019, les tortues géographiques étaient réparties en 12 populations pour l’ensemble du Québec. Cependant, plusieurs d’entre elles sont très peu documentées. Il est estimé qu’un peu plus du tiers des populations seraient en bonne situation, alors que la moitié des populations seraient en situation précaire.\r\n</p><p>\r\nOr, un biais existe quant à la taille des populations. Les populations de tortues géographiques en situation précaire sont généralement de petites tailles et associées à quelques observations ponctuelles. Quant aux populations en bonne situation, elles comprennent des dizaines, voire des centaines d’observations, en plus de s’étendre sur des dizaines de kilomètres. Ainsi, les populations en bonne situation représentent plus de 70 % de la superficie occupée par l’espèce, par opposition à 20 % pour les populations en situation précaire. La documentation est insuffisante pour un peu moins de 10 % des populations.\r\n</p><p>\r\nLes populations situées dans la grande région de Gatineau, en Montérégie et en aval de Montréal présentent des effectifs faibles. Ainsi, l’espèce serait en situation précaire dans plusieurs localités au Québec. Elle pourrait disparaître à ces endroits au cours des 50 prochaines années en absence de mesures de protection renforcées.</p>', '<p>La tortue géographique est une espèce surtout aquatique. Elle préfère les vastes étendues d’eau comme les lacs et les rivières au fond mou, où elle trouve de nombreux sites d’exposition au soleil et une riche végétation aquatique. Les seules incursions sur la terre ferme sont entreprises par les femelles pour aller pondre au printemps. Cette tortue utilise souvent des sites d’exposition isolés du rivage, tels que des roches et des souches émergentes.\r\n</p><p>\r\nElle hiberne en groupe sous la glace, souvent à 5 m de profondeur où l’eau est bien oxygénée. Elle utilise principalement les zones profondes des rivières, là où le risque de gel ou d’assèchement est absent.</p>', '<p>La tortue géographique se nourrit dans l’eau. Son régime alimentaire est très varié. Elle consomme beaucoup de moules, de gastéropodes, de crustacés et d’insectes. Elle se nourrit aussi de poissons, de salamandres et, dans une moindre mesure, de plantes aquatiques.</p>', '<p>L’accouplement a lieu au printemps ou à l’automne. La femelle pond entre 9 et 17 œufs sur la terre ferme, entre juin et juillet. L’éclosion a lieu entre août et octobre. Bien que la ponte puisse avoir lieu en milieu naturel, elle survient souvent dans un milieu modifié par l’humain, dans des substrats habituellement graveleux ou sablonneux où la végétation est absente ou clairsemée.\r\n</p><p>\r\nLe sexe des nouveau‑nés dépend de la température du nid au cours de la quatrième à la septième semaine d’incubation. Dans les nids exposés au soleil, le développement embryonnaire est accéléré et la production de femelles est favorisée. Les sites plutôt ombragés produisent surtout des mâles et les œufs éclosent plus tard.</p>', NULL, '<p>Les principales menaces qui pèsent sur la tortue géographique au Québec sont :</p>\r\n<ul>\r\n  <li>la dégradation et la perte des habitats riverains;</li>\r\n  <li>les activités nautiques motorisées, qui peuvent la blesser et la tuer;</li>\r\n  <li>la pollution de l’eau;</li>\r\n  <li>la fluctuation des niveaux d’eau lors de la période de nidification;</li>\r\n  <li>les collisions avec les véhicules;</li>\r\n  <li>le dérangement par les activités humaines;</li>\r\n  <li>la prédation excessive des œufs. Ses prédateurs sont nombreux : loutre de rivière, raton laveur, pygargue à tête blanche, héron et différentes espèces de poissons;</li>\r\n  <li>la collecte, la garde en captivité et le commerce illégal.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2S3', 'Vulnérable', 'Québec', 5),
(838, 'Tortue musquée', 'tortue musquée de l\'Est', 'Eastern Musk Turtle', 'Common Musk Turtle', 'Sternotherus odoratus', 'Le nom français \"tortue musquée\" et le nom anglais \"Musk Turtle\" sont associés au genre Sternotherus et ne sont pas assez précis pour désigner l\'espèce. Toutefois, le statut d\'espèce menacée a été attribué au nom français simplifié \"tortue musquée\" et non à son nom précis \"tortue musquée de l\'Est\".', '<p>Cette tortue d’eau douce est la plus petite du Québec. Elle est présente que dans quelques baies d’eau peu profonde de la rivière des Outaouais et du fleuve Saint‑Laurent en amont de Montréal. Elle demeure presque toujours en milieu aquatique, même pour pondre.</p>', '<p>La tortue musquée vit exclusivement dans l’est de l’Amérique du Nord. Au Canada, elle est présente seulement dans le sud de l’Ontario et du Québec. Au Québec, cette espèce se trouve dans la rivière des Outaouais, entre Gatineau et Portage‑du‑Fort, ainsi qu’au lac Saint‑François sur le fleuve Saint‑Laurent en amont de Montréal.</p>', '<p>En dépit des efforts de recherche déployés depuis 2005, la tendance des populations du Québec est inconnue, faute de documentation. En 2020, le nombre de populations de tortues musquées était estimé à 6 pour l’ensemble du Québec, réparties en Montérégie et en Outaouais.\r\n</p><p>\r\nSeulement trois populations sont établies à partir de plus d’une observation précise, malgré des efforts d’inventaires importants sur le terrain. Il est toutefois estimé que, pour les populations connues, la moitié serait en situation précaire et l’autre moitié en bonne situation.</p>', '<p>La tortue musquée est une espèce essentiellement aquatique. Elle préfère l’eau calme et peu profonde de rivières, de marais, d’étangs et de lacs avec des fonds vaseux. Pour augmenter sa température corporelle, la tortue musquée se maintient à la surface de l’eau, souvent cachée sous les feuilles de nénuphar. Ainsi, elle profite de l’eau et des feuilles réchauffées par le soleil.\r\n</p><p>\r\nLes tortues musquées peuvent hiberner en groupe sous la glace dans un abri. Ce dernier peut être dans la vase, sous des roches, des souches ou des débris forestiers ou encore dans des terriers ou des huttes de rats musqués.</p>', '<p>La tortue musquée est omnivore. Elle se nourrit sur le fond de l’eau. Son régime alimentaire se compose de poissons morts, d’escargots, de mulettes, d’insectes aquatiques, de même que d’algues et de plantes aquatiques.</p>', '<p>L’accouplement a généralement lieu au printemps ou à l’automne. Au Québec, la période de ponte se déroule essentiellement entre la fin de mai et juillet.</p>\r\n\r\n<p>Le nombre d’œufs pondus est en moyenne de 4, mais peut varier de 1 à 11. Les nouveau-nés, dont le sexe est influencé par la température d’incubation des œufs, émergent du nid à l’automne, soit d’août à novembre.</p>', NULL, '<p>Les principales menaces qui pèsent sur la tortue musquée au Québec sont :</p>\r\n<ul>\r\n  <li>la perte et la modification des habitats;</li>\r\n  <li>la fluctuation des niveaux d’eau lors de la période de nidification;</li>\r\n  <li>les activités nautiques motorisées, qui peuvent causer des blessures ou la mort;</li>\r\n  <li>la pollution de l’eau.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2', 'Menacée', 'Québec', 5),
(839, 'Tortue-molle à épines', 'tortue molle à épines de l\'Est, sous population des Grands Lacs et du Saint-Laurent; tortue à carapace molle', 'Spiny Softshell', 'Soft-Shelled Turtle; Northern Soft-shelled Turtle; Spiny Softshell', 'Apalone spinifera', 'Il est possible que seule la sous-espèce A. s. spinifera soit présente au Québec. Le nom français de cette sous-espèce est \"tortue molle à épines de l\'Est\" et le nom anglais est \"Eastern Spiny Softshell\". Toutefois, le statut d\'espèce menacée a été attribué à l\'espèce et non à la sous-espèce (un trait d\'union a aussi été indiqué dans le nom de l\'espèce, bien que ce dernier soit souvent absent dans les ouvrages de référence).', '<p>Cette tortue d’eau douce dotée d’une carapace souple fréquente les grands plans d’eau. En général, les femelles ne vont sur la terre que pour pondre leurs œufs et rarement à plus de 10 m de la rive. Or, cette espèce peut parcourir 30 km pour trouver un site adéquat pour l’hibernation.</p>', '<p>La tortue-molle à épines vit uniquement en Amérique du Nord. Au Canada, elle est observée seulement à quelques endroits au Québec et en Ontario. Au Québec, les observations récentes sont regroupées au sud, dans la baie Missisquoi, dans le lac Champlain et dans la rivière aux Brochets.</p>', '<p>La seule population connue de tortues-molles à épines au Québec est celle du lac Champlain et de ses affluents. Peu de renseignements sont disponibles pour définir la tendance des populations de tortues‑molles à épines au Québec. La taille des populations de cette espèce repose sur peu d’observations. La viabilité de la population de tortues‑molles à épines est jugée précaire. Elle pourrait disparaître au cours des 50 prochaines années en absence de mesures de protection renforcées.</p>', '<p>La tortue-molle à épines fréquente divers types d’habitats :</p>\r\n<ul>\r\n    <li>Rivières;</li>\r\n    <li>Ruisseaux;</li>\r\n    <li>Lacs;</li>\r\n    <li>Étangs;</li>\r\n    <li>Baies marécageuses peu profondes sablonneuses ou vaseuses avec de la végétation aquatique.</li>\r\n</ul>\r\n\r\n<p>Son choix d’habitats serait lié à l’abondance de nourriture, notamment des écrevisses. Cette tortue utilise des roches plates, des bancs de sable ou autres surfaces afin de s’exposer au soleil.</p>\r\n\r\n<p>Elle hiberne en groupe à l’abri du gel, dans des fosses au fond des rivières dont l’eau est bien oxygénée. Elle privilégie un cours d’eau à faible débit afin de limiter ses dépenses énergétiques. Une bonne partie des individus vivant au Québec hibernent au Vermont.</p>\r\n', '<p>La tortue-molle à épines est principalement carnivore. Son régime alimentaire se compose d’écrevisses et surtout d’insectes. Elle mange également des vers, des mollusques, des têtards, des poissons et parfois des végétaux.</p>', '<p>L’accouplement a lieu entre avril et mai alors que les individus sont rassemblés au site de reproduction. La femelle pond généralement de 10 à 15 œufs en juin. L’éclosion des œufs survient en août ou septembre, après 52 à 95 jours d’incubation, selon l’accumulation de chaleur dans le sol au cours de la saison.</p>\r\n\r\n<p>Les nouveau‑nés, dont le sexe est déterminé génétiquement et non par la température d’incubation comme c’est le cas chez d’autres espèces de tortue, émergent du nid de la fin du mois d’août au début d’octobre.</p>\r\n\r\n<p>Les endroits excavés pour la ponte sont situés à quelques mètres de l’eau, rarement à plus de 10 m, dans des sols graveleux ou sablonneux où la végétation est absente ou clairsemée. Les mêmes sites de ponte sont utilisés d’année en année.</p>', NULL, '<p>Les principales menaces qui pèsent sur la tortue-molle à épines au Québec sont :</p>\r\n<ul>\r\n  <li>la dégradation et la perte des habitats riverains;</li>\r\n  <li>les activités nautiques motorisées qui peuvent leur causer des blessures ou la mort;</li>\r\n  <li>le dérangement par les activités humaines pratiquées dans l’habitat fréquenté par l’espèce, y compris l’utilisation d’hameçons pour la pêche qui peuvent être ingérés par les tortues, leur causant des blessures internes graves;</li>\r\n  <li>la prédation excessive des œufs, surtout par le raton laveur et la mouffette rayée;</li>\r\n  <li>la variation des niveaux d’eau lors de la période de nidification;</li>\r\n  <li>la collecte, la garde en captivité et le commerce illégal.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S1', 'Menacée', 'Québec', 5),
(843, 'Couleuvre tachetée', 'couleuvre annelée; ablabès triangle', 'Eastern Milksnake', 'Milksnake; Thunder Snake; Lightning Snake; House Snake', 'Lampropeltis triangulum', 'Il est possible que la sous-espèce L. t. triangulum ne soit plus reconnue. Auparavant, le nom officiel français de cette sous-espèce était \"couleuvre tachetée\" et le nom anglais était \"Eastern Milksnake\", de sorte que le nom français associé à l\'espèce était \"couleuvre annelée\" et le nom anglais \"Milksnake\", le terme \"couleuvre tachetée\" étant alors associé à la sous-espèce \"L. t. triangulum\" seulement.', '<p>La couleuvre tachetée est le seul serpent du Québec qui se nourrit de petits mammifères. Lorsqu’elle se sent menacée, elle agite le bout de sa queue munie d’écailles modifiées, telles des clochettes. Contrairement au crotale venimeux, elle n’a pas de crochet à venin et est inoffensive pour l’humain.</p>', '<p>En Amérique du Nord, la couleuvre tachetée (sous-espèce triangulum) se trouve du sud du Canada jusqu’au Tennessee et en Caroline du Nord. D’est en ouest, l’aire de répartition s’étend de la Nouvelle‑Angleterre jusqu’en Iowa et au sud‑est du Minnesota.\r\n</p><p>\r\nAu Canada, l’espèce est présente dans toute la région des Grands Lacs, y compris dans le sud‑est de l’Ontario et au sud du Québec. Au Québec, sa répartition est discontinue. Elle se trouve principalement en Outaouais et dans la grande région de Montréal, jusqu’à l’est de la Montérégie.</p>', '<p>Peu de renseignements sont disponibles pour définir la tendance des populations de couleuvres tachetées au Québec. Toutefois, l’espèce demeure vraisemblablement rare, puisque certaines régions ne comptent aucune mention récente.</p>', '<p>La couleuvre tachetée occupe des habitats variés, dont les boisés, les friches, les collines rocheuses, les pâturages et les champs. Elle peut aussi se trouver occasionnellement en milieu forestier ou dans des bâtiments agricoles. Elle se cache parmi la litière de feuilles mortes, sous les pierres, les planches et les troncs, ou encore dans des cavités rocheuses.</p>\r\n\r\n<p>Elle hiberne, de la fin d’octobre à la mi-avril environ, dans des crevasses ou des cavités, naturelles ou artificielles, qui lui évitent le gel.</p>', '<p>La couleuvre tachetée se nourrit principalement de petits mammifères, mais aussi d’autres espèces de couleuvres, de poissons, d’amphibiens, d’oiseaux et de différents invertébrés. Elle est le seul serpent constricteur au Québec : elle tue ses plus grosses proies en enroulant son corps autour d’elles, les étouffant avant de les avaler.</p>', '<p>La couleuvre tachetée est une espèce ovipare, c’est‑à‑dire que la femelle pond des œufs. D’autres espèces sont ovovivipares, c’est‑à‑dire que les femelles vont plutôt mettre au monde des petits déjà formés (espèces ovovivipares).\r\n</p><p>\r\nLa couleuvre tachetée pond ses œufs en juin ou en juillet dans différents substrats, comme des amoncellements de débris végétaux, des troncs d’arbres en décomposition, du fumier ou même dans des tunnels sous le sol. Les femelles partagent parfois un nid commun. L’éclosion a généralement lieu entre août et septembre.</p>', NULL, '<p>Les principales menaces qui pèsent sur la couleuvre tachetée au Québec sont :</p>\r\n<ul>\r\n  <li>le développement urbain et l’intensification de l’agriculture qui entrainent la fragmentation et la perte d’habitats;</li>\r\n  <li>la persécution par les humains;</li>\r\n  <li>les véhicules qui causent leur mort sur les routes.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Québec', 5),
(845, 'Couleuvre brune', 'couleuvre brune de Dekay; couleuvre brune du Nord', 'Dekay’s Brownsnake', 'Brownsnake; Northern Brown Snake; Midland Brown Snake', 'Storeria dekayi', 'Le nom français \"couleuvre brune\" et le nom anglais \"Brownsnake\" sont associés au genre Storeria et ne sont pas assez précis pour désigner l\'espèce. Toutefois, l\'inscription de cette espèce à la liste des espèces susceptibles d\'être désignées comme menacées ou vulnérables a été attribué au nom français simplifié \"couleuvre brune\" et non à son nom précis \"couleuvre brune de Dekay\".', '<p>La couleuvre brune se trouve uniquement dans la région métropolitaine de Montréal et affectionne les habitats ouverts en milieu urbain et périurbain. Ce petit serpent inoffensif pour l’humain n’a pas de crochet à venin. Grande prédatrice de limaces, elle est l’alliée des jardiniers.</p>', '<p>La couleuvre brune se trouve dans l’est de l’Amérique du Nord, du sud‑est du Canada jusqu’au Mexique et au Honduras. Au Canada, la couleuvre brune n’est présente qu’en Ontario et au Québec, où elle occupe la limite nord de son aire de répartition. Au Québec, l’espèce semble restreinte à la région métropolitaine de Montréal.</p>', '<p>Peu de renseignements sont disponibles pour définir la tendance des populations de couleuvres brunes au Québec. Toutefois, les inventaires effectués jusqu’à maintenant au Québec indiquent que sa répartition est discontinue et est restreinte à la région métropolitaine de Montréal. De ce fait, les superficies d’habitats connues sont en déclin parce qu’elles sont converties pour du développement urbain.</p>', '<p>La couleuvre brune vit principalement en milieu urbain et périurbain, dans les champs en friche, les clairières, les prairies, les rivages et autres terrains où il y a abondance d’abris (planches, bûches, pierres, débris, etc.), dont les terrains vagues et les abords des routes et des voies ferrées.</p>\r\n<p>\r\nLa couleuvre brune hiberne de novembre à avril. Elle utilise différents abris souterrains pour éviter le gel, comme des terriers de mammifères, des crevasses rocheuses ou des fondations. Ces habitats peuvent être réutilisés pendant plusieurs hivers successifs. Elle hiberne souvent en groupe et parfois même avec d’autres espèces.</p>', '<p>La couleuvre brune se nourrit principalement de limaces, d’escargots et de vers de terre. Elle peut aussi manger des insectes, des araignées ou de petites grenouilles.</p>', '<p>La couleuvre brune est une espèce ovovivipare, c’est‑à‑dire que la femelle met au monde des petits déjà formés. D’autres couleuvres vont plutôt pondre des œufs (espèces ovipares).</p>\r\n\r\n<p>Cette couleuvre s’accouple généralement au printemps, mais parfois aussi à l’automne, et met bas entre juillet et septembre.</p>', NULL, '<p>Les principales menaces qui pèsent sur la couleuvre brune au Québec sont :</p>\r\n<ul>\r\n  <li>l’urbanisation, qui cause la fragmentation et la perte d’habitats;</li>\r\n  <li>la succession végétale naturelle et l’envahissement des milieux par les plantes exotiques (p. ex. : nerprun) qui transforment les habitats ouverts propices à cette couleuvre (p. ex. : clairière, friche) en habitats fermés auxquels elle n’est pas adaptée (p. ex. : arbustes, forêts);</li>\r\n  <li>les véhicules qui causent leur mort sur les routes.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2', 'Menacée', 'Québec', 5),
(6786, 'Caribou des bois, écotype forestier', 'caribou des bois - population boréale; caribou boréal', 'Woodland Caribou - Woodland Ecotype', 'Woodland Caribou - Boreal ecotype', 'Rangifer tarandus caribou pop. 14', NULL, '<p>Le caribou des bois, écotype forestier, aussi appelé caribou forestier, est une espèce désignée comme vulnérable. </p>\r\n\r\n<p>Le caribou forestier est un animal à déclaration obligatoire. En tout temps, si vous trouvez un caribou blessé ou mort, contactez SOS Braconnage – Urgence faune sauvage au 1 800 463‑2191.</p>\r\n\r\n', '<p>Au Canada, le caribou forestier est établi de la Colombie‑Britannique jusqu’à Terre‑Neuve‑et‑Labrador, ainsi qu’au Yukon et dans les Territoires du Nord‑Ouest. Au Québec, le caribou forestier occupe une bande continue de forêts boréales d’environ 500 km située entre le 49e et le 55e parallèle de latitude nord. De plus, deux populations isolées demeurent au sud du 49e parallèle, celle de Val‑d’Or et celle de Charlevoix. </p>\r\n\r\n<p>Au cours des dernières décennies, le suivi télémétrique Lire le contenu de la note numéro1 des caribous forestiers au Québec a permis d’acquérir des données précises sur la localisation des caribous et sur la façon dont ils se regroupent et utilisent le territoire. Ces données ont permis de distinguer les différentes populations présentes entre le 49e et le 55e parallèle et de délimiter géographiquement leurs aires de répartition. En 2021, 11 populations locales ont été identifiées dans cette zone et deux secteurs d’acquisition de connaissances sur les caribous forestiers ont été définis.</p>', '<p>La limite sud de l’aire de répartition du caribou forestier au Québec remonte vers le nord depuis le milieu du 19e siècle. Le suivi récent montre l’état précaire de l’ensemble des populations. Le taux de survie des caribous femelles ou le taux de survie des faons est faible pour plusieurs populations, ce qui ne permet pas à celles-ci de se maintenir. En 2023, on estimait qu’entre 6 162 et 7 445 caribous forestiers étaient répartis dans l’aire de répartition.</p>', '<p>Le caribou forestier vit dans la forêt boréale. Les types de milieux utilisés dans l’habitat varient en fonction des saisons, de la disponibilité de la nourriture, des risques de prédation et de la tranquillité du milieu. Le caribou a besoin de vastes étendues de milieux peu ou pas perturbés par les activités humaines et, dans une moindre mesure, par les perturbations naturelles, telles que les feux ou les épidémies d’insectes. Il montre une préférence marquée pour les forêts de conifères matures et les forêts anciennes. L’hiver, les caribous se concentrent principalement dans les forêts matures de résineux constituées en grande partie d’épinettes noires et de sapins baumiers, avec ou sans lichens, les landes à lichens ainsi que les tourbières. Durant la mise bas, les femelles tendent à s’isoler et peuvent utiliser des peuplements jeunes et ouverts ainsi que les tourbières en fonction de leur disponibilité. En été, les caribous utilisent une grande variété de milieux dans l’habitat, dont les forêts de conifères matures, et dans une moindre mesure, des milieux plus ouverts offrant des ressources alimentaires diversifiées.</p>\r\n\r\n<p>L’habitat du caribou forestier, population de Charlevoix, est <a href=\"https://www.quebec.ca/agriculture-environnement-et-ressources-naturelles/faune/gestion-faune-habitats-fauniques/habitats-fauniques/proteges-legalement\">protégé légalement</a>.</p>', '<p>Le caribou forestier s’alimente de plantes herbacées et de feuilles d’arbustes au printemps et en été. En hiver, son régime alimentaire est constitué principalement de lichens qui poussent au sol (terricoles) et, dans une moindre mesure, de lichens qui poussent sur les arbres (arboricoles). Les lichens sont une source d’énergie hautement digestible et riche en sucres, mais faible en protéines et en potassium.</p>\r\n<p>Pendant l’hiver, le caribou creuse des cratères d’alimentation lui donnant accès aux lichens. Les conditions d’enneigement, principalement la profondeur et la dureté de la neige, influencent l’énergie dépensée par le caribou pour se déplacer et creuser les cratères d’alimentation.</p>', '<p>Le caribou de la Gaspésie fréquente les hauts sommets des massifs McGerrigle, dont les monts Jacques‑Cartier, et des massifs des Chic‑Chocs (comprenant les monts Albert et Logan). En hiver, le caribou de la Gaspésie utilise également la forêt de conifères matures avoisinant le parc national de la Gaspésie.</p>\r\n\r\n<p>Cette population constitue le dernier vestige du caribou au sud du fleuve Saint-Laurent. À l’époque, le caribou occupait le Nouveau‑Brunswick, la Nouvelle‑Écosse, l’Île‑du‑Prince‑Édouard et la Nouvelle‑Angleterre.</p>\r\n\r\nEtat-situation\r\n<p>Au début des années 1950, la population de caribous de la Gaspésie comptait de 700 à 1 500 individus. Au cours des années 1980, elle était d’environ 250 individus. En octobre 2021, la population était estimée à seulement 38 caribous.</p>\r\n\r\n<p>Outre la chasse qui s’est poursuivie jusqu\'en 1948, ce sont les perturbations de son habitat par les activités humaines (p. ex. exploitation forestière et minière) qui seraient la cause de ce déclin. Aujourd’hui, la précarité du caribou de la Gaspésie serait principalement attribuable au faible effectif de la population, au faible taux de survie des faons et des femelles causé par la prédation du coyote et de l’ours noir ainsi qu’à un habitat de moindre qualité.</p>\r\n\r\nAlimentation\r\n<p>Le régime alimentaire du caribou de la Gaspésie varie selon les saisons. En été, le caribou se nourrit de mousses, de lichens et d’herbacées. En hiver, les lichens qui poussent sur le sol (terricoles) et sur les arbres (arboricoles) dominent son alimentation. Les lichens arboricoles, qu’on trouve dans les forêts matures de haute altitude, sont essentiels à la survie du caribou lorsque les lichens terricoles sont couverts de neige. Les lichens sont une source d’énergie hautement digestible et riche en sucres, mais faible en protéines et en potassium.</p>\r\n\r\nReproduction\r\n<p>La période de rut et d’accouplement du caribou de la Gaspésie a lieu à l’automne, de septembre à novembre.</p>\r\n\r\n<p>La maturité sexuelle est atteinte entre 18 et 30 mois. Toutefois, seuls les mâles présentant un fort gabarit et des bois développés accèdent habituellement aux femelles.</p>\r\n\r\n<p>Les mâles sont polygynes, c’est-à-dire qu’un même mâle peut s’accoupler avec plusieurs femelles au cours d’une même saison de reproduction. Afin de signaler son statut de reproducteur, le mâle brame, secoue les arbustes avec ses bois et affronte ses rivaux dans des rituels (entrecroisement des bois) généralement sans blessure. Pendant le rut, le mâle se nourrit peu. Il garde son énergie pour les affrontements entre mâles et l’accouplement avec les femelles.</p>\r\n\r\n<p>La gestation dure de 225 à 235 jours. Entre la fin de mai et la mi-juin, les femelles se dispersent dans divers types d’habitat pour donner naissance à leurs faons. Les femelles de la population de la Gaspésie, suivies par télémétrie de 2013 à 2016, ont mis bas généralement entre le 20 mai et le 1er juin.</p>\r\n\r\n<p>La plupart des femelles s’accouplent pour la première fois à l’âge de 2,5 ans et donnent naissance à un seul faon par année. La présence de jumeaux est très rare, voire anecdotique chez le caribou. Les femelles du caribou de la Gaspésie préfèrent les secteurs en altitude, généralement rocailleux, accidentés et dépourvus d\'arbres.</p>\r\n\r\n<p>Quelques heures après sa naissance, le faon se dresse sur ses pattes et suit sa mère dans ses déplacements. Dès l’âge de trois jours, il parcourt des distances minimales semblables à celles des adultes, et il commence à brouter après deux semaines de vie. À un an, il accompagne parfois encore la femelle dans les aires de mise bas.</p>\r\n\r\n<p>Le caribou a une longévité typique pour un cervidé, soit entre 8 et 15 ans.</p>\r\n\r\n<p>Les caribous femelles sont moins productifs que les cerfs de Virginie ou les orignaux femelles. Les femelles ne produisent qu’un seul faon par année, alors qu’un cerf de Virginie femelle ou un orignal femelle ont de un à trois faons par année. Les caribous femelles se reproduisent également à un âge plus tardif que les femelles des autres espèces de cervidés. Ces particularités réduisent le potentiel de croissance annuelle et la capacité de renouvellement d’une population de caribous comparativement aux autres espèces de cervidés vivant au Québec.</p>\r\n', NULL, '<p>Les principales menaces qui pèsent sur le caribou forestier au Québec sont :</p>\r\n<ul>\r\n  <li>la destruction, la dégradation et la fragmentation de son habitat, notamment par les coupes forestières et les routes et par des perturbations naturelles comme les feux et les épidémies de tordeuse des bourgeons de l’épinette;</li>\r\n  <li>la prédation accrue sur le caribou qui découle des perturbations de l’habitat. Les changements dans l’habitat favorisent la présence de plus de proies, telles que l’orignal, ce qui permet de soutenir de plus grandes populations de prédateurs, tels que les loups, les ours noirs ou les coyotes;</li>\r\n  <li>la construction de routes et de chemins multiusages qui fragmentent l’habitat et qui facilitent les déplacements des prédateurs et leur accès au caribou;</li>\r\n  <li>les activités récréotouristiques et industrielles, qui peuvent déranger les caribous ou les amener à abandonner certains secteurs de leur habitat;</li>\r\n  <li>le braconnage et, dans certaines régions, la récolte à des fins alimentaires, rituelles ou sociales par des membres de certaines communautés autochtones.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2S3', 'Vulnérable', 'Québec', 2),
(13990, 'Éperlan arc-en-ciel, pop. du sud de l\'estuaire du Saint-Laurent', '', 'Rainbow Smelt - Southern St. Lawrence Estuary population', NULL, 'Osmerus mordax pop. 1', 'Population du sud (considérée dulcicole car présente dans les lacs et rivières). Espèce des côtes Atlantique Nord introduite par les canaux d\'eau et dispersée ensuite comme des appâts vivants.', '<p>L’éperlan arc-en-ciel est un petit poisson de couleur argentée qui vit en banc. Des analyses ont mis en évidence que la population de la rive sud de l’estuaire du Saint-Laurent est une population distincte.</p>', '<p>La population d’éperlan arc-en-ciel du sud de l’estuaire du Saint-Laurent vit dans la portion sud de l’estuaire du Saint-Laurent entre Lévis et Matane.</p>', '<p>La population d’éperlan arc-en-ciel de la rive sud de l’estuaire du Saint-Laurent a été désignée vulnérable. Cette désignation était justifiée par :</p>\r\n<ul>\r\n  <li>le déclin important de la population observé au cours des 30 dernières années;</li>\r\n  <li>l’abandon de la plus importante frayère située dans la rivière Boyer;</li>\r\n  <li>le nombre limité de frayères utilisées.</li>\r\n</ul>\r\n<p>Une analyse réalisée en 2016 à partir de divers indicateurs suggère que la tendance de la population d’éperlan arc-en-ciel du sud de l’estuaire du Saint-Laurent n’est plus à la baisse. Son abondance se serait stabilisée, bien qu’elle soit toujours plus faible qu’avant le déclin de la population. Le rétablissement de cette population demeure fragile puisque sa survie semble dépendre surtout d’une seule frayère, soit celle de la rivière Ouelle.</p>\r\n', '<p>L’éperlan arc-en-ciel s’observe en bancs dans la colonne d’eau. Cette espèce utilise des habitats avec des salinités variées. La population du sud de l’estuaire du Saint-Laurent est confinée surtout aux battures et aux baies peu profondes de cette rive.</p>', '<p>L’éperlan arc-en-ciel se nourrit d’une grande variété d’invertébrés. Il mange entre autres des crustacés, des vers, des mollusques et de petits poissons.</p>', '<p>L’éperlan arc-en-ciel fraie au printemps. Un grand nombre de poissons migrent en masse vers les sites de fraie en eau douce. Les œufs sont libérés directement dans le courant. Ils vont ensuite se déposer sur le fond où ils se fixent grâce à une enveloppe adhérente. \r\n</p><p>\r\nLa population du sud de l’estuaire du Saint-Laurent est connue pour frayer dans différents tributaires du Saint-Laurent : le ruisseau de l’Église et les rivières Ouelle, Fouquette, du Sud, Kamouraska et du Loup. Cette population se reproduirait aussi à même le fleuve Saint-Laurent, sur les hauts fonds situés à la hauteur de Beaumont, près de Lévis.</p>', NULL, '<p>Les principales menaces qui pèsent sur l’éperlan arc-en-ciel au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution agricole, urbaine et industrielle qui nuirait à la qualité des frayères;</li>\r\n  <li>les changements climatiques, à cause des variations dans les régimes d’écoulement et de température qui pourraient influencer la survie des jeunes de l’année;</li>\r\n  <li>le braconnage, à cause du non-respect des prises quotidiennes.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Déléguée au Québec', 1),
(14059, 'Omble chevalier oquassa', 'oquassa', 'Arctic Char oquassa', 'Landlocked Arctic Char', 'Salvelinus alpinus oquassa', 'Toutes les populations isolées en eau douce de l\'omble chevalier (Salvelinus alpinus) appartiennent à la sous-espèce Salvelinus alpinus oquassa.', '<p>L’omble chevalier oquassa est une sous-espèce de l’omble chevalier. Il est présent exclusivement dans certains lacs du Québec, du Nouveau‑Brunswick, de Terre‑Neuve‑et‑Labrador et du Maine. Ces populations sont isolées en eau douce depuis le retrait des glaciers, il y a environ 12 000 ans. Elles sont d’une grande valeur sur le plan génétique et patrimonial.</p>', '<p>L’omble chevalier oquassa est présent uniquement dans certains lacs du Québec, de Terre‑Neuve‑et‑Labrador, du Nouveau‑Brunswick et du Maine. Au Québec, il est présent dans une partie des régions de la Gaspésie, du Bas‑Saint‑Laurent, du Saguenay‑Lac‑Saint‑Jean, de la Capitale‑Nationale, de la Mauricie, de Lanaudière et de l’Outaouais.</p>', '<p>L’omble chevalier oquassa est en voie de devenir une « espèce faunique vulnérable ». Bien que plus de 300 lacs du Québec l’abritent, son abondance n’y est que généralement peu élevée en comparaison avec les autres salmonidés indigènes.</p>', '<p>L’omble chevalier oquassa fréquente les eaux froides des lacs profonds des régions montagneuses. L’été, l’espèce s’isole du réchauffement de l’eau de la surface en descendant dans les zones plus profondes des lacs. En hiver, comme la température de l’eau redevient uniforme dans le lac, il regagne l’ensemble de la colonne d’eau jusqu’en surface.</p>', '<p>L’omble chevalier oquassa mange des larves aquatiques d’insectes, des crustacés et des poissons.</p>', '<p>L’omble chevalier oquassa fraie entre septembre et décembre selon les lacs et les régions, principalement en fonction de la température de l’eau. En lac comme en rivière, il fraie sur des zones alimentées par des sorties d’eaux souterraines avec une bonne exposition au vent, ce qui a pour effet de balayer le substrat et de bien oxygéner les œufs.\r\n</p><p>\r\nL’omble chevalier oquassa ne construit pas de nid. Les œufs se logent dans les interstices du substrat (roche et gravier) où ils sont protégés des prédateurs. Plusieurs mâles peuvent féconder les œufs d’une même femelle. Il n’y a pas de soins parentaux après la fécondation. En pisciculture, les œufs éclosent de 79 à 122 jours après la ponte, à des températures variant de 3 à 11 ⁰C. Ces dernières informations ne sont pas connues en milieu naturel pour cette espèce.\r\n</p><p>\r\nLa maturité sexuelle est généralement atteinte vers 5 ans chez le mâle, et entre 4 et 8 ans chez la femelle. L’omble chevalier oquassa pourrait frayer chaque année. L’âge et la taille à la maturité sexuelle, la période de reproduction, le choix du site de fraie ou encore la fréquence des fraies sont variables entre les populations.</p>', NULL, '<p>Les principales menaces qui pèsent sur l’omble chevalier oquassa au Québec sont :</p>\r\n<ul>\r\n  <li>la pollution urbaine et forestière, qui engendre l’accumulation de sédiments dans le substrat de fraie, l’eutrophisation et l’acidification des lacs;</li>\r\n  <li>le braconnage;</li>\r\n  <li>les changements climatiques, qui causent des variations et une augmentation de la température de l’eau.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S2S3', 'Vulnérable', 'Déléguée au Québec', 1),
(14974, 'Pluvier siffleur melodus', 'pluvier siffleur de la sous-espèce melodus; pluvier criard; gravelot siffleur; tête de pipe', 'Piping Plover melodus', 'Sand Piper; Tee-o; Beach Flea; Pale Ring-neck', 'Charadrius melodus melodus', '', '<p>Le pluvier siffleur est un petit oiseau de rivage présent aux îles de la Madeleine. Il s’agit d’une espèce menacée.</p>', '<p>Au Québec, cet oiseau niche seulement sur les plages des îles de la Madeleine. Il se reproduisait auparavant, de façon très locale, sur les grèves de la Côte‑Nord (jusqu’en 1986) et en Gaspésie, dans la baie des Chaleurs (en 1929 et en 1968).</p>', '<p>Depuis plusieurs décennies, la population nord-américaine de cette espèce a connu un important déclin. En 2013, on comptait 389 adultes de la sous-espèce melodus au Canada. Cette population aurait décliné de 23 % entre 2003 et 2013.</p>\r\n\r\n<p>L’ampleur du déclin de la population de pluvier siffleur au Québec est toutefois difficile à déterminer. Aux îles de la Madeleine, la population compterait actuellement moins de 50 couples.</p>', '<p>Le pluvier siffleur fréquente les plages de sable où pousse de la végétation éparse parmi de petits galets, du gravier, des coquillages et des morceaux de bois présents en faible quantité.</p>', '<p>Le pluvier siffleur se nourrit de vers marins, d’insectes comme les larves de mouches et les coléoptères, de petits crustacés, des mollusques et d’autres petits invertébrés marins.</p>', '<p>Le pluvier siffleur peut se reproduire dès l’âge d’un an. Les pluviers siffleurs atteignent habituellement leurs territoires de nidification entre la fin de mars et le début de mai. Le nid est une simple dépression dans le sable.\r\n</p><p>\r\nUne ponte contient généralement quatre œufs. L’incubation dure de 26 à 28 jours; les œufs éclosent vers la fin de mai ou au début de juin. Les deux parents participent à l’incubation des œufs et s’occupent des oisillons. Le pluvier siffleur produit généralement une couvée par année, mais il peut en produire une deuxième si la première est détruite tôt en saison.</p><p>\r\n\r\nLes pluviers siffleurs quittent les sites de nidification vers la mi‑juillet pour se rendre à leurs sites d’hivernage qui s’étendent de la Caroline du Nord, le long de la côte est de l’Amérique du Nord, jusque sur les côtes du golfe du Mexique.</p>', NULL, '<p>Les principales menaces qui pèsent sur le pluvier siffleur melodus sont :</p>\r\n<ul>\r\n  <li>la prédation (principalement des œufs et des oisillons);</li>\r\n  <li>le dérangement par les activités récréatives sur les plages, dont le passage des véhicules tout-terrain;</li>\r\n  <li>la destruction et la dégradation de son habitat.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3);
INSERT INTO `especes` (`id`, `nom_francais`, `autres_noms_francais`, `nom_anglais`, `autres_noms_anglais`, `nom_scientifique`, `commentaires`, `description`, `repartition`, `etat_situation`, `habitat`, `alimentation`, `reproduction`, `comportement`, `menaces`, `statuts_des_populations`, `rang_S`, `statut_LEMV`, `competence_principale`, `groupe_id`) VALUES
(15297, 'Faucon pèlerin anatum', 'pèlerin; collier blanc; faucon ordinaire; faucon des perdrix', 'Peregrine Falcon - anatum/tundrius population', 'Peregrine; Pinnacle Hawk; Great-footed Hawk; Ledge Hawk', 'Falco peregrinus pop. 1', NULL, '<p>Le faucon pèlerin est l’oiseau le plus rapide au monde. Au sommet de la chaîne alimentaire, il est sensible à l’accumulation de produits toxiques dans ses tissus. Auparavant très précaire, le nombre de faucons est aujourd’hui en hausse, notamment grâce à l’interdiction d’utiliser le DDT, un pesticide nocif.\r\n</p><p>\r\nLe faucon pèlerin est un animal à déclaration obligatoire. En tout temps, si vous trouvez un faucon pèlerin blessé ou mort, contactez SOS Braconnage — Urgence faune sauvage au 1 800 463‑2191.</p>', '<p>Le faucon pèlerin vit partout dans le monde, sauf en Antarctique, en Nouvelle‑Zélande, en Islande et dans les îles du Pacifique oriental. Deux sous-espèces du faucon pèlerin sont présentes au Québec : l’une occupe l’extrême nord de la province (Falco peregrinus tundrius), principalement autour de la baie d’Ungava, et l’autre fréquente le sud de la province (Falco peregrinus anatum).</p>', '<p>Le faucon pèlerin a subi un déclin alarmant de la fin des années 1940 jusqu’aux années 1960. L’utilisation massive de pesticides organochlorés (p. ex., DDT) et leur accumulation dans la chaîne alimentaire ont engendré des problèmes de reproduction comme la stérilité, l’amincissement de la coquille des œufs, la mort embryonnaire ou le comportement anormal des parents.\r\n</p><p>\r\nDepuis la fin des années 1970, l’utilisation de ces pesticides en Amérique du Nord est interdite et les populations de faucons pèlerins se portent mieux.\r\n</p><p>\r\nDes études génétiques effectuées sur le faucon pèlerin au Canada suggèrent que les différences génétiques entre les sous-espèces anatum et tundrius seraient minces. Ces différences seraient attribuées à la nature limitée du patrimoine génétique utilisé pour les introductions de faucons pèlerins qui ont été effectuées afin de redresser les populations en Amérique du Nord, au Canada et au Québec à la suite de l’effondrement des populations causé par le DDT.</p>', '<p>La majorité des faucons pèlerins du Québec sont migrateurs : ils fréquentent principalement le territoire québécois durant la période de nidification. Toutefois, une proportion de plus en plus importante des faucons pèlerins qui nichent dans le sud de la province hivernent maintenant au Québec.\r\n</p><p>\r\nPour installer son nid, le faucon pèlerin utilise les falaises situées près d’un plan d’eau ou des structures artificielles (immeubles, ponts et carrières).\r\n</p><p>\r\nPour chasser, le faucon pèlerin survole les cours d’eau, les marais, les plages, les vasières et les champs.</p>', '<p>Le faucon pèlerin est un rapace carnivore qui vit le jour (diurne). Il se nourrit principalement d’oiseaux de rivage, de canards, de pigeons bisets et de petits mammifères comme des lemmings ou, occasionnellement, des souris. Il saisit généralement ses proies en piqué, à une vitesse pouvant atteindre plus de 300 km/h.</p>', '<p>La période de ponte et d’incubation du faucon pèlerin s’étend du début avril jusqu’à la fin juillet. La couvée compte en moyenne de 2 à 4 œufs. Il ne construit pas de nid, mais il choisit ou creuse une dépression peu profonde dans laquelle il peut amasser quelques matériaux de nidification.\r\n</p><p>\r\nLes deux adultes participent à l’élevage des jeunes, bien que la femelle en assure la majeure partie. Le faucon pèlerin peut revenir année après année au même site de nidification, dont il défend le territoire.</p>', NULL, '<p>Les principales menaces qui pèsent sur le faucon pèlerin au Québec sont :</p>\r\n<ul>\r\n  <li>l’utilisation de pesticides organochlorés dans les aires d’hivernage situées en Amérique du Sud;</li>\r\n  <li>le dérangement par les activités humaines, dont l’escalade et la randonnée pédestre à proximité des nids;</li>\r\n  <li>la pollution;</li>\r\n  <li>les changements climatiques (p. ex., augmentation du nombre d’événements météorologiques violents provoquant la mort des œufs ou des jeunes, changements dans la dynamique des populations d’insectes piqueurs pouvant causer la mort des jeunes faucons);</li>\r\n  <li>l’intensification de l’agriculture, dont le recours aux pesticides;</li>\r\n  <li>la réduction de la diversité des cultures qui diminue la quantité de proies.</li>\r\n</ul>\r\n<p>Afin d’éviter un nouveau déclin de l’espèce, il importe de protéger les sites de nidification, d’améliorer les efforts de suivi des populations et de permettre la surveillance accrue des menaces émergentes comme l’entrée sur le marché de nouveaux pesticides problématiques.</p>\r\n', 'Reproducteur', 'S4B', 'Vulnérable', 'Québec', 3),
(17067, 'Salamandre pourpre, pop. des Adirondacks et des Appalaches', 'salamandre pourpre du Nord; lézard d\'eau', 'Spring Salamander - Adirondack / Appalachian population', 'Northern Spring Salamander; Purple Salamander; Northern Purple Salamander', 'Gyrinophilus porphyriticus pop. 2', NULL, '<p>La salamandre pourpre n’a pas de poumons ni de branchies : elle respire grâce à sa peau perméable à l’air et à l’eau. Cette grande salamandre fréquente les ruisseaux des Appalaches à l’eau claire, froide et bien oxygénée, sans contaminants ni sédiments.</p>', '<p>La salamandre pourpre vit uniquement dans l’est de l’Amérique du Nord. Elle se retrouve le long de la chaîne de montagnes des Appalaches. Au Canada, elle est présente dans le sud-est du Québec, soit sa limite nord de son aire de répartition. Au Québec, la salamandre pourpre est observée au sud du fleuve Saint‑Laurent, principalement à l’ouest de la rivière Chaudière. En 2020, la présence de populations à l’est de cette rivière a été confirmée.</p>', '<p>En 2021, le nombre de populations de salamandres pourpres était estimé à 331 pour l’ensemble du Québec. Comme près de 40 % d’entre elles sont très peu documentées, il est difficile d’en évaluer les chances de survie à moyen terme. Toutefois, la moitié des populations auraient de bonnes chances de persister dans les 20 prochaines années, si les conditions actuelles sont maintenues ou améliorées.</p>', '<p>La salamandre pourpre occupe les cours d’eau permanents ou intermittents coulant dans les forêts en milieu montagneux. Elle préfère des ruisseaux à courant moyen, ayant une eau claire, froide et bien oxygénée, avec un substrat graveleux ou rocheux. Elle vit en amont de massifs montagneux, surtout sur les berges avec des roches plates. Les adultes restent habituellement dans le ruisseau ou à moins de 2 m de celui-ci, mais peuvent se déplacer en forêt. Elle hiberne au fond des ruisseaux ou dans des cavités sous la berge.</p>', '<p>La salamandre pourpre se nourrit de petits insectes aquatiques, de vers, de crustacés et de petites salamandres, incluant parfois des semblables.\r\n</p><p>\r\nCe comportement de cannibalisme est variable au sein de l’espèce. Dans les populations nordiques, les salamandres ne représentent qu’une petite fraction de la diète de l’espèce.</p>', '<p>L’accouplement se déroule au printemps et à l’automne. Les œufs sont déposés dans l’eau courante un an plus tard. Les femelles pondent leurs œufs en une seule couche, sous de grosses roches, d’autres abris submergés ou partiellement enfouis dans la berge. Le nombre d’œufs pondus varie de 9 à 132. La période larvaire s’étend de 3 à 6 ans. La première reproduction a lieu en moyenne à 5 ans et les reproducteurs peuvent atteindre l’âge de 10 ans.</p>', NULL, '<p>Les menaces qui pèsent sur la salamandre pourpre au Québec sont :</p>\r\n<ul>\r\n  <li>l’apport de sédiments fins liés aux traverses de cours d’eau et aux champs agricoles qui provoque la détérioration des ruisseaux qu’elle fréquente;</li>\r\n  <li>la modification de l’écoulement naturel de l’eau (p. ex., ouvrages de retenue d’eau et modification du drainage à des fins agricoles ou forestières);</li>\r\n  <li>le développement du réseau routier qui dégrade et fragmente des habitats de l’espèce, en plus de causer la mort par collision;</li>\r\n  <li>l’exploitation forestière qui réduit le couvert forestier, ce qui influence négativement les conditions d’humidité et de température optimales pour l’espèce.</li>\r\n</ul>\r\n<p>Comme elle respire seulement par la peau, la salamandre pourpre est particulièrement sensible à toute modification ou détérioration de son habitat. De plus, elle ne tolère pas les milieux secs.</p>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Québec', 4),
(30035, 'Couleuvre d\'eau du Nord', NULL, 'Northern Watersnake', NULL, 'Nerodia sipedon sipedon', NULL, '<p>La couleuvre d’eau est la plus grande couleuvre du Québec. Inoffensive, elle ne mord que si elle est manipulée et elle n’a pas de crochets à venin. Surtout aquatique, elle peut être aperçue en train de se réchauffer au soleil sur la végétation dans les marais, les étangs ou les baies peu profondes.</p>', '<p>La couleuvre d’eau occupe la majeure partie de l’est des États-Unis, allant du centre jusqu’à la côte est. Au sud, elle se trouve jusqu’au Mississippi. Au Canada, la couleuvre d’eau est présente seulement en Ontario et au Québec, où elle occupe la limite nord de son aire de répartition. Au Québec, elle a été observée dans la vallée de la Gatineau, dans les basses-terres du Saint‑Laurent et dans les Laurentides.</p>', '<p>Dans les régions de Montréal et de la Montérégie, il reste seulement quelques populations de couleuvres d’eau de faible taille, dont celles du lac des Deux Montagnes. Dans ces régions, les populations sont en déclin et sont isolées les unes des autres. Cependant, elle semble assez commune en Outaouais.</p>', '<p>La couleuvre d’eau est une espèce étroitement associée au milieu aquatique. Excellente nageuse, elle fréquente le bord des rivières, des ruisseaux, des étangs et des lacs. Elle peut se trouver le long des rives rocheuses, tantôt étendue sur des pierres, parfois abritée en dessous, ou encore dans un buisson ou sur une branche près de l’eau.\r\n</p><p>\r\nElle hiberne sur la terre ferme dans d’anciens terriers, des amas de pierres, des talus de remplissage ou des fissures qui lui permettent d’éviter le gel. Ces abris sont utilisés pendant plusieurs années.</p>', '<p>La couleuvre d’eau se nourrit principalement de poissons, de grenouilles adultes, de têtards, de salamandres, d’écrevisses, de limaces et de vers de terre. Elle chasse à découvert tout en se déplaçant.</p>', '<p>La couleuvre d’eau est une espèce ovovivipare, c’est‑à‑dire que la femelle met au monde des petits déjà formés. D’autres couleuvres vont plutôt pondre des œufs (espèces ovipares). Cette couleuvre s’accouple généralement à la fin de mai et elle a ses petits à la fin de l’été.</p>', NULL, '<p>Les principales menaces qui pèsent sur la couleuvre d’eau au Québec sont :</p>\r\n<ul>\r\n  <li>le développement industriel et résidentiel et les travaux de stabilisation des berges qui entrainent la fragmentation et la perte d’habitats;</li>\r\n  <li>la persécution par les humains;</li>\r\n  <li>la pollution environnementale comme les résidus toxiques de pesticides.</li>\r\n</ul>\r\n', 'Toute l\'année', 'S3', 'Vulnérable', 'Québec', 5),
(30091, 'Pie-grièche migratrice, sous-espèce de l\'Est', 'pie-grièche migratrice de la sous-espèce migrans', 'Loggerhead Shrike, Eastern subspecies', '', 'Lanius ludovicianus pop. 1', '', '<p>La pie-grièche migratrice est un oiseau chanteur de taille moyenne qui fréquente les prairies. Au Québec, cette espèce est désignée menacée.</p>', '<p>La pie-grièche migratrice niche depuis l’Alberta, la Saskatchewan et le Manitoba jusqu’au nord du Mexique. Plus à l’est, l’espèce est présente dans le sud de l’Ontario.</p><p>\r\n\r\n<p>Au Québec, la nidification de l’espèce était fréquente entre 1980 et 1995 : à l’ouest de Gatineau, au nord-est de Montréal et à l’est de Cap-de-la-Madeleine.</p><p>\r\n\r\nSa répartition en hiver est peu connue, mais l’espèce semble surtout occuper le centre-sud des États-Unis et le Mexique.<p>', '<p>La pie-grièche migratrice est généralement en déclin et a même disparu de plusieurs secteurs de son ancienne aire de répartition.</p><p>\r\n\r\nAu début du 20e siècle, la pie-grièche migratrice était considérée comme un oiseau nicheur commun dans le sud-ouest du Québec. Or, le nombre d’oiseaux de cette espèce a considérablement chuté au cours des dernières décennies. Au Québec, seulement 19 cas de nidification ont été rapportés entre 1980 et 1995, et la pie-grièche migratrice n’a jamais été trouvée nichant dans plus de trois sites différents pendant une même année. La population nicheuse est donc estimée à un nombre infime de couples : il y aurait moins de 10 individus présents au Québec.</p>', '<p>La pie-grièche migratrice habite les milieux très ouverts, principalement les pâturages où l’herbe est courte, parsemés d’arbustes et de petits arbres dans lesquels elle peut nicher et se percher.</p>', '<p>La pie-grièche s’alimente de gros insectes, de petits oiseaux, de grenouilles et de rongeurs. Elle tue ses proies à l’aide de son bec recourbé et a l’habitude de les empaler sur des épines ou d’autres objets pointus.</p>', '<p>La pie-grièche migratrice se reproduit au printemps. Les deux adultes contribuent à réunir les matériaux nécessaires à la construction du nid par la femelle.</p>\r\n\r\n<p>Pour construire son nid, la femelle choisit un arbre ou un arbuste isolé ou encore elle l’installe le long d’une clôture ou d’une haie. Elle couve ses quatre à six œufs pendant environ 16 jours. Pendant ce temps, elle est nourrie par le mâle. Les deux adultes nourrissent et protègent les petits au nid jusqu’à ce qu’ils aient appris à chasser.</p>', NULL, '<p>Les principales menaces qui pèsent sur la pie-grièche migratrice sont :</p>\r\n<ul>\r\n  <li>la conversion d’anciens pâturages en champs servant à la culture céréalière, ce qui cause une perte d’habitats;</li>\r\n  <li>la compétition avec d’autres oiseaux qui occupent les mêmes habitats;</li>\r\n  <li>l’intoxication aux pesticides par l’intermédiaire de ses proies;</li>\r\n  <li>l’utilisation de pesticides en milieu agricole, qui réduit l’abondance des proies;</li>\r\n  <li>la prédation (p. ex. par les chats errants);</li>\r\n  <li>les collisions avec des véhicules.</li>\r\n</ul>\r\n', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3),
(30096, 'Bruant sauterelle pratensis', 'bruant sauterelle, sous-espèce de l\'Est, bruant des savanes; oiseau canne; pinson des sauterelles; pinson sauterelle', 'Grasshopper Sparrow pratensis', 'Savanna Bird; Grass-dodger; Grass Pink; Savanna Finch', 'Ammodramus savannarum pratensis', NULL, '<p>Le nom du bruant sauterelle vient de son chant qui rappelle celui d’un insecte. Cette espèce menacée au Québec est un allié des agriculteurs puisqu’elle consomme de grandes quantités de criquets.</p>', '<p>Au Québec, le bruant sauterelle se reproduit très localement, dans le sud des basses-terres du Saint‑Laurent longeant une portion de la rivière des Outaouais, et en Montérégie, près de Montréal. Il aurait aussi été signalé dans d’autres régions du Québec, jusqu’au Saguenay. Il hiverne dans le sud des États‑Unis, au Mexique et en Amérique centrale.</p>', '<p>Depuis 1965, les populations nord-américaines de l’espèce auraient grandement fluctué, notamment dans le nord‑est. Au Québec, les bruants sauterelles sont plus nombreux en Outaouais que dans la région de Montréal. Les populations de l’Outaouais colonisent d’ailleurs de nouveaux sites. Les espèces de la grande région de Montréal perdent des sites utilisés au profit du développement urbain et industriel et à cause de la modification des types de cultures.</p>', '<p>Le bruant sauterelle niche dans un habitat doté d’un sol bien drainé et d’un couvert clairsemé d’herbacées comme les pâturages, les prés de fauche et les prairies naturelles. L’hiver, il utilise le même genre de milieux.</p>', '<p>Le bruant sauterelle mange surtout des criquets.</p>', '<p>Le bruant sauterelle est monogame et retourne généralement au même site de nidification chaque année. Les mâles arrivent avant les femelles au site de nidification au début de mai. La femelle pond généralement de 4 à 5 œufs et peut produire deux nichées par année. Les deux parents élèvent et nourrissent les jeunes.</p>', NULL, '<p>Les principales menaces qui pèsent sur le bruant sauterelle pratensis sont :</p>\r\n<ul>\r\n  <li>la perte d’habitats causée par la conversion des cultures fourragères et des pâturages en cultures intensives;</li>\r\n  <li>la fragmentation de l’habitat qui entraîne plus de prédateurs;</li>\r\n  <li>le fauchage tôt durant la période de reproduction.</li>\r\n</ul>', 'Reproducteur', 'S1', 'Menacée', 'Environnement et Changement climatique Canada', 3);
